/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200225-8","meetingId":"r02-cm02","date":"2020年2月25日","dateIso":"2020-02-25","committee":"建設委員会","time":"午前１０時００分～午後 ３時４３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を101件整理しています。","topics":[{"id":"topic-01","title":"第１８号議案 品川区営住宅条例の一部を改正する条例","agenda":"第１８号議案 品川区営住宅条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２点伺いますけれども、まず、法定利率が引き下げられた根本的な理由は何なのかということが１つと、それと、利息（延滞金）が発生する明渡請求とは、どのようなケースを差すのか伺いたいと思います。","respondent":"森住宅課長","answer":"不動産を持っているとか、そういった不正な形で入居された方に対して、損害賠償という形でいただくための利率の変更ということになります。法定利率に関しましては、今、５％としているものを３％に引き下げるという形になりますし、３年ごとに見直すという形で考えております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"法定利率が引き下げになった理由についてお伺いしたいと思います。","respondent":"森住宅課長","answer":"引き下げられたことに関してですけれども、年５％というのは民法制定時の市中金利をもとに設定をされているものです。基準貸付利率、その利率は５％から３％へ引き下げられ、また市中金利の動向によって３年ごとに見直しを図るというふうな改定がなされたところです。","id":"exchange-002"},{"speaker":"松本委員","kind":"質問","question":"今、年５％という割合で定められていたものを法定利率に改めたというお話がありました。例えば３年後に３％から２％に引き下げられた場合は、法定利率と定めるので、自動的にスライドされるというような理解でよろしいのか尋ねました。","respondent":"森住宅課長","answer":"委員ご指摘のとおり、民法で３年ごとに見直しということになりますので、自動的に条例にかかわるものも見直されるということになります。","id":"exchange-003"},{"speaker":"松本委員","kind":"質問","question":"今回は区営住宅の条例ですけれども、区民住宅のほうはどうなるのかもお伺いできればと思います。","respondent":"森住宅課長","answer":"区営住宅につきましては、国から示されております公営住宅の標準条例に基づいて条例化しているものですけれども、区民住宅についてはそういった規定がもともとなく、特に不正入居によってというようなことでの損害賠償という規定は設けていないところであります。","id":"exchange-004"},{"speaker":"松本委員","kind":"質問","question":"今回は、不正入居ということかと思うのですけれども、賃料の滞納などについてはどうなっていますか尋ねました。","respondent":"森住宅課長","answer":"今回の３％の法定利率の対象につきましては、第３３条第１項第１号の不正の行為により入居したときとの損害賠償ということで考えております。使用料を３カ月以上滞納したときという形のものもありますが、この法定利率は適用されず…","id":"exchange-005"},{"speaker":"松本委員","kind":"質問","question":"ということは、一応、使用料の未払い、賃料の未払いについては、特に利息などは載せていないという理解でよろしいか尋ねました。","respondent":"森住宅課長","answer":"はい、ご指摘のとおりです。","id":"exchange-006"}]},{"id":"topic-02","title":"第１９号議案 品川区手数料条例の一部を改正する条例","agenda":"第１９号議案 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"別紙１の(1)ですけれども、この制度の対象となるような建築物は、現在、区内にどれだけあるのでしょうか。伺いたいと思います。","respondent":"長尾建築課長","answer":"今回、現時点でその制度を使えそうな建物の見込みも特に今のところはございません。供給型熱源機器等ということで、例えば太陽光パネルの発電設備であったり、空調用の温水とか冷水を供給するような設備といったものが挙げられます。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"(2)のほうですけれども、1)の住宅に係る省エネ性能の評価方法についてとありますが、全体の申請数のうちの何％ぐらいを占めるのでしょうか。ほぼ必ず行っているものなのか、そうではないのかなども含めて伺いたいと思います。","respondent":"長尾建築課長","answer":"そのうち、例えばですけれども、低炭素建築物の認定を受けるような建物は、そのうちの約２０棟前後程度です。年間でおよそ２００から３００程度はありますので、２割、３割ぐらいはこの制度改正で申請上の影響を受けるようなところかと考えております。","id":"exchange-008"},{"speaker":"安藤委員","kind":"確認","question":"新築数は１,０００棟あり、２割から３割にあたる２０棟程度が低炭素建築物の認定を受ける、今回の対象になるということでよろしいでしょうか。そこだけ確認だけお願いします。","respondent":"長尾建築課長","answer":"はい、そのとおりです。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"確認","question":"確認ですけれども、今回、別紙１のほうでは、括弧書きで手数料見直しに係るものとなっているのですが、内容を見ると、いわゆる簡素化される、特例が拡充されるという、使い勝手がよくなるということの改正で、手数料自体の金額は変わらないということでよろしいのか尋ねました。","respondent":"長尾建築課長","answer":"委員おっしゃるように、今回は制度の拡充がなされますけれども、手数料条例上の金額が具体的に変わるというようなところはございません。","id":"exchange-010"},{"speaker":"吉田委員","kind":"確認","question":"こういう省エネの建物を建てる方向へ誘導するものであるというふうに理解してよろしいのでしょうかということが１つ。こういう計算とかにとても不得手なものですから確認なのですが、正確性をどうやって担保するのか、いかがか尋ねました。","respondent":"長尾建築課長","answer":"国の方でこれまで制度を運用してきた中での実績値を踏まえ入力を削減しても大丈夫なところを極力項目数を減らして入力手間を省けるようにしておりま…そういった形で正確性の担保は図られているところです。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"ただ、その基準が厳しくなるよりも、手間の簡素化が事業者にとってはメリットであるという理解でよろしいでしょうか。全然実務的なことがわからないのですけれども、これから建てる人に対しての促しというのか、その辺についてもお答えほしいと求めました。","respondent":"長尾建築課長","answer":"今後、今のところ、来年の４月ごろを予定しておりますが、今回の誘導策ではなくて、規制にかかわる部分の法改正の施行があります。その環境の中では、今回、簡素化された評価方法もより説明しやすくなる環境づくりに貢献してくることになると考えております。","id":"exchange-012"},{"speaker":"吉田委員","kind":"確認","question":"済みません、１個聞き忘れました。この共用部分が評価から外れるということについての省エネ性能との関係を確認させてください。","respondent":"長尾建築課長","answer":"例えば空調設備であるとか、照明設備もそうですけれども、そういった設備を住戸内と同じぐらい入れるという場合は少ない状況もあるかと思います。そういうところを踏まえまして、計算対象からは除外してもいいだろうということで、今回の緩和につながっております。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"例えば建物で、昔は１０年保証など当たり前ではなかったけれども、今は当たり前ではないですか。そこら辺のところを教えていただきたい。","respondent":"長尾建築課長","answer":"最終的に処分したり、相続したりというところまで含めて、その一連の流れの中で国のほうでもそういったメリットも準備しております。基本的には省エネ性能の優れた建築物がより普及していくような流れが、今、つくられていくところかと捉えております。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"それが限りなくゼロに等しくなれば変わらないのではないのかと、わからないのだけれども、そういうものがあるではないですか。建てる方のほうのメリットがよくわからないので、ぜひそこら辺が、わかるようにしてほしいなということだけお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"}]},{"id":"topic-03","title":"第２６号議案 専決処分の承認を求めること","agenda":"第２６号議案 専決処分の承認を求めること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"伺いたいのは、この雇上会社の運転手の勤務についてですけれども、昨年の一般質問等では、休憩時間もまともにとれない等の実態も紹介されていました。伺いたいと思います。","respondent":"工藤品川区清掃事務所長","answer":"これは区の直営車も同じですが、勤務時間終了を全て把握しておりまして、大体１５時３０分前後には終了するような形になってあります。私どもの職員も、休憩時間を１時間とるわけでございまして、昼休みにつきましても取得はされているというふうに認識しています。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。そこからさらに自分の会社に戻るということもあって、そこまで含めての勤務時間ということでよろしいのかと伺いましたので、いかがか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"雇上会社につきましては、区のほうで就業を終えて、それぞれの雇上会社に戻るです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと今お伺いしましたけれども、今後の再発防止にあたって、どのように適正な労働環境の改善などについてお考えをお持ちでしょうか。伺います。","respondent":"工藤品川区清掃事務所長","answer":"清掃安全衛生委員会を法律に基づいて設置しておりまして、月に１回、そういった形で適正な形で努めているところです。今までもそのようにしておりましたが、今後ともそのような形で対応していきたいと思ってあります。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"ですから、やはりこれからの取り組みは、今までとは違うことをやらなくてはいけないのではないかと思います。そのことについて、区としてお考えはないのかと伺ったので、もう一度お聞かせくたさい。","respondent":"工藤品川区清掃事務所長","answer":"交通安全に向けた事故事例等を踏まえまして、交通安全に関する研修、再発防止というところで取り組んでいるところです。そのようなことがないように再発防止に努めているところですので、ご理解のほど、よろしくお願いいたします。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺っていると、そういった事故が起きないような安全な運行ができるような体制をぜひつくってほしいと求めましたし、今後の取り組みに生かしていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"大沢委員","kind":"意見","question":"他の車もかかわっているわけで、事故を起こすにはさまざまな他の車両のいろいろな状況があったりとか、前の車の状況もあったと思うのです。十分了解をしているのですけれども、この事故はそもそもどのような状況で起きたのか、まず説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"そして、そのはずみで２台目が１台目に衝突したという状況になったです。事故の状況はこのような状況です。","id":"exchange-021"},{"speaker":"大沢委員","kind":"質問","question":"確かに議案には前方不注意と書いてある。でも、前方不注意と先ほど来の労働環境の話は必ずしも結びついてこないと思うのですけれども、そこのところはどのようにお考えか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"しっかりと私どもも区としましては損害賠償が発生したという部分で補償をしなければいけない、相手方に対してするものだというふうに思ってあります。作業上の安全、交通安全等を含めまして、全体的に事故をしないようにというところで取り組んでいるところです。","id":"exchange-022"},{"speaker":"大沢委員","kind":"質問・要望","question":"清掃事業のより安全性、そしてより迅速性、また交通安全に対する意識を高めていただくような取り組みを今後してほしいと求めました。先ほど来の労働環境云々かんぬんも含めて、清掃をつかさどる職員たちの安全意識を、それと、労働に対する意識も高めていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問","question":"ちょっとお伺いしたいのですけれども、雇上業者だった場合は、どこの保険を使うのか。雇上業者で２台でこういう事故が起きて、損害賠償２,７８８万円となった場合も、これは議会に報告は来るわけか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"保険等と議会へのご報告の考え方、対応についてです。変わってくるのですけれども、基本的には雇上会社の責任という形になりますので、雇上会社の保険で対応するです。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問","question":"専決処分の事故件数は報告がよくおありになるけれども、実際、雇上業者のほうが多いではないですか。我々のところへ報告が来ているのは３ぐらいで、ほかに７ぐらいはあるという理解でいいのか、そこら辺のところだけ説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"区のほうには、今までそういった過失という部分で、そういったお話はございません。１対３という形になってありますので、そういった事故という部分は日常の清掃事業の中ではあるというふうに認識していただきたいと思ってあります。","id":"exchange-025"},{"speaker":"松本委員","kind":"確認","question":"この１７９条とか、あるいは損害賠償義務が発生した場合の議会への報告以外に、報告するような何か規定は地方自治法上あるのでしょうか。済みません、私も確認不足なので、お願いします。","respondent":"工藤品川区清掃事務所長","answer":"３００万円以下の議決につきましては、損害賠償、和解ともに報告をするという形になってありますので、この中で報告をさせていただいておるものです。かなり重いものだという部分で判断した場合には、ケース・バイ・ケースでこういう情報をお流ししているような状況です。","id":"exchange-026"},{"speaker":"松本委員","kind":"質問","question":"重大な事故とかに関しては、任意というか、根拠があるかどうかは別として、委員会に報告される場合があるという理解でよろしいか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"今お話がございましたように、報告はケース・バイ・ケースという形になります。","id":"exchange-027"},{"speaker":"吉田委員","kind":"意見","question":"先ほど、こういう事故に関しての労働環境の議論がありましたけれども、この件に関してそれがどうなのかということについては判断つきません。その注意が払われるような労働環境であってほしいということを一言つけ加えて、賛成といたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"}]},{"id":"topic-04","title":"令和２年陳情第９号 児童遊園の安全性に関する陳情","agenda":"令和２年陳情第９号 児童遊園の安全性に関する陳情","exchanges":[{"speaker":"松本委員","kind":"質問","question":"これは私道なのかわからないですけれども、道路があるのですけれども、この道路はどこの所有になるのでしょうか。二重に通路ができるというような形になるのか、そのあたりの位置関係、所有関係を教えてほしいと求めました。","respondent":"溝口公園課長","answer":"赤く塗られているところ、赤で囲われたところは売却敷地になりまして、これの上側に奥のマンションに入る通路があります。所有につきましては、あくまで後ろ側のマンションの敷地というふうに認識しています。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"この荏原児童遊園の管理については、どのようにしていく考えなのか伺います。それと、公園との境界へのフェンスの設置などについて品川区での規定や基準などはどうなっているのか、あるのかないのかも含めて説明を求めました。","respondent":"溝口公園課長","answer":"公園管理については、今後、検討していきたいと考えています。それは隣接する土地の所有者の方とも協議しながら、どのような形でフェンスを設置していくのかというのは決めていきたいと考えているところです。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"今後いろいろな意見を聞きながら決めていくべきものだと思いますけれども、ある程度、区分けされているのが普通な分け方なのかなと思います。「実質的に自由にしてよい」というところと、これはそれぞれどういう意味でおっしゃっているのか、区としての考えがもしあれば伺います。","respondent":"溝口公園課長","answer":"そういった中のニュアンスを捉えての発言かなというふうに思っているところです。そういったものをしっかり行いながら、設計を進めていく中で、そういったものと協議をしながら進めていきたいというふうに思っております。","id":"exchange-031"},{"speaker":"安藤委員","kind":"確認","question":"では、確認ですが、公園を実質的に自由にしてよいと区が言ったわけではないということなのか、そこら辺を確認させてください。","respondent":"溝口公園課長","answer":"もしかすると、協議の中でそのようなニュアンスでとられた部分があったのかもしれません。２６８公園ある中で、これについては、ほかの公園と同様に取り扱っていきたいと考えているものです。","id":"exchange-032"},{"speaker":"吉田委員","kind":"確認","question":"その辺、はっきり確認したいと思うのですが、お答えいただけますでしょうか。住民の依頼に対して便宜を図った町会役員のお考えでは、この理解については、区としても同意見というふうに捉えてよろしいのか尋ねました。","respondent":"溝口公園課長","answer":"公園課の立場としては、町会といえ、好きに使えるという形にはできないというふうに考えております。同じような形での手続、進め方、考え方でいきたいというふうに考えているところです。","id":"exchange-033"},{"speaker":"吉田委員","kind":"意見","question":"ただ、やっぱり発言についてはそういうこともあるということを踏まえていただく必要はあるかなと思います。それからもう１点、そのときに町会の役員以外の方たちの意見を聴取するというような場面はつくられるのかどうか、それについても説明を求めました。","respondent":"溝口公園課長","answer":"そういったものも聞きながら、総合的に判断して進めていきたいと考えています。今後、設計していく中で決まっていきますけれども、そういった中でしっかり安全対策はとりながら進めていきたいと考えているものです。","id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういうことは使用許可の問題もあって、当たり前のことは当たり前のようにやっていただく指導はしていただきたいと考えています。町会会館の敷地というのが、私は一番いいと思っていますので、この陳情については不採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"大沢委員","kind":"質問・要望","question":"公園管理者としての公平性が担保されている、この件に関しては、町会内のお話の中でやってほしいと求めました。議会としては取り上げることはできないと思いますので、不採択とさせていただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それから道路境界にはガードレールという安全対策ということで、２つ大きく求められており、その思いは非常にわかります。当然そういう声も聞いていると思いますけれども、こういった陳情がありましたという声は町会のほうにもお届けいただければいいかなと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"安藤委員","kind":"意見","question":"陳情の児童や公園利用者の安全を守るということの趣旨はわかるので、趣旨採択でお願いしたいのですがとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"具体的な手法ですとか設計や設えについては、今後、検討の上で決まっていくものだと理解しております。先ほどもありましたけれども、公園を利用する側の立場の方の意見もしっかり聞いて具体化するように求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"吉田委員","kind":"意見","question":"基本的には町会の運営の問題だというふうに思いますが、そこがなかなか難しいところで議会に陳情を出されたというふうに理解しております。こういうことを採択することによって、そういう思いを示していきたいというふうに思いますので、採択を主張いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"松本委員","kind":"意見","question":"実際、この児童遊園自体は改修後かなり狭くなっていくのだと思います。その中で、今の段階でこれをここに書いてあるような方向で進めていきたいというふうなことを採択することはなかなか難しいかなというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"}]},{"id":"topic-05","title":"令和２年陳情第１６号 東五反田二丁目第３地区開発計画に関する陳情","agenda":"令和２年陳情第１６号 東五反田二丁目第３地区開発計画に関する陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"こういうスケジュールで進めていくのは適切ではないと思うのですけれども、少なくともこのスケジュールは見直すべきなのでしょうか。このまま進めるのか尋ねました。","respondent":"稲田都市開発課長","answer":"その前にまちづくり勉強会等々がもう既に平成２５年には始まっているというところで、そういう中で区との話し合いを進めてきておる状況です。十分検討してきており、日野学園への影響等も考えながらやってきたところですので、この予定を変更するつもりは今のところありません。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問","question":"見直しの声が上がっているわけですから、これを機に、一旦立ちどまって見直していくべきだというふうに思います。資料では日影図なども出されましたけれども、これのどこが良好な日照を得ることができる状況なのか、具体的に日影資料などから伺いたいと思います。","respondent":"稲田都市開発課長","answer":"日影図は先ほどご説明したとおりです。１年中、すべて日影になっているという状況ではございませんというところを、春秋分における日影図でご説明させてもらったところです。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"冬場ですから、今の説明で品川区は文科省が言うところの良好な日照を得ることができているという理由と考えているということでよろしいのでしょうか。伺います。","respondent":"稲田都市開発課長","answer":"この日照の件ですけれども、先ほど来、説明しているとおり、できる限りの工夫等をしながら開発を計画しています。このような考えです。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"特に区立学校ですから、品川区がみずから建てた学校に対して、どういう環境配慮をするかというのは、それはそれでなぜ考えないのかと思うのです。２つ伺いますけれども、再開発ですから再開発組合が主体だとおっしゃるのでしょうけれども、条件を出さなかったのか尋ねました。","respondent":"稲田都市開発課長","answer":"複合日影は検討されたのかです。そういう中ではさらにこれよりも影響を受ける部分はあるというふうには認識しております。","id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"先ほどの質問で、区立学校の真南の計画なわけですから、そうした条件や考えを示したことはなかったのかということをお伺いしました。伺います。","respondent":"稲田都市開発課長","answer":"そういう中において、区も建物の間を広げるという案につきまして検討を進めてきているというところです。２０ｍ、基準どおり開けるように考えておりますけれども、そういうところも並行してやっているという状況です。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"実際にここまで影ができて、それで残っている日照がどうなるのかということは、やはり複合で見ないとわからない。開発計画が適正かどうか、これはぜひ資料提出を受けた上で審査すべきだと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"私は、とても不勉強だったと思うのですけれども、複合日影のことについて認識がなかったので、できたら出してほしいと求めました。そういうことについても知っておかれたいと思うのではないかと思いますので、その辺、ぜひ資料を出してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"先日の一般質問の中でも、部長からのご答弁で、組合に対して指導していくというご発言があったと思います。その指導というのがどれぐらい強制力と言っていいのか、実効性がある指導になっていくのか、その辺について伺いたいと思います。","respondent":"稲田都市開発課長","answer":"今後もさらにその間隔が、どういうふうに建てれば広がるかというようなことも組合には指導していきたいと、一緒に考えながらやっていきたいです。ただ、日影規制がないというところにおいて、全体を考えながらよりよいところを考えられればというふうに思っております。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区としては、区立の学校を日影規制がないところに建てているわけですから。その辺について、過去の確認になってしまいますけれども、改めて教えてほしいと求めました。","respondent":"稲田都市開発課長","answer":"上位計画、そういう地区内に指定されているというところで、この街全体を考えたまちづくりについて議論をやっている。考えながら、北側には学校がありますという中において、話し合いをやってきたものです。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問","question":"この陳情者にお話を伺ったのですけれども、この陳情を出される前に、区に対してもいろいろ意見とかをおっしゃっている。具体的には建物の間を広げるというほかに、低層棟がありましたか、その辺についてはいかがか尋ねました。","respondent":"稲田都市開発課長","answer":"そういうところも考えて、空間を考えてやっているです。現在２０ｍというところの間隔ですけれども、組合には指導していますし、今後もそのことについて議論していくというふうに考えています。","id":"exchange-051"},{"speaker":"吉田委員","kind":"質問","question":"では、例えば、今後、指導の結果、そういう意見というか、そういうものがこういう形で、ここがこういうふうに変わって生かされましたというようなことは示されることはあるのか尋ねました。","respondent":"稲田都市開発課長","answer":"やはり学校へ与える影響などを最大限に考えてもらいたいということで話しておりますので、建物の間がどれぐらい広がったとか、そういう形の報告は今後できていくかとは思っております。","id":"exchange-052"},{"speaker":"松本委員","kind":"意見","question":"民間、民間がやろうとしていることにあまり指導がいき過ぎると、それはそれで違法という話にもなり得るのではないかと思います。そのあたり、感覚というか、ご見解をほしいと求めました。","respondent":"稲田都市開発課長","answer":"そういうまちづくりの大きな目標の中でやってきている、さまざまな人々の生活の中で関連があることのバランスをとりながら考えているです。このまちづくりをやっているですので、今のところ、ここで条例をつくる考えはございません。","id":"exchange-053"},{"speaker":"たけうち委員","kind":"質問","question":"ＰＴＡや保護者とか、いわゆるこの日野学園の関係者のほうからのそういった懸念の声だとか、また反対の動きだとか、そういったものを所管として何かつかんでいるものがありますか尋ねました。","respondent":"稲田都市開発課長","answer":"１６条の説明会をやる前に話をしたり、それ以外にも学校に話をしたりというところで、この計画の説明をやってきているところです。そういう中におきまして、ＰＴＡ、学校からのこの計画に対する大きな動きはございませんで、順序立てて話をしているという状況です。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"今度、この建物の間の距離がこれから現在の都市計画の縛りから変わるということはあり得るのかということを改めて確認させてほしいと求めました。原案の段階で、心配する意見が出ていましたけれども、そういった意見は都市計画案作成段階にどのように反映されて作成されたのか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"これは建物の２倍の範囲を設定しまして、その範囲で周知を図り事業者が地域で説明していくです。いずれにしましても、この事業者説明会で出た意見で反映させるべきものについては反映してきているというふうに考えております。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"逆にお伺いしたいのは、説明会を経て何か変わったところ、反映されたところは何があったのかを伺います。この段階で２つの建物の棟の間が広がるというような、そういうような抜本的な変更はあり得るのですかということをお伺いしたので、説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問","question":"つまり、２０ｍになっているところの範囲を３０ｍ、別の案が出されるということもあり得るということなのでしょうか。これは東京都などではもう行われていると思いますが、ホームページ等、そちらはそういうふうになるということでよろしいのか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"これはあくまでも学校への影響を事業者がどう考えて、現在、これが大幅に広がるということはなかなか考えにくいところではあります。それから、説明会の回数です。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"内容自体に住民の声をどう反映させるかという点においても非常に不十分だと思います。意見を求めようという姿勢が疑われると思いますので、まだ時間もありますので、ホームページにアップして見られるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"石田（秀）委員","kind":"質問","question":"その間に第二日野小学校も１学年１桁というようなこともあって、こういうさまざまな歴史があった中で今の大崎駅周辺があると思っています。東五反田二丁目第３地区について、こういうものが今の現状ではあって、この陳情については不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"大沢委員","kind":"質問","question":"たけうち委員からの質問にもありましたように、再開発そのものに反対なのか、あるいは基本的人権の侵害という文言も出ております。不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"たけうち委員","kind":"質問・要望","question":"不採択でお願いします。区もできる限りの配慮を求めているといったことも総合的に踏まえて、不採択ということでお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"安藤委員","kind":"意見","question":"配慮が乏しい上に、その影響も明らかにしないという点で、私はおかしいと思います。私は採択をすべき、そして東五反田二丁目第３地区開発計画に関しては、一旦立ちどまって計画変更の検討をしていくべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほど、再開発に反対ではなくて、この計画を子どもたちの基本的人権が侵害されることがない計画に変更していただきたいという内容です。こういう陳情者の声もあるということを示すというのは、とても大切なことかと思いますので、そういう意味でも採択を主張いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"松本委員","kind":"質問・要望","question":"理由ですけれども、陳情の内容は計画の変更を区に求めているものだと思います。行政に計画の変更を求めるという陳情に関しては、それはちょっと難しいかなというところで、不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"}]},{"id":"topic-06","title":"専決処分の報告について（報告第３号）","agenda":"専決処分の報告について（報告第３号）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"報告第５号ですけれども、樹木の根が成長したことにより段差が生じるということはあるとは思います。あるいは、本人の過失ということになるのか、そこら辺の基準みたいなものがもしあれば説明を求めました。","respondent":"溝口公園課長","answer":"そういった事故を起こすもの、ハザードといったものを取り除いていく、そういったことの管理はしっかりやっていかなければいけないと考えています。過失割合の有無ではなくて、そこについてはしっかり公園管理者として取り組んでいきたいところです。","id":"exchange-065"},{"speaker":"松本委員","kind":"質問","question":"同じく今の報告第５号ですけれども、これは裁判になったのか尋ねました。","respondent":"溝口公園課長","answer":"今回の件につきましては、裁判まではいっておりませんが、やはり過失の関係ですとか、そういったところの話し合い、協議を重ねてきた結果、通常よりも専決処分というか、損害賠償額の決定にちょっと時間を要したものです。","id":"exchange-066"},{"speaker":"吉田委員","kind":"質問","question":"例えば区道とか、公園とかにおいて、何かそういうような今まで統一した考え方とかはあるのでしょうか。その辺についての考え方が、今まであるのか、もしくはこういうことがあったことを機会に何か考える予定があるのか伺いたいと思います。","respondent":"多並道路課長兼用地担当課長、溝口公園課長","answer":"緊急にやらなければいけないところは今年対応し、来年度、根上がりの箇所は補修していこうと思っています。未然に防ぎながら、巡回のチェックの中でそういう場所があった場合は… 抜本的な対策になりますと、そういったときに樹木の根を含めてどうしていくのか、そういったことを考慮しながら改修を進めているところです。いずれにしましても…","id":"exchange-067"}]},{"id":"topic-07","title":"羽田空港機能強化に関する説明会の実施状況および実機飛行確認における騒音測定結果","agenda":"羽田空港機能強化に関する説明会の実施状況および実機飛行確認における騒音測定結果","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"それと、実機飛行確認中に、区に寄せられた問い合わせは何件でしょうか。できれば実施日ごとの件数と合計件数も伺いたいと思いますし、また、そうしたものに対して、どのように対応しているのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"実施中の問い合わせ件数ですが、２月２日は日曜日ですので宿直にかかってきた電話の件数ですとか、そういったものを含めてになります。２月２日が１件、２月３日が３１件、２月４日が３件、２月５日が８件、２月７日が６件、２月１１日が１件、２月１２日が８件です。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。問い合わせいただいたときの対応についてもお伺いしたのと、側方向から１５０ｍということで、高さはわからないか尋ねました。","respondent":"鈴木都市計画課長","answer":"お寄せいただいた電話に対する対応ですが、全てまとめて国のほうにお知らせ、お伝えするという形の対応をとってあります。これも約ということになりますが、立会小学校のあたりですと、大体３７７ｍぐらい、台場小学校ですと、約４７５ｍです。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"なので、きちんと区で責任をもって答えられるところは答えてほしいし、丁寧に対応していただきたいとまず思います。その情報は区はどのように把握しているのか伺いたいのですが、追加したのが３カ所ということは、そういったところを正確に知りたいのです。","respondent":"鈴木都市計画課長","answer":"先ほどの区のお問い合わせに対する対応について補足をしますが、そうした状況の中、当然ながらお答えすべきことはお答えをしています。実施主体は国ということで、それから高度については、まだ手元にない状況です。","id":"exchange-070"},{"speaker":"安藤委員","kind":"確認","question":"実機飛行確認中の落下物の有無や被害については、国から区はどのように聞いているのか伺いたいというのが１つです。実機飛行確認での進入角度なのですけれども、それとも３.５度で行われたということなのか、そこも確認したいと思います。","respondent":"鈴木都市計画課長","answer":"国が設置している３カ所について、これも約になりますが、手元にございましたのでご報告します。７日の間、３.５度の日もありましたし、３度の日もあったです。","id":"exchange-071"},{"speaker":"安藤委員","kind":"確認","question":"３度の進入角度は、実機飛行確認中にエアカナダが、３.５度の飛行の参加を見合わせたということも報じられております。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"社内としては、内部的な準備が整っていないものの、３月２９日からの新飛行経路運用開始までには必要な準備を進める旨、回答があったというものです。目的地の変更、成田空港に変更があったですが…","id":"exchange-072"},{"speaker":"安藤委員","kind":"確認","question":"そもそも実機飛行確認の目的、これはそもそも論で言うと何だったのかというか、国の評価について伺いたいのです。こういうものを確認するという意味でやっているのか、今回の実機飛行確認の、国はこれをどのように評価していると区に説明されているのか尋ねました。","respondent":"鈴木都市計画課長","answer":"実機飛行確認の実施の内容ですが、新たに設置した騒音測定局の機器の調整を行うというところで実施したです。基本的にはそうした目的が確認がとれたというところで国から聞いているところです。","id":"exchange-073"},{"speaker":"安藤委員","kind":"質問・要望","question":"一体何が確認されたのかというふうに思いまして、先ほどの確認だけの意味だったら、中止せよと求めるべきだと思います。それはもう一度確認したいので伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"かねてから当委員会でご説明していますが、騒音環境の低減については、これをしっかり今後も行っていただきたいということを求めてあります。当然ながら騒音環境の軽減と落下物に対する不安を少しでも軽減するような形でのルートを固定化しない見直しを行っていただきたいという…","id":"exchange-074"},{"speaker":"安藤委員","kind":"質問・要望","question":"実際にどうなのですか、中止も求めたほうがいいのではないですかと聞いたら、まだ固定化しないよう求めていくということなのですね。これから何を求めていくのですか、さらに求めていくということなのか、考えをお伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"国の回答は、この回答があって、これで検討していただけるのですね。早急に示していただくように、やはりしっかり検討していただいて示していただくように、国には今後も強く求めていきたいです。","id":"exchange-075"},{"speaker":"吉田委員","kind":"質問・要望","question":"これまでも区は国に対して区民の不安を払拭するための丁寧な説明と対策を求めていくということなのですけれども、今、騒音測定の結果が出ております。具体的に国に対してどういうような要望を、説明を求めておられるか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"これは国のほうも２月２１日の国土交通大臣の会見の中で、現在、できる限り早期に公表することを予定しているという答弁が会見でございました。これまで説明した騒音レベルを著しく上回る結果となった場合…","id":"exchange-076"},{"speaker":"吉田委員","kind":"質問・要望","question":"丁寧な説明を求めていく、もうそれは今の航路については固定化にとどまらず撤回していくということを求められるということでしょうか。その辺を確認させてください。","respondent":"鈴木都市計画課長","answer":"これまでもさまざまな区民の不安解消につながる取り組みを実施していっていただきたいということは求めてきてございまして、３月２９日以降。必要に応じた新たな騒音対策を検討していかなければいけないというところは…","id":"exchange-077"},{"speaker":"吉田委員","kind":"質問・要望","question":"あくまで中止は求めないということなのですが、ある意味、幸いにして何も事故も起きなかった。この航路については撤回していただくというようなことを区が求めてくださらないと、区民としては、その辺についてはいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"国として対応するというところは、これは国の事業ですし、まさに委員ご紹介いただいたように当然のことです。現在の取り組みで立ちどまるのではなくて、さらに取り組みを進めていっていただきたいというところを今後も国のほうに強く申し上げていくです。","id":"exchange-078"},{"speaker":"吉田委員","kind":"質問・要望","question":"これ以上やりとりしても同じようなことになってしまいますので、それについては、ぜひきちんと対応してほしいと求めました。この説明会のこの状況について、これについては何か区としては国のほうに申し入れているということはないのか尋ねました。","respondent":"鈴木都市計画課長","answer":"第６フェーズの説明会が終了したわけですが、そこでいただいたご意見も国はニュースレターという形で周知を行っているところです。第６フェーズが終わって、これでもう説明会等が行われないのかというところは、やはり継続して行っていっていただきたいです。","id":"exchange-079"}]},{"id":"topic-08","title":"「都市計画公園・緑地の整備方針」および「緑確保の総合的な方針」の改定案","agenda":"「都市計画公園・緑地の整備方針」および「緑確保の総合的な方針」の改定案","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"別紙１のほうは、これを説明していただきたいということと、別紙２のほうです。今回の旗の台の公園用地整備と、緑確保の総合的な方針の改定との関係といいますか、そちらがよくわかりませんでしたので説明を求めました。","respondent":"鈴木都市計画課長、溝口公園課長","answer":"別紙１の右下の優先整備区域内の建築制限の緩和ですが、詳しくは本編の４３ページに出てありますが、いろいろ制限が加えられてあります。以前は木造３階建等が建てられて… 緑確保の総合的な方針、今回の改定にあわせて旗の台六丁目を位置づけた経緯等について、ご説明します。計画的な公園整備にあたっていきたいということで、今回、緑確保の総合的な方針の改定にあわせて新たに指定をするものです。","id":"exchange-080"},{"speaker":"安藤委員","kind":"質問","question":"結果的に緑が増えたけれども、さまざまほかの環境的な課題が発生したりとかということになって、万々歳というふうにいかないと思うのです。この２つの整備方針に関しては、それぞれそういうところの不安といいますか、そこら辺に関して区の考えをそれぞれの計画について伺いたいと思います。","respondent":"鈴木都市計画課長、溝口公園課長","answer":"先ほどご説明した視点で、どこを優先的にやっていくかというところを整理しているものです。あらゆる取り組みの中で、総合的にはそういう方針、方向性は変わらないと考えています。 さまざまなまちづくりが起こっていく中で、あわせて緑ですとか道路、そういった必要な公共インフラの整備も行っているところです。さまざまな手法を使いながら、やはり緑豊かな街を後世に残していく…","id":"exchange-081"},{"speaker":"安藤委員","kind":"意見","question":"必ずしもそのときにまちづくりとして適正かどうかというのは、また違う観点があると思いますので、ぜひそこら辺は総合的な観点から進めていく必要があるというふうに意見を述べしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"吉田委員","kind":"質問","question":"丸の３つ目、もう１回、ご説明いただけたらと思います。","respondent":"鈴木都市計画課長、溝口公園課長","answer":"済みません、先ほどの説明が不足していたのかもしれませんが、本編の４３ページをご覧いただけますでしょうか。依然として２階建てまでしか建て替えできませんとなると、そうした前提のもと… 整備方針の中で、先ほど都市計画課長が説明されたように、自分の設計の中で一定の緩和をしていこうというのがもともとの考え方の流れです。ただ、１０年間の中で…","id":"exchange-083"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望です。意見を添えします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"},{"speaker":"たけうち委員","kind":"質問","question":"別紙２のところで、水準１から３の中で、品川区は旗の台六丁目の１箇所のみということでいいですね。品川区は２４箇所、８.５４ヘクタールとあるのですが、説明を求めました。","respondent":"溝口公園課長","answer":"保存樹、保存樹林、そういったものに取り組みながらやってきているところです。は個人宅、なかなか公表というところまではいかないので、箇所と面積だけの公表という形にさせていただいているものです。","id":"exchange-085"},{"speaker":"たけうち委員","kind":"意見","question":"議会にも報告があるのでしょうけれども、今の段階でいろいろ当たり障りがある、そういうことですね。はい、わかりましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-086"},{"speaker":"石田（秀）委員","kind":"質問","question":"民間で１回推し進めようとやったけれども、やっぱり大変だと言ってやめていくとか、いろいろあるではないですか。ここには書いていないのだけれども、そういう話は都心区というか、考えはないのか尋ねました。","respondent":"溝口公園課長","answer":"緑確保の総合的な方針の中では、さまざま緑化していきましょうというところの記載はあるものの、細かいところはないと感じています。そういったものが起きた際には、緑の条例に基づく緑化指導を行いながら、少しでも緑を増やしていく保全に向けて取り組んでいきたいです。","id":"exchange-087"}]},{"id":"topic-09","title":"居住支援協議会の設立","agenda":"居住支援協議会の設立","exchanges":[{"speaker":"吉田委員","kind":"確認","question":"そのときも伺いましたし、あくまでここの所管の問題として進んでいくのか、その辺について確認させください。","respondent":"森住宅課長","answer":"今ご説明をいたしました３部８課で構成しております。それぞれの課が居住支援のための事業をそれぞれ展開していくために、この協議会の中でさまざまな協議が進めばというふうに思っているところです。","id":"exchange-088"},{"speaker":"たけうち委員","kind":"質問","question":"右側の不動産関係団体には、東京都宅地建物取引の品川支部と、全日本不動産協会の東京都城南支部が入るということでいいのか尋ねました。","respondent":"森住宅課長","answer":"委員ご指摘のとおりです。","id":"exchange-089"},{"speaker":"たけうち委員","kind":"質問","question":"第１回目は間もなくということなのですけれども、そうすると、この第１回以降の主なスケジュール感はどのような感じなのか尋ねました。","respondent":"森住宅課長","answer":"１２月あたりに、２回目、３回目ということで予定しています。ただ、高齢者について協議をしていくとかというようなことも考えられると思いますので、随時フレキシブルに協議を行っていきたいと考えております。","id":"exchange-090"},{"speaker":"石田（秀）委員","kind":"質問","question":"それで幾つかお聞きしたいのですが、１つのフレームをどこが考えるのかということがあるではないですか。これは生活保護だったら５万３,７００円以下だったらお風呂のないところ、そういうものをあっ旋したりとか、やったりもしているではないか尋ねました。","respondent":"森住宅課長","answer":"例えば中心にといったようなところですけれども、今、高齢者地域支援課で高齢者住宅生活支援サービス事業を一昨年の８月から実施しております。所管課長から説明をしてもらって、大家も貸してくれるかというようなものを具体的な話をしながらやっていければと思っています。","id":"exchange-091"},{"speaker":"石田（秀）委員","kind":"質問","question":"それはその金額以下なのだからそっちへ行ってしまうということもあったりするではないですか。そういうことまで含んで、ぜひここの部分はやってほしいなと思うのだけれども、この辺のところの感覚はどうか尋ねました。","respondent":"森住宅課長","answer":"これ以上にＰＲを進めるとか、支援が必要な方に対して、提供するということも１つの遡上に乗せていくべきなのかというふうに思っております。区全体として、区民住宅の提供のあり方についても、今後検討していければというふうに思います。","id":"exchange-092"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私はここにもう１つ足していただきたいのは、ぜひそこら辺のところも議論していただきたいというのは、お願いします。何か答弁があれば聞いておきます。","respondent":"森住宅課長","answer":"今、外国人の活用を進めていこうとしておりますので、当然この居住支援の中でも要配慮者の中に外国人も入っております。それは、この協議会での具体的な議論になってくるのかなというふうには思っておりますし、そうしていきたいと思います。","id":"exchange-093"},{"speaker":"大沢委員","kind":"確認","question":"確認だけお願いしますけれども、まずこの事業は、区独自、それとも都、国から、そこの関連性を説明を求めました。","respondent":"森住宅課長","answer":"居住支援事業につきましては区の事業です。国として進めており、当然、区民と直接にかかわる区市町村の居住支援協議会が中心となって具体的な支援を進めていくです。","id":"exchange-094"},{"speaker":"大沢委員","kind":"質問","question":"都と国の補助金ということなのですけれども、これを見ると、事業期間が、平成３１年４月１８日から平成３２年１月３１日となっているのですけれども、これはどういうふうになっているのか尋ねました。","respondent":"森住宅課長","answer":"東京都として、居住支援協議会をそれぞれ進めていこうとしておりますので、今後も出てくるのかというふうに思っております。そういったものを活用しながら、区として事業を進めていければと思います。","id":"exchange-095"},{"speaker":"大沢委員","kind":"確認","question":"いずれにしろ都と国がかかわっているのであれば、ご覧になっていないというか、確認しておくのは事業を始める前に大事なことではないでしょうか。どうか尋ねました。","respondent":"森住宅課長","answer":"当然、国等の予算等々、来年度、今年度もそうですけれども、事業については確認をしています。それぞれの事業の中で１年間を通じてということもありますし、そういったものは確認をしながら進めていきたいと思います。","id":"exchange-096"},{"speaker":"安藤委員","kind":"質問","question":"１点ですけれども、そこの具体的な解決がないと、やはり絵に描いた餅になってしまうのかなというふうに思うのです。協議会においては、どのような方策が考えられるといいますか、区としても今考えていることなどもあれば、あわせてお伺いしたいと思います。","respondent":"森住宅課長","answer":"今、委員にご例示していただきました高齢者についてですが、高齢者地域支援課であんしん居住サポートをやっているところです。不動産会社と一緒になってそういったものを展開していきながら、まずは今ある高齢者住宅生活サービス支援事業を展開していければと考えています。","id":"exchange-097"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、支援方法みたいなものをぜひ検討してほしいと求めましたけれども、いかがか尋ねました。","respondent":"森住宅課長","answer":"最初に預託金をいただきながらということでありましたが、最初の自己負担が多いということで、分割も勧めているというふうに聞いております。協議会のメンバー等々、そういった部分を明らかにしていきながら…","id":"exchange-098"},{"speaker":"あくつ委員長","kind":"質問・要望","question":"会派からも長年要望していましたので、先ほども幾つか質問がありましたが、かなり民間の参入がモデルとして書かれている。ただでさえそれも今、民間の知恵と活力を使っていくというところをどういうふうにお考えになっているのかお聞かせほしいと求めました。","respondent":"森住宅課長","answer":"居住支援を行っていくための担い手としましては、今、民間活力というのか非常に重要になってくるというふうには考えております。あるいは、２６団体の意見も聞きながら、それぞれどういった形で参画していただけるかというのは検討していきたいと思います。","id":"exchange-099"}]},{"id":"topic-10","title":"防災都市づくり推進計画の基本方針改定案","agenda":"防災都市づくり推進計画の基本方針改定案","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"不燃化特区を全域に広げていくというお考えはあるのか、求めたいと思いますけれども、いかがかというところをお伺いします。３点目としましては、特定整備路線は、今の現状でのそれぞれの用地取得率について伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"今後も新たな５年間延伸するところに、検討する考えはありますが、区内全域に不燃化特区の支援制度を求めていくという考えはございません。現在、今回の東京都の基本方針によって、そのまま９地区が自動的に延伸するというものではないということで東京都から話を受けております。","id":"exchange-100"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後ですが、特定整備路線が２０２５年度まで延長ということですけれども、完成の見通しはあるのでしょうか。そこら辺についての区の見通しといいますか、見立てを、伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"新たな工事を見据えて頑張って進めていくというような決意を示そうとしているといったところは、ともに連携して一緒に品川の街をよくする防災まちづくりが進められるように協力していきたい、このように考えているところです。","id":"exchange-101"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/733618?Template=document&Id=4284#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":80963,"voices":283}},{"id":"r02-20200225-9","meetingId":"r02-cm02","date":"2020年2月25日","dateIso":"2020-02-25","committee":"文教委員会","time":"午前１０時００分～午後 １時１２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件整理しています。","topics":[{"id":"topic-01","title":"第１４号議案、品川区子ども家庭支援センター条例","agenda":"第１４号議案、品川区子ども家庭支援センター条例","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"資料に、子ども家庭支援センターが扱うものとして、「虐待、養育困難等」とあるのですけれども、この「等」の部分はどういったものがあるのかということと、それと関わって、子育て支援センターとのすみ分けの部分をもう少し具体的にご説明ほしいと求めました。","respondent":"崎村児童相談担当課長","answer":"しつけの相談ですとか、ケースで長期でもつようなものについて、虐待を含めて対応するといったところです。相談をして、内容によって子ども家庭支援センターにつないでいただくといったことも想定をしているものです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"わかりました。本会議でもその体制を伺い、全体で２５名程度ということだったのですが、心理職の人数というのも伺いたいと思います。","respondent":"崎村児童相談担当課長","answer":"内訳につきましては、現在のところ、福祉職が１０名程度、心理職が８名程度、ほかに事務職等々、あと会計年度任用職員などを配置する予定です。新規職員の採用状況ですとか、数字のほうは若干変動があるかもしれませんが、現在のところはそのように見込んでいるところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"意見","question":"やはりこういった専門職の方がしっかりと体制をとっていらっしゃるということが相談業務の強化につながると思います。この子ども家庭支援センターをつくることによって、児童相談機能の“こういったことが強化される”ということをご説明ほしいと求めました。","respondent":"崎村児童相談担当課長","answer":"子ども家庭支援センターという名称の組織を備えることによって、対外的に区の児童相談、認知度が上がるというところで期待しているものです。１７区ほどは部や課として位置づけているといったところですので…","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問","question":"子ども家庭支援センターは、今回、組織化され一元化されるのですが、区立児童相談所の設置に関連して、今後の見通しというか、そちらとの関連がどういう状況になるのか、開設されることに向けてどういう体制になっていくのか、そして開設されたら、そことの関係はどうなるのか、ご説明お願いします。","respondent":"崎村児童相談担当課長","answer":"児童相談所が開設したときには、今後、児童相談所の開設にあたって基本計画等々を作成していく過程で検討してまいりたいと考えております。来年度から３区が児童相談所を開設することになりますので、そういった動向等も勘案しながらやっていきたいと考えています。","id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"意見","question":"二元的だったところを一元化して、組織的にもしっかりと対応していくということがわかりました。児童相談所の開設に向けて、ぜひ区立児童相談所開設に向けて、よりよい方向で検討していってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"横山委員","kind":"確認","question":"細かいところなのですけれども、確認だけお願いいたします。１８歳に達して以降の最初の３月３１日までの間にある者という意味になるのか、その辺りを教えていただけたらと思います。","respondent":"崎村児童相談担当課長","answer":"委員ご指摘のとおり、児童福祉法上は１８歳未満が児童で、そういった者が対象となっております。こういった対応については、委員がおっしゃいましたように、そういったことはケースに応じて柔軟に対応していきたいと考えています。","id":"exchange-006"},{"speaker":"のだて委員","kind":"意見","question":"これまで民間委託していた子ども家庭支援センターを区が直営で運営するということで、児童虐待相談などを深めたり、児童相談所開設に向けても人材育成などの強化につながると思いますので、賛成ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"第１５号議案、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例の一部を改正する条例","agenda":"第１５号議案、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回の改正のポイントというのですか、確認になりますけれども、そこを伺いたいと思います。改めて、影響する人はいないということで確認させてほしいと求めました。","respondent":"佐藤保育課長","answer":"１点目の国の間違いなのかですが、官報にも原稿誤りということで明記されております。影響に関しましては、先ほどご説明したとおり、全くございません。","id":"exchange-008"},{"speaker":"塚本委員","kind":"意見","question":"どうなるというのが間違っていてどう直したのかというのをもう少し詳しく説明していただけると、なぜ間違えたのかみたいなことにもつながるかと思いますので、詳しくご説明いただければとの意見を述べました。","respondent":"佐藤保育課長","answer":"影響と言いますか、間違った箇所の具体的な説明ですが、新旧対照表を見ながら聞いていただければと思います。「未満」と書いていると０・１・２歳児になり、０・１・２歳というのは３号認定なので、あり得ない文章になっているです。","id":"exchange-009"},{"speaker":"のだて委員","kind":"確認","question":"確認なのですが、幼稚園の職員の状況というのはどのようになっているのか。長時間労働がどの程度あるのかというところを伺えればと思います。","respondent":"工藤指導課長","answer":"勤務時間外の在園時間についても一定程度生じているというところでは、学校の教員と同じように時間外での勤務、残って園務をしているということがあるということは把握をしています。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"一定程度の時間外労働があるということで、１日何時間労働とかがわかれば伺いたいと思います。","respondent":"工藤指導課長","answer":"ただ、先ほど申し上げたところです、次の日の勤務のためにということで残っているということは把握していますけれども。すみません、数字については、今、お示しできないので、また改めてお示しできるところにて、と思います。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"幼稚園の職員にも恒常的な長時間労働が発生しているという認識でよろしいのか尋ねました。","respondent":"工藤指導課長","answer":"必要に応じて、自発的に残って教材研究をしている、残ってそういった作業をしているというのを幼稚園訪問などでも伺っているところです。全員ではなく、自発的に残って作業をするということは実際にはしているというところの現状をお話しさせていただいたところです。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"個々の自治体ですとか学校の完全選択制で導入するかどうかを決められる。５つのハードルを言いましたけれども、実際に今後どのようにしていくのか、そこを伺いたいと思います。","respondent":"工藤指導課長","answer":"意見聴取も含めて進めるものであると私どもは認識していますが、また変形労働時間制については実効性あるものにしていければと考えているところです。個々の条件についてという考えは、またそれについては条例の改正等…","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"月４５時間以下、年３６０時間以下の教員にしか変形労働時間制というのは導入できない、区のお考えを伺いたいと思います。つまり、前提条件としてこれをクリアしなければ導入はできないということになりますので、そこの厳格性を伺えればと思います。","respondent":"工藤指導課長","answer":"今回でいえば、また年間で言うと３６０時間を超えない、まずは管理する側に示されたというところで受けとめております。今、私のほうでお答えはしておりませんけれども、それぞれ効果があるように行っていくという考えではあります。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"夏季だけなのか、それともほかの長期休暇のところでも取れるとか、そういったところも具体的には今後詰めていくということでいいのか、そこの確認。今、業務を削減していくということでやっていかなければできないと思いますので、そこのところも確認させてほしいと求めました。","respondent":"工藤指導課長","answer":"今後詳細につきましては検討していく必要があると考えていますし、また必要に応じてお示ししていくものだと考えています。それにより質の高い教育ができることを目的としていますので、削減とかさまざまなところは講じていきたいと考えているところはあります。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそういった形でやらなければいけないと思いますので、時短ハラスメントということがないようにしてほしいと求めました。幾つか労働組合にもお話を聞いたのですが、話を聞いていないというお話だったので、なぜこの協議をしていないのか、伺いたいと思います。","respondent":"工藤指導課長","answer":"今、いわゆる超勤４項目以外でも公務として教員が自主的に残っている、労働基準法で言うところの労働時間に含まれないものという考えです。これまで超勤４項目にも当然同様の規定はございましたけれども、いわゆる勤務条件を変えるものというふうには認識してございません。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"今回のものが管理するもので、変更ではないということですか。そうすると、労働条件の変更になってくるのではないかと思うのですが、最後に改めて伺います。","respondent":"工藤指導課長","answer":"今、教員がいわゆる超勤４項目以外で残っている校務につきましては、本来労働時間としては含まれないものであります。ただ、教員の勤務時間の条件を定めているものではないという認識をしていますので、そういった話をしていないところがあります。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回のものは管理するものであって上限を定めるものではないというお話だったのですが、ちょっと私は納得できないところがあります。労働組合との協議を行っていくということが必要だと思いますので、そこのところはしっかりと今後やっていっていただきたいということでお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"筒井委員","kind":"確認","question":"まず国の、それに基づいて、地方自治体にも条例改正をすべきというような指針が出されたという理解でいいのですか。文部科学省が出したスケジュールでは２月議会で条例制定をするという流れは出ているのですけれども、そういった流れでいいのかという確認を、まず。","respondent":"工藤指導課長","answer":"委員ご指摘のとおり、学校教育職員のいわゆる給特法が改正されたことによりまして、業務量を管理する必要があります。今回、条例改正が必要になったというところで、ご指摘のとおり国のほうの改正があったというものを受けましての条例改正です。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"資料の２ページで、規則改正（予定）の概要とあるのですけれども、これも一応、中央教育審議会で審議されて、そうしたモデルケースみたいなものが示されて、それを受けて、この規則改正（予定）の概要という内容が出たということでよろしいのか尋ねました。","respondent":"工藤指導課長","answer":"国の動きとしては、委員ご指摘のとおりですが、私どもでいえば特別区の人事・厚生事務組合の人事委員会からの改正案というのを提示いただきまして、それを受けてこの内容でというところで、今後、規則改正をする予定です。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"今、特別区とおっしゃったのですけれども、ほかの県とか自治体によっては細かいところで時間が違うということもあり得ることなのですか。それとも、やはり一律なのか尋ねました。","respondent":"工藤指導課長","answer":"こちらの規則改正の予定のものにつきましては、国が示した格上げされる前のガイドラインも同様の規定でございました。ひいてはこの時間等は労働基準法に基づいたものですので、これが自治体等によって変わるということはないと認識しています。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"そういった体制というのは、今現在、品川区ではできているのでしょうか。それともこれからさらにブラッシュアップして準備していくというような状況なのか尋ねました。","respondent":"工藤指導課長","answer":"品川区におきましては出退勤システムを早期から導入していますので、教員側の在校等時間の管理につきましては従前よりできるようにしています。一部システムの改修も行いながら、これに合わせて実施ができるようにということで進めているものです。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは既にガイドラインで超勤４項目以外も含めて時間外在校等時間ということで、できているというのか、わかれば。やはり時間内で仕事をやり切れませんでしたという人がもしいるとすればどれぐらいなのか、数字等がわかれば教えてほしいと求めました。","respondent":"工藤指導課長","answer":"６０時間でも超えてしまう教員がやはりおるというところで、そういったところがある中で、もちろん削減も含めて行う必要があるという認識があります。学校のほうでもこれまでの基準とまた異なるところがありますから…","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"なぜこんなことを聞くかというと、労働基準法から来ている時間設定だというのを伺いましたけれども、“はい。この間、こういうもので業務量の削減というのはやはり十分図れるものと見通しているのかどうか、というようなところを伺いたいと思います。","respondent":"工藤指導課長","answer":"生徒指導であるとかイレギュラーが発生した場合にも、十分対応できる時間を確保することにつながると考えているところです。ご質問いただきました２点目、また具体的に業務量を削減させるというのも含めながら、今後とも続けていきたいという考えです。","id":"exchange-024"},{"speaker":"横山委員","kind":"確認","question":"この辺り、影響であったり課題といったところがもし何かありましたら、そして今後どう考えていらっしゃるのかというところを確認できたらと思います。大分進んできているのか、現在の状況というか意識改革の部分について、何か進んでいる状況を確認できたらお願いいたします。","respondent":"工藤指導課長","answer":"は児童・生徒に関わる対応等の調整なのですけれども、チームとして対応すること、工夫しているところではあります。特段、それが課題になっているという認識はございません。","id":"exchange-025"},{"speaker":"せお委員","kind":"質問・要望","question":"１点だけ確認させていただきたいのですが、資料の２ページ目の規則改正の概要の中の（２）、幼児。どのようなことを考えられるのかなと思ってお聞きしたいです。","respondent":"工藤指導課長","answer":"そういった場合には交代制をするであるとか、そういった場合であっても、という規定です。申し上げたような事情だと認識しておりますので、これをさまざまな場合に適用して、私どもも認識しています。","id":"exchange-026"},{"speaker":"せお委員","kind":"質問・要望","question":"先ほどからお話がありますように、そういった場合でもチームで対応したり、なるべく業務量を減らしてみんなで対応していく、さまざまな方法を使っていただいて、教員のサポートをしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"要するに、外部人材を進めて業務削減できているかどうかをしっかり確認しましょうというのを教育委員会に求めているという点。どういうのが考えられるか尋ねました。","respondent":"工藤指導課長","answer":"例えば、人材を増やすことも含めてできる限りの試みは検討していきたいと考えているところです。閉庁日の設定であるとかそういったところも含めながら、また学校からも十分意見等を聞きながら、相談をしながら進めていきたいと考えています。","id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"質問","question":"個々の学校ではなかなか人材発掘ができないので、教育委員会のネットワークというのでしょうか、そういうものを活用してほしいと求めました。この数字ですね、上限が決まったのですが、それ以下にできるだけ抑えるような形で教育委員会もぜひ教員のフォローをお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"この制度の目的、あとこの制度を利用する際の仕組みというのですか、どう利用申請をするのかとかそういったところ。学習支援員・介助員という方が、現状何人いらっしゃるのか伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"社会参加に向けた支援ですので、より本人の社会参加を促すものになるという考え方に沿って配置をしている状況があります。なお、仕組みですが、ＮＰＯ法人に申請をする前に、まず各校より、これは半年に１度ですが、支援員の配置申請をとっております。","id":"exchange-030"},{"speaker":"のだて委員","kind":"確認","question":"そうすると、まず確認として、このＮＰＯ法人がどこなのかというところですね。そうすると、その後、追加で必要になったという方については利用はなかなか難しいということになるのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"１年生に関しましては入った状況で、６年生が卒業してしまった以降の部分もありますので、そこは柔軟に個別に対応させていただいているところです。それと、本法人はこれまでも学習支援員の制度以外にもすまいるスクール等…","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"半期に１回申請があるということで、各校の配分というのはある程度余裕を見てというのでしょうか、確認を。学校からもやはり増やしてほしいという要望が出ているという話も聞きまして、今回、確認をさせてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"これまでもニーズのある、支援の必要なお子さんが増えるたびに予算要求はさせてきていただいておりますので、毎年必ず通るかどうか、最終的に区議会でご判断をいただくものですが、増額する形で対応してきた経緯があります。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"毎年やってきたということですけれども、学校の要望とかも聞いてということでよろしいのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"そういった部分はしっかりと教員研修ですとか個別の支援、あるいは指導主事が教室に入って指導・助言をすることで対応をするべきものと。ぜひそこはしっかりと申請したいという場合には、申請書を出していただいて、これまでどおり判断してきているところです。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問","question":"この間も要求をしてきたという中で、これまでは要求していたけれども増えてこなかったということなのですかね。そこの区の認識を伺えればと思います。","respondent":"大関教育総合支援センター長","answer":"それは今後もあろうかと思いますが、その場合、必ず政策予算で必要であるという内容をしっかりと要求させていただいてまいりました。当時は１億６,０００万円程度だったものが、もう６,０００万円ぐらい、議会の皆様にもご理解いただいて進んでこれたものだと認識しております。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"最後に、ＮＰＯとの時間数というのですか、契約上どのような形になっていらっしゃるのか。ＮＰＯとの関係で増やせないとかそういったこともあるのか、伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"実際には予定していたお子さんが、例えば途中で転学されるケース、その間は支援員が必要なくなるというケースもあろうかと思います。有効にお願いをし、委託先としっかりと連携を取りながらやっておりますので、年度当初の契約のとおりやってもらっている部分があります。","id":"exchange-035"},{"speaker":"筒井委員","kind":"意見","question":"教育委員会としては予算要求もされたということなのですけれども、個別の教育的ニーズのある児童・生徒というのは、今、増加傾向にあるのか。それに対して品川区として学習支援員・介助員の増員が必要だと考えているのか、ちょっとお考えを説明を求めました。","respondent":"大関教育総合支援センター長","answer":"国の調査によれば、そして東京都はそのうち半分ぐらいのお子さんが特別支援教室などで対応ができるだろうと試算はしています。特別支援学級については品川区内で増えてきておりますので、特別支援学級については教員とは別に１学級に１名学習支援員を配置しておりますので。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"１月の状況を見て判断されるということや、その年度とか月によって、柔軟にケース・バイ・ケースで対応していくのがいいとお考えになっているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"後期にはかなり自立できる内容が増えたので配当せずとも大丈夫というケースもあったり、あるいは逆に後期から必要だというお子さんに新たにつけたりという見直しをするのが、大きくは年２回となります。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問","question":"ということで、見直しを定期的にかけているということで、一律単純に増やせばいいというものでもないという理解でよろしいか尋ねました。","respondent":"大関教育総合支援センター長","answer":"今、委員よりご指摘いただいたように、一律単純に増やせばいいということではなくて、状況に応じて見直しも半期ごとに行っております。やはり社会参加に向けて自分の力というものを高めていくのが学習支援員・介助員のあり方だと教育委員会では考えております。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問・要望","question":"予算があるから、人がいるから要望があれば「はい、一方でそこの客観性というのはなかなか一言で言えない部分というのがあるのだろうと思うのです。特につける・つけない、配置をする・しないというところの判断についての一定の見解というのですか、そういうのを一点だけお伺いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"特別支援教育係に１０名おります特別支援教育の視点をもって２週間に１回担当校を回っております巡回相談員が普段の子どもたちの学習の様子をつぶさに見ておりますので、申請内容に対して最終的な配当時間を係として決定する場合の参考として、普段の巡回の様子を記録しています。","id":"exchange-039"},{"speaker":"芹澤副委員長","kind":"質問","question":"本日結論を出すで、不採択でお願いいたします。内容として、今、ご説明ありましたとおり、これから拡充をする予定だと伺いましたので、これからの動向をまず見ていきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"せお委員","kind":"質問","question":"陳情者の方がおっしゃるとおり、意義のある制度だとは思います。通級などの利用、そういったことも有効かと思いますので、引き続きインクルーシブ教育に向けてさまざまな支援を行ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"塚本委員","kind":"意見","question":"結論は不採択です。令和２年度予算では２億２,７７２万２,０００円余が計上されて、今現在、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"のだて委員","kind":"意見","question":"やはり必要な子どもに必要な手立てが講じられるべきだと思います。今回、予算要求をされているということですが、区教育委員会の後押しにもなると思いますので、採択をしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問","question":"ご答弁があったように、予算要求もされたということと、一定の期間で見直しを行っているということで、意義のある制度だと。この陳情者のお考えは理解できるのですけれども、陳情項目で一律増員をすべき旨のような陳情内容にも見受けられるので、今回は不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"その配置については連絡会等できちんとその可否を検討されていると伺いましたが、より一層、適切な配置をお願いしたいと思います。ほかの委員からもお話がありましたが、年度途中の状況にも柔軟に対応するということは要望させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"横山委員","kind":"質問・要望","question":"ただし、個々の特別な配慮を要するお子さんは増加傾向にあります。ご本人のペースに合わせて自立していく力を高めていくという環境をしっかりと整えていただくことを要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川保育問題協議会から１,７２１名の署名とともに出されており、公園などの整備、４点を求めるものです。これは本当にゼロになるのかということをお聞きしたいと思います。","respondent":"大澤保育支援課長","answer":"認可保育園の不承諾の方は、認証保育所ですとか定期利用保育等、ほかの保育施設等の利用によって実質的にはゼロに近い数字になっていくと思います。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問","question":"ほかの認証保育所を利用してゼロになるというお話ですが、やはり認可保育園に入りたいということで希望して入られているということだと思うのです。そういった方は本来、認可保育園に入りたい人だと思うのですけれども、そこの認識を伺いたいと思います。","respondent":"大澤保育支援課長","answer":"乳幼児人口ですが、ピークを迎えた後、いずれは必ず下降になるときが来ると推計でも出ておりますので、それを考えますと、今ある施設を利用することは必要なことだと考えております。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問","question":"今ある施設の活用ということが重要だというご答弁でしたが、どういうことでしょう。申請した人というのは認可を希望している人ではないのですか、ということで伺いましたので、そこのところを答弁ほしいと求めました。","respondent":"大澤保育支援課長","answer":"定員がありますので、すべての方が希望された認可保育園に入園できるということではございません。その場合は、今ある認証保育所等の施設も活用して保育需要に応えていくという考え方だということです。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問","question":"やはり待機児童の問題というのが国の基準ではいろいろと削って数が少なくなってしまい、深刻な状況になっているのではないかと思っているわけです。区としてそういった認識はあるのか、伺いたいと思います。","respondent":"大澤保育支援課長","answer":"不承諾数については、確かに昨年度と比べても増えてありますので、定期利用保育等の利用の数を大幅に増やして対処する予定です。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"改築するために１園あたり８億円ということで、今の区の財政状況でいえば、この改築を進めていくということは可能ではないかなと思うのです。民営化していくということは、この間も言ってきましたがやめるべきだと思いますが、いかがか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"１園あたり８億円から１０億円ですが、保育支援課長から答弁がありましたように、約７割以上が建設後４０年を経過している施設です。これは計画的に改築していくにあたっては相当の費用がかかることが見込まれますのと、一定程度の民営化は必要なものと考えているところです。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"民営化は必要だというお話ですが、保育の質という面でも民営化をしていくというのはやめるべきだと思います。民営化していくことで、保育の質の低下にもつながってくるのではないかと思いますが、いかがか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"安全面はどうなるのだとか、そういったところの質問は出ましたが、民営化に対する不安というのは今回の保護者説明会では聞かれなかった次第です。そのようなところを含めて、区でも今後十分に民営化に対して対応していくものと考えております。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問・要望","question":"保育の質の問題はつながってまいりますけれども、その中で区の独自の人件費助成がされているというお話がありましたが、これはどういったものなのか。直接、保育士への加算というのはされていなかったと思うのですが、そこのところを確認させてほしいと求めました。","respondent":"大澤保育支援課長","answer":"人件費の区独自の加算ですけれども、各施設に対して、例えば特別支援の保育の加算ですとか、看護師の雇い上げ加算、事務職員の雇い上げ加算等を行っております。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"本来的には保育士の基礎の部分というのが上がってこないと、そこの基礎の部分、これを上げてほしいということは区として国に求めていらっしゃるのか。そして、先ほどのご説明とは別の保育士への加算ということでやっていくお考えはあるのか伺いたいと思います。","respondent":"大澤保育支援課長","answer":"東京都に対しては、キャリアアップ補助金等は継続するように区からも直接申し入れは行っているところです。保育士に、直接区から独自に加算することは考えてございません。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"引き続き国や都に求めていただいて、区としてもぜひ独自に加算をしてほしいと求めましたけれども、伺いたいと思います。これがなくなるのではないかというお話も聞いておりまして、そこはぜひなくさないでほしいと思うのですけれども、そこのお考えも伺えたらと思います。","respondent":"大澤保育支援課長","answer":"おおよそ１,６５０人ですので、十分な対応はしていると認識していますので、これ以上の加算をする考えはありません。引き続き継続していただけるように、区からも申し入れしておりますし、今後もそれは続けていきたいと考えています。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問","question":"区として２０億円出して加算をしているというお話でしたが、１.５倍でしたか、その予算ということでしょうか。区が出している２０億円のことについてもう少し詳しく伺いたいと思います。","respondent":"大澤保育支援課長","answer":"２０億円は保育士の処遇改善に係る部分で、キャリアアップ補助金、宿舎借り上げ助成等の合計額です。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、遊び場を確保するためにも公園・広場等を整備してほしいということは当たり前の願いだと思いますので、公園の整備状況を伺いたい。公園の遊具、ぜひ乳児も利用できる遊具も整備をしていただきたいと思うのですが、区としての考え方を伺いたいと思います。","respondent":"溝口公園課長","answer":"幼児、区内にはなかなかそういう広い公園がない中、どうしてもさまざまな年齢の方が遊べる複合遊具を設置していくような形になりますので。最大限、公園利用者の方たちに配慮した遊具の設置も改修に合わせて引き続き行っていきたいと考えているところです。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"保育園として利用する際も、３歳になった一部の子どもたちが利用できて、そうするとみんなが３歳にならないと利用できないという状況になります。３歳以上の子どもたちが利用しているという中で、乳幼児の遊具というのをぜひ一緒に整備をしてほしいと求めましたが、改めて伺いたいと思います。","respondent":"溝口公園課長","answer":"ゾーン分けといったものができれば一番いいと考えていますけれども、なかなかニーズにすべてお答えすることができない状況になっております。とはいえ、複合遊具といったものを設置しながら改修を進めてきているところですので、公園整備にあたっていきたいと考えております。","id":"exchange-058"},{"speaker":"筒井委員","kind":"意見","question":"つまり私立保育園のメリット、デメリットというのはどこにあるのか、簡単にお知らせくださいとの意見を述べました。","respondent":"佐藤保育課長、大澤保育支援課長","answer":"品川区では古くから特別支援保育でありましたり、そういった面に関しましてはメリットが大きいのだろうと考えております。デメリットのほうは… デメリットとしましては、ここ１０年で開設した園が圧倒的に多いですので、どうしても若い保育士が多くなる傾向はあります。そこはやはり経験値という意味では、なかなか難しい部分も否めないなと感じております。","id":"exchange-059"},{"speaker":"筒井委員","kind":"質問","question":"先ほど補助金のお話が出ましたけれども、品川区では民間委託を進めるというような理由というのは何でしょうか。簡単にお知らせください。","respondent":"吉田保育施設調整担当課長","answer":"先ほどの説明の中にもあったのですけれども、そこで検証を行いまして、民設民営に移していくことも検討してまいります。区のほうとしては、民営化するところについての長い目でのメリットはそこにあるのも一つだと考えているところです。","id":"exchange-060"},{"speaker":"筒井委員","kind":"質問","question":"ということは、区としてはそうした財政負担の軽減も考えて、今ある公立保育園をそのまま存続するというのはあまりにも硬直化し過ぎるというような懸念があるというお考えはあるのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"今回の基本方針の中でも、全部の園を民営化するということは予定しておりません。今の基本方針としては、民設民営化を考えていくと、今のところは予定しています。","id":"exchange-061"},{"speaker":"せお委員","kind":"質問","question":"３番目ですが、職員の処遇はかなり改善されていると考えますので、引き続き職員のサポートをお願いしたいと考えています。４番目の公園ですが、それから障害のある方も誰もが使いやすい公園になる予定でありますので、こういった４点のそれぞれの理由から不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"塚本委員","kind":"意見","question":"品川区の施設に対するものというのは一定程度理解できますけれども、そういう意味では広域で考えていくべきものだと考えています。今、対応を進めていらっしゃっている区の方針でそのままやってほしいと求めましたので、以上の理由で不採択といたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"筒井委員","kind":"質問","question":"やはり財政負担上、ある程度民営化、民間委託するのはやむを得ないことかなと考えております。公園も品川区のなかなか狭い土地で土地確保が難しい中増設している、そうした努力をされているということなので、今回の請願は不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"区としてはきちんとチェック、監視という言葉はよくないかもしれませんが、指導をしていってほしいと求めました。公園に関してはご説明をいただいたので、そのとおりだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"横山委員","kind":"質問","question":"区として処遇改善等に取り組んでいること、また公園については、引き続き幅広い事情を踏まえて整備を進めていくことなどの説明がありました。人口推計、多様なデータを総合的に分析して、多様な手法を用いながら認可保育園の開設を進めていただくことが現在必要であると私は考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"}]},{"id":"topic-03","title":"ひがしやつやま・ほうさん保育園の運営期間等","agenda":"ひがしやつやま・ほうさん保育園の運営期間等","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"そのために認可保育園の増設を求めるとともに、入園枠を狭める区立ひろまち保育園の閉園延長を求めるものということになります。そういったことで探してきているわけですけれども、この入園申請の大変さというのを区はどのように認識されているのか、伺いたいと思います。","respondent":"佐藤保育課長","answer":"私のほうで入園相談を所管しておりますので、ご説明いたします。国の通知で示されている優先利用の順番等がありますので、その辺りも見極めて、他区とのバランスをつけて入園調整基準をつくっているところです。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問","question":"この中で３歳の壁というものをどのように考えていらっしゃるのか。その後も当然保育園に預ける、保育が必要だということになると思うのですが、そこのお考えを伺えればと思います。","respondent":"大澤保育支援課長","answer":"その枠が８０以上ありますので、その関係もありまして、大体７割の方しか認可保育園のほうには入園しないのが毎年の状況です。全くの新規で枠があるのが３００少しですので、３歳児の壁というものはなく、入園は可能という状況だと認識しています。","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問","question":"今回、２１０名ということで不承諾が送られておりますが、やはり壁がないと言えるのでしょうか。３歳児でも待機児童ゼロになるというお考えなのか伺います。","respondent":"大澤保育支援課長","answer":"先ほどの説明と同じになりますが、認可保育園に定員がある以上、そういう意味では不承諾が必ず出るのはいたし方ないと考えております。ほかの園を選んでいただいたり、ほかの施設を利用するということで待機児童としてはゼロになると考えております。","id":"exchange-069"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそういった認識に立っていただきたいと思うのですけれども、いかがでしょうかということです。そこの区のお考えを伺いたいと思います。","respondent":"大澤保育支援課長、佐藤保育課長","answer":"大体１.５km2ぐらいになるかと思うのですけれども、その範囲ではどこかに通えるという計画のもとに開設を進めています。そういう中ではなかなかすべてのニーズに応えていくというのは状況としては難しいのではないかと考えておりま… ２点目のご質問の、陳情にある第２条に関しましては、そういった場合に国や地方公共団体に責任が生じるという意味だと理解しています。…","id":"exchange-070"},{"speaker":"のだて委員","kind":"質問・要望","question":"園での状況を見学されていく中で、本当に行きたいというところが２、３園ぐらいに絞られてくるということで書かれていると思うのですね。今回延長するわけですからひがしやつやま保育園のほうはもつのだと思いますが、この今後の延長の可能性というのはあるのか、伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"延長する予定はないかということなのですけれども、５年間で閉園した場合ですけれども、仮設園舎。その際に、一遍に５年で閉じて同時に解体をやったほうが、今のところ５年という形で考えているところです。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問","question":"工事車両の面ということで５年と、今後、検討を進めていった中で延長の可能性というのもあるでしょう。今いる園児が卒園するまで続けて、閉園を延長していくということが重要なのではないかと思うのですが、改めて伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"その辺りは保育園の募集を始めるときから利用者に説明しているところなので理解されているものと感じております。今回、偶然延長することができたというところでございまして、原則は５年で閉じるところを今のところ変える予定はありません。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこの在園児が卒園できるまで続けていただくということでぜひ考え直してほしいと求めました。最後に１点伺いたいのですが、代表質問でもありましたけれども、いかがか尋ねました。","respondent":"大澤保育支援課長","answer":"認可保育園の開設計画ですけれども、子ども・子育て支援事業計画に沿って進めてまいります。現在、昨年度実施した調査結果をもとに新たな計画を策定しているところですので、それに沿って進めてまいります。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問","question":"この計画を今やっているということですが、そこも含めて保育が必要になる子どもたちの割合というのですか、算出を増やしていくべきではないかと思いますので、ぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"筒井委員","kind":"質問・要望","question":"陳情の要旨の２点目、区としてＪＲと計画を立てたということは、その契約というのはあったのですか。強引に延長した場合、ＪＲからやはり損害賠償請求等々そうした訴訟にもなるような可能性があるのか、伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"筒井委員","kind":"質問","question":"所管が違うので、この場では詳細のお話は難しいかと思うのですけれども、時期の延長というのが前にもお話にありましたが、可能性というのはあるのか。相手方があることですから、一方的に区が強行して延長するということが客観的に可能性としてあり得るのかどうかを伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"保育課としては、都市開発部門と調整をとりながら、都市開発部門がＪＲと調整をとってきたところですが、ＪＲ東日本の広町地区におけるまちづくりというのが令和３年３月以降に実施されるため、区としてはそのとおりに考えているところです。","id":"exchange-076"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"そして突然閉園が決まって転園ができない方が多くいらっしゃるという前提条件が私の認識と大きく異なっていますので、採択をすることができません。ただ、ひろまち保育園、あとこれから閉園を予定する保育園の保護者に対しての対応というのは区で引き続き行ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"せお委員","kind":"質問・要望","question":"来年度も増える予定ではありますし、こちらに関して引き続き総合的な待機児童対策を進めていただきたいと思っています。このようなことを踏まえて不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"塚本委員","kind":"質問・要望","question":"３歳児転園ということで認証保育所からの転園ということですが、定員増という政策の中でしっかりと解決していっていただきたいです。認証保育所から３歳児の転園枠というのは十分に確保されているので、ということをお願いしたいと思いますけれども、不採択といたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"},{"speaker":"のだて委員","kind":"意見","question":"今回、やはりこれからも認証保育所の卒園児の転園先を確保していくということは必要だと思います。新たに申し込みする方が入園する枠も減ってしまうということになりますので、あわせて採択をしていきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"筒井委員","kind":"質問","question":"この陳情者の方々が抱えている不安というものを払拭するための丁寧なご対応というのをお願いしたいと考えております。先ほど述べたとおりＪＲという相手方があることですから、相手方がいることを無視して、今回不採択とさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"高橋（し）委員","kind":"意見","question":"転園先確保についてのお話は、先ほどご説明いただいたように認証保育所等のところからの枠を含めた３歳児の枠を確保していくと。それから、ひろまち保育園のほうは、以前にも議論がありましたけれども、当初の５年という計画のところから、延長は難しいと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"横山委員","kind":"質問・要望","question":"利用者の公平性の担保をしながら、今後も多様な手法を用いて認可保育園の開設を続けていただきたいと考えています。これまで議会からの質問やお問い合わせについて５年で閉園するという答弁を行政から得ているところでありまして。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"おくの議員の教育の質問で、教員の病休者の数等があったと思うのですが、その病休者あるいは休職者の年代別の人数を教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=4992#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":49327,"voices":240}},{"id":"r02-20200225-5","meetingId":"r02-cm02","date":"2020年2月25日","dateIso":"2020-02-25","committee":"総務委員会","time":"午前１０時００分～午後 ０時２１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件整理しています。","topics":[{"id":"topic-01","title":"では(1)の第１０号議案からの審査でありますが、会議の運営上、順番を入れかえ、審査を行います。 まず、(5)第２２号議案 東品川海上公園拡張整備工事請負契約","agenda":"では(1)の第１０号議案からの審査でありますが、会議の運営上、順番を入れかえ、審査を行います。 まず、(5)第２２号議案 東品川海上公園拡張整備工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"最近の契約状況といいますか、職人の確保は、今どのような状況になっているのか。職人の確保、建設労働者の確保について、少し現状を報告していただけたらと思いますとの意見を述べました。","respondent":"立木経理課長","answer":"それに対して、中身は起工書の中で必要な人工の部分に関しては、全部計算がされて出ているものです。こちらの応札はできませんというケースもありますが、職人が足りなくなるという状況は、今のところ避けられていると考えております。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"１人で受け持つ人数にも限りがありますので、いろいろそういう状況を伺うので、必要な対応をしていく必要があるのかなと思います。ここから何か酌み取るというのも、少し大変さはあると思いますが、ひとつ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"西本委員","kind":"確認","question":"１点確認したいのですが、この土地というのは、どのような経緯で取得されたのですか。もともと海上公園の延長のところにあったのか、それとも今回、どこからか買ったのか、譲り受けたのか、いかがか尋ねました。","respondent":"立木経理課長","answer":"こちらの土地は、もともと公園用地として取得しているところで、今回整備する部分に関しましては、区がもともと持っていた部分に加えて、道路の接道部分は民有地を購入して整備することになってあります。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"もともと区が持っていたものであるという部分は、使っていなかったわけですか。今回、拡張に当たっては、例えば、こちらから申し入れをしたのか、いいタイミングがあって譲り受けることになったのか、その辺の事情はいかがか尋ねました。","respondent":"立木経理課長","answer":"都市計画決定をするという中で、売却をしてもいいという話があったので、区で買わせていただいているです。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"もう都市計画をやってしまうといや応なしという部分があるとは思うのですけれども、そこのやりとりというのはうまくいっているものなのでしょうか。今回整備するところは遅れてしまったという状況なのか、その辺はどうなのか尋ねました。","respondent":"立木経理課長","answer":"もともと区が運河沿いのほうも土地として所有しているという中で、やはり東側に接道を行いたいという部分で、土地所有者との話し合いの中で、買えそうだということになったので、それをもちまして計画を立てていったと聞いております。","id":"exchange-005"},{"speaker":"西本委員","kind":"確認","question":"もともとの土地所有者の方とうまくいっていればいいのですが、その辺が少し気になったので確認させていただきました。その辺だけお願いします。","respondent":"溝口公園課長","answer":"少し公園整備の詳細な内容になっておりますので、私からお答えさせていただきたいと思います。都市計画変更をして、用地買収等を進めながら、今回の計画に至ったということになっております。","id":"exchange-006"}]},{"id":"topic-02","title":"第１０号議案 品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人情報の提供に関する条例の一部を改正す…","agenda":"第１０号議案 品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人情報の提供に関する条例の一部を改正す…","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"なぜ、そのような法改正が行われたのかというのが質問です。私は問題があると思っているのですけれども、その点についても、区の見解を伺いたいと思います。","respondent":"山本情報推進課長","answer":"各自治体からこういった要望が出たというところで、国が法の改正を行って、番号法に基づいて情報連携を行うことができるとなったものです。今までどおり利用していって、必要に応じて情報連携を行うという分散管理の方法を行っておりますので…","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"一括法にかかわって、自治体からの要望を受けての法改正ということでありますが、自治体からどのような要望があったのか伺いたいと思います。ぜひ、国に対してマイナンバー制度はやめるよう求めてほしいと求めましたが、そちらも答弁。","respondent":"山本情報推進課長","answer":"番号法に基づいて情報連携を行うのが基本だと考えておりますが、これまで、それを運用して情報連携を行っていたところであります。本来提供するべき添付書類の省略等が区民の方へ利便性だと考えていますので、番号制度自体、区民の方にもメリットはある制度と考えております。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"ここから質問なのですけれども、やはりマイナンバーの利用が広がっていることに懸念をしています。漏洩対策をどうしていくのかというところで、リスクの高まりについて、区の見解を伺いたいと思います。","respondent":"山本情報推進課長","answer":"本人確認等も行っておりますので、そういった部分でなりすまし等はできないところが、そもそもの制度のつくりとしてなっていると考えています。ネットワークの分離といって、それから、何らかの形でインターネットから情報が流出しないような仕組みをつくっているところです。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"では、そのような対応をしているため、リスクの高まりは考えていないということでよろしいか尋ねました。","respondent":"山本情報推進課長","answer":"確かに、マイナンバーを使うものが増えるということは、流出リスクが高まるというおそれもあるかもしれないのですけれども、今申し上げたとおり、我々としてはセキュリティ対策を万全にとっておりますので、そういったセキュリティ事故は起こらないと考えております。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"いろいろ変わってきたというところはわかったのですが、例えば(2)について見ると、品川区独自で定めて運用していたということだと思うのです。このマイナンバー制度をどう活用して、今後、住民サービスにつなげていくのかという観点はいかがか尋ねました。","respondent":"山本情報推進課長","answer":"区といたしましては、区独自としては印鑑登録証とマイナンバーカードの一元化を図って、区民サービスの向上に努めているところです。夏ごろ、来年３月から保険証利用も始まるところで、そういったマイナンバー制度の利便性と安全性の周知に努めていきたいと思っているところです。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"状況を踏まえて、この方にはどういう福祉的な支援をするのかとか、一時的にはこういうことが必要になるであろうということが見えてくると思うのです。他部署などいろいろなところの協力体制、仕組みづくりというのも同時に考えていただきたいと思うのですが、いかがか尋ねました。","respondent":"山本情報推進課長","answer":"一部ですけれども、電子サービス等を受けられるという仕組みになっているので、そういったところの拡大も考えていきたいと思っています。個人個人の特性に合わせたお知らせが行ったりというところは、別のツールになりますけれども、そういったところも検討しています。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"これは、こういうものがあるのですよと紹介できるぐらいの仕組みづくりをぜひ今後考えていただきたいなと考えていますので、よろしくお願いします。以上、意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"個人情報の漏洩に対しては、よりセキュリティの向上に向けて、私はこれからも取り組んでほしいと求めました。新しい仕組み、またいろいろな方法ができておりますから、今後も十分注意して取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問","question":"事務の追加というところで、このシステムは、新たに費用がかかって、システムをつくって、追加していくという感じでいいのか尋ねました。","respondent":"山本情報推進課長","answer":"事務の追加のシステム改修ということですけれども、特にシステム改修の必要性はないです。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問","question":"基本的に、今後、またこういういろいろな法律を受けて改修する際にも、余り費用はかからずにシステム改修ができるのかという見通しについて教えてほしいと求めました。","respondent":"山本情報推進課長","answer":"今回の延長夜間保育利用料徴収事務に関しては、システム的な部分で現在の運用で対応できるというところなのですけれども、それ以外のシステムに関しては、その都度判断していく形になるので、費用がかかる場合もあるかと思います。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問","question":"都度かかるということで、わかりました。法律が変わるときに合わせてというところと、通年でというところでどうなのかなと思って伺ったので、ありがとうあります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"中塚委員","kind":"意見","question":"マイナンバー制度は進めるべきではないと思いますので、反対しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"}]},{"id":"topic-03","title":"第１１号議案 品川区職員定数条例の一部を改正する条例","agenda":"第１１号議案 品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今回の定数条例の変更ですけれども、説明の冒頭に行財政の見直しとありましたが、行財政の見直しというのは、どういう意味、内容なのか、そこを伺いたいと思います。","respondent":"黒田人事課長","answer":"毎年度、区としてやらなければならないというものがあります。予算を執行するという形の体制をとるという意味で、毎年度、見直しを行っているものです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"執行体制の見直しということなのですけれども、区が考える行財政改革は何ですか。改めて伺いたいと思います。","respondent":"黒田人事課長","answer":"いわゆる人事の側面から申しますと、人件費が発生いたしますので、当然、その原資は税です。職員が急に減ることはありませんので、翌年度以降、執行体制の見直しに取り組んでいるです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"一般事務と福祉と心理とそれぞれありますけれども、児童相談所開設に向けて、何人まで定数を増やす考えなのか。ご答弁者は人事課になるので、どのように把握されているかも含めて、質問としては、何人まで確保したいと思っているのか、伺いたいと思います。","respondent":"黒田人事課長","answer":"その中では、都の児童相談所の派遣も含めて、経験を積みながら、執行体制を考えていくということです。そういった法改正の過渡期的なところもありますので、そこは所管と協議しながら、遺漏のないような形で進めていきたいと考えています。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"児童相談所を開設している先行事例を見ると、それではとても運営ができないので、自治体の判断で上乗せしているという状況もあるかと思います。先行自治体の状況も見ながら進めていただきたいと思うし、子どもの虐待に対する対応の人員確保や経験、十分な体制を整えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"田中委員","kind":"意見","question":"情報公開で調査し、わかったので、それについては評価をしています。先ほどの説明の中にもあったかもしれないのですけれども、もう一度、人事課と用務の減について、それぞれ詳しくご説明をいただければと思うのですとの意見を述べました。","respondent":"黒田人事課長","answer":"令和２年度の予算の中で、いわゆる社保事務について、少し合理化が図れないかという予算のご提案をさせていただいています。基本的には用務職は退職不補充という方針で進めておりまして、学校の環境整備に当たっているというところで、こちらも実情に応じて減員しています。","id":"exchange-023"},{"speaker":"田中委員","kind":"意見","question":"用務員に関しては、どうして退職不補充となってしまったのか。その経緯や、いつごろそういう方向の決定となったのかというところを知りたいなと思いますとの意見を述べました。","respondent":"黒田人事課長","answer":"複数校を１つのグループとして事業者に委託をして、環境整備という面では、十分対応できていると考えております。用務職を採用するということではなくて、そういった方法を使うことで、全体的な区民サービスを充実させていこうという取り組みです。","id":"exchange-024"},{"speaker":"田中委員","kind":"意見","question":"子どもたちの話しやすい存在であったり、防犯の目にもなっているところであったり、とても重要な役割をされているところがあるのです。区として、用務員についての役割をどのように考えられているのかというのを聞きたいのですとの意見を述べました。","respondent":"黒田人事課長","answer":"先を見通して執行体制を考えたときに、そういったところを活用するということで、全般的な見直しの中で進めている。今も用務がおりますから、変わるところではありませんが、そういったさまざまなやり方で事業の質を担保していくことに取り組んでいるところです。","id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"付則のところで７０名以内という形になっているので、もう既に働かれていて、人数がどこからどういうタイミングで変わっていくのだろうと思うのです。そのタイミングがよくわからないのですとの意見を述べました。","respondent":"黒田人事課長","answer":"条例の施行期日は４月１日ですので、４月１日の段階で、そこに合うように採用活動を進めていく。採用見込みで行っておりますので、４月１日の新年度のスタートに向けて、その上限を超えない形でいろいろ工夫を図るです。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"この付則の７０人はどういう立場の人たちになってくるのか。その７０人がどういう立場になってしまうのだろうと思うのですが、いかがか尋ねました。","respondent":"黒田人事課長、榎本総務部長","answer":"定数外の７０人の考え方なのですけれども、育児休業で７０人ほど休職しておりますと、育児休業中で不在ということになります。年度内で増えたり減ったりということもありますが、そういったことも含めて… ２,５０３人が本則の定数、付則での定数が７０人ということで、令和２年４月１日で、正規職員が２,５７３人を超えないという条例上の定めです。あくまでも、タイミング的に…","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"ただ、そのプラスアルファの方たちが、例えば仮に年度途中に３０人いたという場合に対しても、正規職員の扱いという形になるわけです。その分の給料体系も、その換算でなっていくという話でいいのか尋ねました。","respondent":"榎本総務部長","answer":"要は、どの時点においても２,５７３人を超えないという形ですので、定数外も見込んで、ある程度人数を出しています。上限である２,５７３人は、年度中は超えないという条例上のお約束という形です。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"そうすると、いろいろな事情によって現場の人数が少なくなってしまうという可能性もありますね。民間を活用するのかどうかはわからないですけれども、正規という形ではなくて、違う方法を使って補う分を何とかするという感覚でよろしいか尋ねました。","respondent":"黒田人事課長","answer":"なかなか集まらないところについては、いわゆる非常勤を活用するとか、人材派遣のほうで人員的な措置をする。さまざまな方法を使って、欠員になった部分については対応していくという状況です。","id":"exchange-029"},{"speaker":"西本委員","kind":"意見","question":"これだけでは足りないという事業の内容も今後出てくる可能性もあるので、そうなった場合に、やはり必要なところにはそれなりの人を充ててほしい。しっかりリンクする形でとっていただいて、余り負担を強いるような状況にはしてほしくないなと思いますので、今後との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"田中委員","kind":"意見","question":"用務の人員減のところで、民間活用ということだったのですけれど、この民間の活用というのは、環境整備の民間事業者なのか、どういった民間の活用なのかというところを聞きたいのですとの意見を述べました。","respondent":"黒田人事課長","answer":"用務を減したところをストレートに業務委託だけではなくて、それ以外の人員的な措置も含めて、全体的な運営をしています。","id":"exchange-031"},{"speaker":"大倉委員","kind":"質問・要望","question":"何か目標があって、そこにはまだ届いていないというところで、この２人でどうなるのかというのと、どのくらいの方に受けてもらっているのか。所管があるので、わかるところで教えてほしいと求めました。","respondent":"黒田人事課長","answer":"そのうち１名が指導主事を兼ねているということで、学校現場に配属されている固有教員は２９名という計画で、進めてあります。どういった方かですが、そういった方にご応募いただいて、教員になっていただいているという実態ではないかなと考えています。","id":"exchange-032"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり私は、品川区には特にいい人材を１人でも多く採用してほしい。いい人材を品川区に持ってきて、今考える時期ではないかなと思いますので、そういう方向で今後も取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"つる副委員長","kind":"質問","question":"平均して、一般的に区の職員の異動のタイミングというのは、何年に１回ぐらいのスパンであるのですか。部課長というか、理事者以外の一般職員の人たちはどのぐらいあるのか尋ねました。","respondent":"黒田人事課長","answer":"通常の異動ですと５年を目安にということもありましたが、確実的に何年でということはありませんが、かつてはそういった目安もあったです。","id":"exchange-034"},{"speaker":"つる副委員長","kind":"質問","question":"所管が異なってしまうかもしれないですけれども、児童相談所に行き着くまでのアプローチというのでしょうか。そうした規定があるのかどうかということが、もしあれば説明を求めました。","respondent":"黒田人事課長","answer":"そういったところも２３区で児童相談所の経験のある者の採用に取り組みましても、生活保護のような事務で、障害分野の経験も必要です。その者が持っているスキルやキャリアを勘案しながら、また、そういう点も勘案した人事異動をしていかなければならないなと考えています。","id":"exchange-035"},{"speaker":"つる副委員長","kind":"確認","question":"開設に際しては、オープニングスタッフではないですけれども、そのような意識づけを持っての人事のやりとりはあるものなのですか。人事ローテーションでいろいろなところを経験させて、その場に戻るということはあるのか尋ねました。","respondent":"黒田人事課長","answer":"確かに虐待対応という１つを捉えますと、東京都との連携も、区として対応できるような対策をとっていかなければいけないということです。その中の１つとして、職員の個々のスキルによってさまざま違うと思いますが、適切に対応できるように取り組んでまいりたいと考えています。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"学校用務員の専門性を奪い、チームとして学校が動く際にも、弊害となる民間委託はやめてほしいと求めました。ぜひ現場の声をよく聞いていただいて、対応していただきたいと、ここは要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"田中委員","kind":"意見","question":"答弁からは、その辺の不安感が拭い切れなかったためです。用務員がいることによって、学校現場での職員の負担も軽減されてきたと思うので、反対したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"}]},{"id":"topic-04","title":"第１２号議案 職員の服務の宣誓に関する条例の一部を改正する条例","agenda":"第１２号議案 職員の服務の宣誓に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"少し教えていただきたいのですけれども、地方公務員法で服務の宣誓をしなければならないと規定されているということです。そこもご説明ほしいと求めました。","respondent":"黒田人事課長","answer":"申し上げますと、「私は、ここに、主権が国民に存することを認める日本国憲法を尊重し、かつ、擁護することを固く誓います。国が準則として定めておりますので、各自治体とも、これに準じた形で条例に規定されていると考えています。","id":"exchange-039"},{"speaker":"中塚委員","kind":"提案","question":"条例改正が提案されていると理解しているのですけれども、区民から見れば職員なので、そこに宣誓が必要ないとする根拠はどこなのか。その辺についてもご説明ほしいと求めました。","respondent":"黒田人事課長","answer":"やらなければならないことが出てまいりましたので、あくまでも形式的に誓うところでもありますので、そういった対応をとるものです。それが現在、非常勤職員が宣誓することが法令で定められていなくても、当然、守るべきところかなと思ってあります。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"その中に、国に対して先頭を切って運動をするということが見受けられる部分があるのですが、それは、職員としてはどうなのかな。どういう位置づけで、私は余りそのようなことはされてはいけないのではないかと思っているのですが、そこの仕切りはどうなっているのか尋ねました。","respondent":"黒田人事課長","answer":"勤務しないということがあれば、当然、処分の対象になるということはあります。そこは、考えを示すというところとは別に、服務として守らなければならないことを守らなければ、処分の対象になるという関係です。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"どういう部分だと服務規程に反する行為なのかというのは示されているのでしょうか。こういうことは服務規程上から外れていますというような指針といいますか、マニュアルといいますか、そのようなものは存在しているのか尋ねました。","respondent":"黒田人事課長","answer":"今回ご提案している条例は、あくまでも採用するに当たっての宣誓です。これは、職員として違反した場合については懲戒処分の対象になるという規定が別にございまして、そちらは職員のほうに周知しています。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"採用するときの法律の規定に対する宣誓ですから、服務規程とは何かというところは、ぜひ教えていただきたいなと思います。そこら辺を示すことはできるのか尋ねました。","respondent":"黒田人事課長","answer":"そこが服務に関連してくるかどうかというのは、ケース・バイ・ケースかなということがあります。主張を通そうとして仕事をストライキするということであれば、ストライキに対しては懲戒処分がありますし、内容によるのかなと思ってあります。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、そういう規律があるのであれば、やはり示してほしいなと思いますし、徹底してほしいなという部分もあります。これは要望ですので、今後、また個人的にでも教えていただければありがたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"須貝委員","kind":"質問","question":"現在の国家公務員も、もちろん該当するならば、宣誓書に反したら処罰されるということがあるのでしょうか。その辺について、個人的でもいいのですが、見解を説明を求めました。","respondent":"黒田人事課長","answer":"採用する際に、公務員としてということで宣誓をしなければ職務に当たることができないという法律の規定もありますので、それに対応して宣誓する。懲戒処分の対象になると思いますけれども、一律にこうであればというところは申し上げにくいので…","id":"exchange-045"},{"speaker":"須貝委員","kind":"質問","question":"我々がどう見てもうそをついているとしか思えないのですが、こういうお話をお聞きしたので、少し質問したわけです。恐らく多くの区民にとっても、これは聞いておきたいという質問であったと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"田中委員","kind":"意見","question":"しかし、今回の議案は、会計年度任用職員のいい面として、任用されている間は正規職員としての扱いを受ける。したがって、服務の宣誓をするということなので、この議案には賛成したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"}]},{"id":"topic-05","title":"第１３号議案 職員の特殊勤務手当に関する条例の一部を改正する条例","agenda":"第１３号議案 職員の特殊勤務手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいことは、この申し合わせというのは、どのような形で確認をされたものなのか。合わせて、東京都の児童相談所は月額で、今回の申し合わせでは日額ということですけれども、その理由についても伺いたいと思います。","respondent":"黒田人事課長","answer":"これは統一交渉ではありませんので、考え方については、金額の水準を定めました。児童相談所の設置を表明していない区もありますが、そういったところも含めて、考え方についてはすり合わせをしているというものです。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"2)のことなのですが、「家庭訪問、指導、相談等」と書いてあるのです。指導と相談というのは、外でも施設内でも該当するという認識でよろしいか尋ねました。","respondent":"黒田人事課長","answer":"ご指摘のとおりでございまして、児童相談所で児童福祉士として、いわゆるケースワーク業務に当たったということです。それは、訪問であっても、所内であっても、そういった業務に当たったものについては、日額で支給するということを想定しているものです。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"特に家庭訪問、指導、相談という中で、日額４９０円ですか。私は、それなりの対価というものは必要なのではないかと思っているので、もう少しこの金額の根拠を教えてもらえますか尋ねました。","respondent":"黒田人事課長","answer":"児童相談所を設置している近隣の政令市等においては、日額４００円という中では、特別区としての対応として４９０円ということです。基本的に公務員の給与制度という中では、他の自治体との均衡も図られるべきというところがございまして、こういった金額となったものです。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問・要望","question":"ここは自由なわけですから、一応２３区で合わせましょうという形でやっていますが、別に自由に決めていいのですよね。これが、「給料を１,０００万円あげるからやりませんか」と言ったら、やる人はいるのではないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"須貝委員","kind":"質問・要望","question":"２３区一律云々というのももちろんわかりますが、人であるわけですから、その資金の一部を有効に使う。今後も努力して、検討して、私はやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"つる副委員長","kind":"確認","question":"確認すると、災害時が５９０円、清掃が７００円を超えない範囲でと規定されているわけです。その辺の検討をする、また変動性は、考え方としてはできるものなのか尋ねました。","respondent":"黒田人事課長","answer":"夜間保育園を１０時まで開設しているのが品川区だけということで、仕事の特殊性によりまして、金額については検討すべきものと考えます。児童相談所の設置に当たりましては、先行３区が児童相談所を設置するというところと、議論があるだろうと考えています。","id":"exchange-053"},{"speaker":"つる副委員長","kind":"質問・要望","question":"それに対する手当はあってしかるべきだと思うのですが、服務の宣誓もありましたけれども、そういう高い精神性が求められる。保育士含め、社会全体として求められているからこそ喫緊の課題として保育士の処遇改善が近年ずっと手厚くされてきたということを考えると、当然。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"田中委員","kind":"意見","question":"今回の手当については、２３区での申し合わせとともに、労働組合との協議もあったと聞いています。今回から始まることなので、他区の状況等、これからの様子を見ながら、金額の妥当性についてなど、注視していきたいと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"}]},{"id":"topic-06","title":"令和２年陳情第１１号 タウンミーティング開催を求める陳情","agenda":"令和２年陳情第１１号 タウンミーティング開催を求める陳情","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"やはり区長が率直に区民と対話する機会を設けるということは、私はとても大切なことだと考えています。前回も伺いましたが、学生と話をすることをもって、なぜ一般区民との直接対話をやらないのか伺いたいと思います。","respondent":"木村広報広聴課長","answer":"先ほどの説明と重複いたしますが、それでは、本年度から少しそのような形でやってみようということでやったことです。前回もご説明いたしましたが、次はこのテーマで、こういう人たちとやってみようという形で展開も考えてまいりたいと考えています。","id":"exchange-056"},{"speaker":"中塚委員","kind":"確認","question":"今のご説明ですと、区長は区民との対話を継続しているというお話がありましたけれども、どういう企画なのか伺いたいと思います。そこも確認させてください。","respondent":"木村広報広聴課長","answer":"それから、今後に関しましては、これも繰り返しになりますけれども、固定ということではございません。対象を固定せずに、引き続き、区民の方から声をいただくという場面を設定してまいりたいと考えております。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど、それは、今やっている「しながわ未来トーク」のことを指しているという意味だったのでしょうか。ぜひそのように進めてほしいと求めましたのと、採択をしていただいて、区長と区民の対話を広げていただきたいなと皆様にお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"田中委員","kind":"質問・要望","question":"私も、やはり若い世代の声を聞いてほしいという区議会からの要望があって、それはそれで続けていただいていいと思うのです。今までのタウンミーティング、特に対象を限らずに集まれるような設定であってもいいのではないかなと思うのですが、その辺はいかがか尋ねました。","respondent":"木村広報広聴課長","answer":"先ほども少しご説明させていただきました日時や場所にとらわれずに、そういうところでやりとりをさせていただいているという場面もあります。機会としては、そのような形で今後も進めさせていただきたいと考えております。","id":"exchange-059"},{"speaker":"田中委員","kind":"質問","question":"そこら辺について、区としての見解を伺いたい。その辺についても少し伺いたい。","respondent":"木村広報広聴課長","answer":"１つ、そうすると、どうしてもそこへ行けない方も出てくる。ずっと続けて、幅広でやってまいりますので、ご理解いただきたいと思います。","id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"そうなのでしょうか。区民の人たちはそれを求めているかというと、そうではないと私は非常にギャップを感じてしまっています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"須貝委員","kind":"意見","question":"聞くほうもちゃんと伝えられるかどうかというのは、さまざまな手法を利用されて、今後も区に対してご意見をきちんといただけたらいいなと思います。私はどちらがより効率がいいのかなと考えると、タウンミーティングに関しては消極的な考え方を持っておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"つる副委員長","kind":"質問・要望","question":"確認だけです。確認ができているのですけれども、区側の真意というか、本来の趣旨が伝わりづらくなってしまっているのかなということがあると思うのです。","respondent":"木村広報広聴課長","answer":"今おっしゃっていただいたところは、まさに私も先ほど気づいてしまったところでありまして、しっかり広聴手段の１つとしてやっていることもありますので、そこはちゃんとやっていきたいと思います。","id":"exchange-063"},{"speaker":"小芝委員","kind":"意見","question":"本日、結論を出すということでお願いします。１２月のときにも発言させていただきましたが、声なき声も政治に反映されるべきだと思いますし、この陳情に関しては不採択といたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"大倉委員","kind":"質問","question":"今までやってきた経緯があって、もっと若い人たちにということで、区長もこういった判断をして行っているということです。しっかりと区長が考えたやり方を行っていくということでいいのかなと考えていますので、態度としては不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"つる副委員長","kind":"確認","question":"本日、結論を出すということで、態度については、不採択です。先ほど、確認させていただいた点や、前回の陳情のときに意見を述べていますので、同様ということになります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日、結論を出すということと、態度としては、前回同様、採択を主張したいと思います。地方自治の発展に欠かせないと思いますので、ぜひ進めていただきたいということで、賛成いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"田中委員","kind":"意見","question":"新しく転入された方の声というところも、ああ、確かにそうだなと思いました。そういった方たちの意見交換の場が必要だと考えますし、タウンミーティングが開催されてほしいなと思いますので、採択としますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問・要望","question":"本日、結論を出していただきたい。意見は先ほど申しましたので、お願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2158#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":41630,"voices":193}},{"id":"r02-20200226-6","meetingId":"r02-cm02","date":"2020年2月26日","dateIso":"2020-02-26","committee":"区民委員会","time":"午前１０時００分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"この加入率というのは何の何に対する割合かということを伺いたいのと、私は余り、なかなか大変そうだというふうにも見える部分もあるのですね。それが２点質問です。","respondent":"川島地域活動課長","answer":"こちらは町会・自治会から報告いただいたものをもとにこちらで集計してまとめているものです。先ほどお話しした検討会の中でも、その辺もどこか整理できないものかというようなことで、これまでもいろいろ行ってきたところです。","id":"exchange-001"},{"speaker":"藤原委員","kind":"質問・要望","question":"率は横ばいだけれども、実の人数は増えているのでしょうか。何が知りたいかって、やはり、高齢者の方の率のほうが多いのかというのを伺いたいのです。","respondent":"川島地域活動課長","answer":"住んだら加入するということではなくて、何らかの申し込みというか申請行為が伴うものだというふうに認識しております。委員おっしゃるとおり、率は同じでも町会・自治会加入者の数というのは増えているというふうに認識しております。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"最後の答弁のことでまず伺いますけれども、やはり行政の１つの大切な仕事として、数字的な統計はとっておくべきだと思うのですね。９０歳以上とか、やはり担当として押さえておくべきだと思うのですけれども、そこの町会から上がってくるということか尋ねました。","respondent":"川島地域活動課長","answer":"今、委員ご指摘のとおりの形で町会員のカウントをしているところです。それから、少し研究というか検討させていただければと思います〔同日後刻に「世論調査でアンケートを行っている」と答弁訂正あり〕。","id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"それは、あれですよね。やはりあくまでも町会のほうで探してくださいということになるのか尋ねました。","respondent":"川島地域活動課長","answer":"この条例制定以降に建てられたマンションでしたら、当然どなたか存在しますので、地域センターの所長、もしくは地域活動課にご相談いただければ、どなたが連絡調整員になっているかというのは報告することになっております。","id":"exchange-004"},{"speaker":"くにば委員","kind":"質問・要望","question":"お伺いしたいのですけれども、その自治体の事例などをお教えいただきたいのと、前年度・今年度で実際に執行されたこちらのトップランナー事業をお教えください。","respondent":"川島地域活動課長","answer":"平成３０年度、５つの町会で、こちらは防犯カメラの設置というところもその事業ということになっております。それからいろいろな講話をするというような内容で、そのときの装飾品代ですとか衣装品代、それから参加者の弁当代等を補助金として支給したものです。","id":"exchange-005"},{"speaker":"くにば委員","kind":"質問","question":"今のお話を伺った限りでは、こういった取り組みをしていただいた場合に補助金の対象になりますであるとかの、何か具体的な例示をしてあるのかどうか。先ほど申し上げたような、わかりやすい例示をしているのかどうか、お答えください。","respondent":"川島地域活動課長","answer":"やはり、昨年度はこういう事業が採択されましたというような説明をさせていただいているところです。実際に１件だけという形になりましたので、地域センターとも連携しまして、せっかくの制度を使っていただけるようにご説明。","id":"exchange-006"},{"speaker":"くにば委員","kind":"提案","question":"そういった方々が１件だけしかなかったということで、もし、実際には通らなかったけれどもご提案があったものの４件がどういったものだったのか。なぜ、実際の事例が積みあがっていってこそ１つの具体的な例になると思うのですけれども、少しお話をお伺いできますかとの意見を述べました。","respondent":"川島地域活動課長","answer":"具体的な申請までは至っておりませんので、採択になるかどうかというところですから、内容の確認までまだ追えていないところです。貴重な、大事なご意見だというふうに認識しておりますので、私どもで履歴が追えるような形で確認等とれればというふうに思っております。","id":"exchange-007"},{"speaker":"くにば委員","kind":"質問・要望","question":"２つ目をお伺いしますけれども、１年以上更新されていないのが、済みません。やはり、それぞれの町会に対してホームページを活用していただくための取り組みをどうなさっているのか、そちら２点を伺いたいのですが。","respondent":"川島地域活動課長","answer":"それから、こちらの支援のご説明というか周知、非常に大事なところです。こちらも、先ほどの補助制度の説明のときに、補助金の説明と一緒にこういう支援をやっているというご案内を毎年させていただいているところです。","id":"exchange-008"},{"speaker":"くにば委員","kind":"質問・要望","question":"若い方々がどういうことをしているのかというのがわかりやすいように、区のほうで２０１分の２２しか、ここは力を入れてほしいと求めました。何かプラスアルファとして施策として考えていらっしゃることがあるのか、取り組みができているのかどうか、そちらの２点をお伺いします。","respondent":"川島地域活動課長","answer":"魅力ある活動をしていただけるような金銭的な支援と、大変省力化して、しかも効果があるような部分を使っていただけるような活動の促しというのを区でしていくのが必要になってくるのだというふうに考えております。","id":"exchange-009"},{"speaker":"くにば委員","kind":"意見","question":"本当に区の基礎となる町会・自治会、こちらの単位について、やはり全国の自治体でさまざまな、もちろん取り組みをしてらっしゃると思うので、こちらの全国の自治体の取り組みを調査研究していただきまして、品川区の継続的な町会・自治会の発展に寄与できるように、ぜひともとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010","title":"町会・自治会支援"},{"speaker":"木村委員","kind":"意見","question":"公園の清掃１つにしても、なぜごみを持ち帰らなければいけないのか、いろいろなことが起こると思うのです。その点、どのように考えますかとの意見を述べました。","respondent":"川島地域活動課長","answer":"区はメリットがあるようなものに支援をしていくというのが１つ大事だと思うのですけれども、先ほども説明しました補助のメニューの拡充の中で。整理統合はいたしますが、その事業のメリットを区民の方に還元できるようにというような考えで、私どもは今仕事を進めているところで…","id":"exchange-011"},{"speaker":"湯澤委員","kind":"質問","question":"イコールで町会費に結びついているものなのかというのをお聞きしたいのと、あとは、増えているのかどうかというのをお聞きしたい。もう１つが、これについても、こういったものに関しても行政書士に業務をしていただくということが可能なのか尋ねました。","respondent":"川島地域活動課長","answer":"先ほど説明をさせていただきました協力員の方をご登録いただいていて、これを動かすようなところというのは、町会長さんにもお知らせするとか。つくるとき、本当に町の方にもあちらからご説明にいらっしゃるというところなのですけれども…","id":"exchange-012"},{"speaker":"湯澤委員","kind":"意見","question":"町会の情報、そういったものを発信していただくというのも大切なことだと思うので、そういった対策も必要かなというふうに思います。そういうことも一声かけながら、されているかもしれませんが、しっかりとしていただければと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"町会・自治会数をまず教えていただきたいのと、あと、条例制定前の加入率はどうだったかというのを参考までにお聞きしたいと思います。その２点をお願いします。","respondent":"川島地域活動課長","answer":"平成２８年度が５９.３９％、平成２９年度が６０.４９％、平成３０年度が５９.８６％。令和元年度につきましては５９.９６％ということです。","id":"exchange-014","title":"町会・自治会支援"},{"speaker":"こんの副委員長","kind":"質問","question":"そうすると、区が今全体の数字だけを把握をされているというお答えでしたが、各町会の加入率というのも把握をされていらっしゃるのでしょうか。いろいろな要因でこの加入率とかいうのを考えると、区としても押さえておく必要があるのではないかと考えるのですけれども、その点いかがか尋ねました。","respondent":"川島地域活動課長","answer":"いろいろな意味で、そちらのほうがいいという方もいるかもしれませんけれども、現状では公表はまとめた数字でするような形になっております。どこまでだったらいいのかというのはあるかもしれませんが、そちらについては、今後の検討課題という形にさせていただければと思います。","id":"exchange-015"},{"speaker":"こんの副委員長","kind":"質問","question":"区としてどうパートナーシップを築いていくかということであるならば、公表ということでは必要は、ある意味ないと思います。たとえ１枚の申請書であっても、丁寧には教えてはいただくのですが、その点でご答弁があればお願いします。","respondent":"川島地域活動課長","answer":"私ども、地域に寄り添った形で所長、それから地域支援係が一生懸命支援しているつもりではありますが、もうより一層、そういったところの相談事、それから、申請書類の作成支援等に努めていく必要があるというふうに考えております。","id":"exchange-016"},{"speaker":"こんの副委員長","kind":"質問","question":"やはりどうしていいかわからないというところの、よりその辺のところを、読み取っていただく。その点、お願いをしたいところですけれども、ご答弁がありましたらお願いします。","respondent":"川島地域活動課長","answer":"さまざまなお困り事というか相談事につきましては、やはり各所長にも、今まで以上にウエルカムの姿勢というのでしょうか、相談しやすいような姿勢でいていただけるようにするように、私からも働きかけをしてまいりたいと考えています。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2860#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":20591,"voices":50}},{"id":"r02-20200226-7","meetingId":"r02-cm02","date":"2020年2月26日","dateIso":"2020-02-26","committee":"厚生委員会","time":"午前１０時００分～午後 ３時４２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を82件整理しています。","topics":[{"id":"topic-01","title":"品川区立障害児者総合支援施設の愛称","agenda":"品川区立障害児者総合支援施設の愛称","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"どうしてそのようなことになったのかといういきさつを詳しく教えていただけないでしょうか。開設のときに、その愛称の話というのは、事業者からどのようなお話になっていたかお教えください。","respondent":"築山障害者施策推進担当課長","answer":"いきさつですけれども、愛称については、当初は愛称をつけるという予定はありませんでした。区民のお声を聞きながら愛称を決定したいという区の考えがございましたので、公募に付して、今回の流れになったです。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"運営法人が決めた後で、区が愛称をつけると決めたのですか。そうした一つ一つの混乱と言ったらいいのですか、信頼関係のなさを見せるというのはあまりいいやり方ではなかったと思います。","respondent":"築山障害者施策推進担当課長","answer":"ですので、運営法人もそれ以降、運営法人が決めた愛称については使ってはおりません。公募をするということに至りましたので、運営法人とも、もちろん当時の過程を経ての公募を実施させていただいたというところになっております。","id":"exchange-002"},{"speaker":"あべ委員","kind":"質問","question":"運営法人がこの愛称を内部で決めて区にご相談をしたのは、これは開設の後ですか、前か尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"開設の前です。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"決めるなら区であるということを言ったのであれば、開設のときには、そういったアナウンスは一切なかったと思うのですよね。何か少し順番が違うのではないか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"現時点ではまだすぐにではないのですけれども、公募等も含めて検討する旨を法人のほうに伝えています。開設後、区民の皆様からのご意見をお聞きしまして、公募を実施するという形になったです。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"その後、それが撤回されて、愛称を区が新たに募集したというふうに理解をしておりますが、それは違うのでしょうか。だけど、利用者も含めて、その名前を開設後に知っているのはおかしいのではないか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"愛称については、区のほうで最終的に決定をするので使わないでほしい旨、運営法人には伝えておりますので、その愛称が外に出たということについてはちょっとこちらのほうではわかりかねます。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問・要望","question":"そもそも、この１０月の開設の前に、私は１つの背景だと考えています。何と言ったらいいのでしょうか、そして、その不具合を全て事業者側の責に押しつけるのはやめていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"渡部委員","kind":"質問","question":"区立の施設ですから、４つの事業者で話し合われて、きっとそういうことはなかったのだと思うのです。１ですよ、どうぞ自由にやってください、それは利用者の方がわかりやすいようにやっていただくのは区としてもありがたいことであると。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"愛称が必要ではないのですかと。オープンの当日のときにも、これは愛称が必要ではないのですかというのは申し上げましたよね、覚えていらっしゃると思いますけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、初めはそういう方針だったのでしょうかということが１点。障害者団体、地域、この愛称選考委員会のメンバーを教えてほしいと求めました。","respondent":"築山障害者施策推進担当課長","answer":"当初の説明のとおり、障害児者総合支援施設のままで考えておりました。そこは大まかにご説明させていただきたいと思うのですけれども、障害者団体の方、民生委員の代表者の方が合計で４名いらっしゃいます。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ということは、こういう愛称になったということは、法人のほうとしても納得されているということでいいのでしょうかということが１点です。そういうところでは、区も事業者と一緒になって、その点についても説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"各法人も出ておりますので、その結果を踏まえてということでご理解はしているかとは、していただけるかとは思っております。管理、運営を協力体制のもと、実施していきたいと考えています。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"何て言ったらいいのですかね、何て言ったらいいのですかね、そういうハレーションを見せないでいただきたいのです。この愛称を決めるのはスタートラインではありますけれども、いつまで経っても不信感が残ってしまいますので、ぜひ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"}]},{"id":"topic-02","title":"「しながわ健康プラン２１」中間・評価見直し（案）およびパブリックコメントの実施結果","agenda":"「しながわ健康プラン２１」中間・評価見直し（案）およびパブリックコメントの実施結果","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"まず、このパブリックコメントについて、どのように評価をされていますでしょうか。「しながわ健康プラン２１」という比較的広いテーマの中ではありますけれども、その他、パブリックコメントについての評価をお願いいたします。","respondent":"高山健康課長","answer":"そういった全体的な動きに必ずしも快く思っていないという反応が非常に端的にあらわれているというような感触を得ています。健康増進の分野においては喫煙を是認する要素は全くありませんので、やはり受動喫煙防止を進めつつ、特段の変更を加えるという考えはございません。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"結果的に、一部の強い意見だけになってしまって、なかなかパブリックという結果にならないかなと思います。これだけではなかなか周知として足りないのではないかと思うのですが、その点、いかがお考えか尋ねました。","respondent":"高山健康課長","answer":"パブリックコメントを実施した時期に、とりわけ、ご意見が分散してしまったということも要素の一つとして考えられるのではないかと思います。今後、今後は新たな手法なども組み入れながら…","id":"exchange-013"},{"speaker":"あべ委員","kind":"意見","question":"中身についてなのですが、基本理念が加えられたというのはとてもいいことだと思います。これは全体構成として、どういう発想の中でこういう章立てになっているのか、解説してほしいと求めました。","respondent":"高山健康課長","answer":"今回、策定ではなくて、あくまでも中間・評価見直しというプロセスの中で、このいわゆる冊子の形式で計画案をつくっているところです。主に４章以降、３章以降を中心に、そういった意味があるかと考えております。","id":"exchange-014"},{"speaker":"あべ委員","kind":"意見","question":"それをどうしろと言うのも何ですけれども、もう少し伝わりやすいといいますか、すっきりここで構成が見えるのではないかなと思います。よりよいものにしたいということですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"何ていうのですか、そういう状況にある中でのこのプラン２１の見直し、中間・評価見直しというものだったわけですよね。何ていうのですかね、その点、まずいかがか尋ねました。","respondent":"高山健康課長","answer":"このパブリックコメントの実施について公表、集まってきた意見を真摯に受けとめるというのが基本的なスタンスなのだろうというふうに考えています。地域で説明、きちんとご説明してまいりたいというふうに考えておりますので…","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから少し確認させていただきたいのが、改めて次に反映させていくということでされていくのかということが１点です。どこか業者とかは入っているのか、もし入っているのであれば、どういう業者が入っているのかということについても教えてほしいと求めました。","respondent":"高山健康課長","answer":"あるいは例えば５年の中間年かは少し検討にはなるのですけれども、やはりその進捗についてはともに確認をしてまいりたいというふうに考えております。そういうこともありまして、庁内検討会については３回、検証会については２回実施していっているところです。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"何というのですかね、厚労省でも明確にもう出していて、もう否定しようがないところまで行っていると思うのです。３８、３９ページのところに資料として出していただいたのはとてもよかったと思うのですけれども、その点について再度説明を求めました。","respondent":"高山健康課長","answer":"３６ページ目、地域の方々に平易にわかりやすく健康に関する取り組みを説明し、そういった出張健康学習などの事業などもあります。これは４月以降、この取り組みをすることで、相乗効果でこのような取り組みが前進していけばというふうに考えております。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"１１ページか、これは誰がどのような形でアンケートをとられているのか、これを少しお聞かせほしいと求めました。特定健診データと比べると、非常にこれは根拠としては弱いのかなというふうに思いましたので、これのご見解だけお聞きしたいと思います。","respondent":"高山健康課長","answer":"アンケートの規模といたしましては４,０００名程度の方からご意見をいただいたといったところがこの記載の統計資料の根拠となるものです。やはりこれを後期５年に向けては偏りのない資料、後期に向けては採用しないという方向で…","id":"exchange-019"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やはり他区と比べても、ぜひそこはあり方として検討していただきたいなと思うのですけれどもいかがでしょうか。３８ページのようになっていくというのはよかったなと思うのですけれども、何ですかね、そこはいかがかということです。","respondent":"高山健康課長","answer":"本区においては、企画部門で全庁的な対応について統一的なものを出していくといった中では、そのパブリックコメントの要綱に基づいて実施しています。それから３８ページのコラムのほうが見にくいという点ですが、カラーになった段階で…","id":"exchange-020"},{"speaker":"渡部委員","kind":"意見","question":"でしたら、せめて第３章と第４章の入れかえぐらいやったほうがいいのかなと。第１章があって、第２章があって、第３章と第４章はせめて入れかえたほうがいいのではないかなと思いますとの意見を述べました。","respondent":"高山健康課長","answer":"少し先ほどもご説明しましたように、今回、中間・評価見直しということで、第１章、第２章、第３章で、要するに、前期で浮き出てきた課題を重点的なものとして取り組むべき施策として浮き出した上で、第４章以降という形のほうで……。","id":"exchange-021"}]},{"id":"topic-03","title":"「品川区がん対策推進計画」（案）およびパブリックコメントの実施結果","agenda":"「品川区がん対策推進計画」（案）およびパブリックコメントの実施結果","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"つくり終わってから誰かに説明するのではなくて、説明をしながら意見を求めていくというようなことをすれば、意見をもらう以上に関心を持ってもらう。ごめんなさい、いろいろ言いましたけれども、お考えについてお伺いできればと思います。","respondent":"高山健康課長","answer":"パブコメを一つのプロセスと考えずに、説明をしながら計画をつくっていくというのが一つではないかといったようなご意見をいただきました。そういった説明のプロセスにおいては十分ではなかったというようなご指摘をいただくかもしれませんが…","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問・要望","question":"それともう一つ、この文章を書いているのは何かプロにお任せしているものなのでしょうか。がん予防の普及啓発という段落の下から２行目、３６ページの１行目とか、今後のスケジュール的にはどのような感じになっているのか尋ねました。","respondent":"高山健康課長","answer":"あくまでも２月２６日バージョンということ、計画案として、計画として決定していくものです。最終的に私の目できちんと確認して、正しいもの、正確なものとしてつくってまいりたいと考えております。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"概要版とか、区民向けの何かコンパクトなものというのはつくる予定があるでしょうか。あれば説明を求めました。","respondent":"高山健康課長","answer":"先ほどの健康プラン２１と同様に、これをこのままというのはなかなかとっつきにくいと思いますので、概要版をつくるという予定はあります。この中のエッセンスを抽出して、概要版として、よりよい、読みやすいものをつくりたいというふうに考えております。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"少し代表質問でも取り上げたのですけれども、本当に説明会はやらない、ずっと求めてもやらないという方針で来ているのだと思うのですよね。それから、せっかくできたこの計画をどのように活用していくのかという点では、どう考えられているのか説明を求めました。","respondent":"高山健康課長","answer":"今回、やはりそういった５年間の間でやはり中間的な評価を含めた進行管理をしていく必要があるというふうに考えております。そうした教育面からの取り組みが奏効するというふうに考えておりますので、そして我々、活用されていくものというふうに考えております。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひそういう方向で、今後、検討していただきたいということで要望させてほしいと求めました。「しながわ健康プラン２１」のほうは株式会社創建が入られているということだったのですけれども、この業者は入っているのか尋ねました。","respondent":"高山健康課長","answer":"健康プラン、健康増進計画と、それからがん対策推進計画の２つを同じ会社にお願いしたいというような経緯です。その他の委員につきましても、年２万円を少し下回るような金額でお支払いしていたというふうに記憶しております。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう運営方針が出ていますけれども、これに基づいて、健全化計画というのを品川区がつくったものということなのでしょうか。それで、その健全化計画というのはもう既に計画そのものができているということで、今回はその実施状況の報告書ということなのか尋ねました。","respondent":"池田国保医療年金課長","answer":"この実施状況報告書ですけれども、こちらはまず、左側の年度、これが平成２８年度の時点のものということで数字を押さえてあります。この３億円の部分を６年度で割ったもので、平成３０年度の実績がまとまったということで、ご報告をさせていただきました。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それは委員会に報告はされたでしょうか。計画があるのか、委員会に報告がされたのか、その２点を説明を求めました。","respondent":"池田国保医療年金課長","answer":"この作成当時は、委員会のほうに報告というところまではやらないで、東京都のほうに実際の部分の計画ということで報告をさせていただいているものです。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"どういう大もとの計画なのか、なかなか理解できないということだと思うのですけれども、どうでしょうか。９億６,８００万円ではないのですかと思うのですけれども、何で３億円という数字が、あわせてご説明をお願いします。","respondent":"池田国保医療年金課長","answer":"今、委員からおっしゃったことについては、赤字の原因の２と３の部分であるかと思います。２番の部分で、３番の部分で黒字分を差し引いた赤字額というような表現になっているですけれども、そのままになっている状態です。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"法定外繰り入れというのは、赤字分として入れるものが法定外繰り入れだと思うのですよね。その法定外繰り入れから赤字分を差し引いたものが、それが何で赤字となるのかというのはよくわからないですけれどもとの意見を述べました。","respondent":"池田国保医療年金課長","answer":"保険料を１００％にしても、実際に入ってくるのは９３％程度しかないということで、そこで必ず繰入金になるということになります。３月の話ですので、先ほど言った３億円ぐらいが赤字ということで、４,９００万円というような形にさせてもらったところです。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３億円ということで考えていいということなのですが、そのことの確認をお願いしたいのと、３億円という数字はここに出てきてないのですよね。何かこれだけだと、多分、どんなに話を聞いても、納得いく資料にはならないのではないかなと思うのですけれども、委員長、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これが計画書なのですか。これ、報告書。","respondent":"池田国保医療年金課長","answer":"実績報告書、もうほとんどそれと同じものです。","id":"exchange-032"},{"speaker":"渡部委員","kind":"質問","question":"もしそれを見て２億円というのを出さなければいけないのだったら、この２億円というお金は出てこないと思うので、それでは全然違うのですか。その解消に使うための繰入金というのはもともと３億円で、それを毎年５,０００万円ずつ使うんだと、それだけの話ではないのか尋ねました。","respondent":"池田国保医療年金課長","answer":"大体、委員のおっしゃったとおりですけれども、ただ、もう一つ補足すると、平成２８年度の赤字に使った額についてを解消、その解消しようという……。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"６年間かけて緩和、平成２８年度分と重なりながら、そういう計画の全体像というのがわからないのです。全体の計画の成り立ちを伺った上で、それについても教えていただかないと、議論のベースにならない。","respondent":"池田国保医療年金課長","answer":"５年、その１％ずつを赤字解消していくような計画をつくってくださいということで、４,９００万円というような形にさせていただいたところです。来年度に赤字削減額２億１,６００万円と、もう初年度で２億１,０００万円に達していますから…","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"この計画の根拠は、東京都の国民健康保険運営方針ということなのですけれども、この計画自体は各区でつくっているものなのでしょうか。それとも、数字はもちろん各区ベースだとは思うのですけれども、この枠組みというのは各区共通という感じでやっていますか。","respondent":"池田国保医療年金課長","answer":"こちらのほうは、様式というものに定められたものがございまして、各区市町村で計画書を作成いたしまして、東京都に提出してというような形をとらせていただいているものです。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"2)、3)とそれぞれざっくりどの程度の寄与率というようなことというのは、区としては把握されているのか尋ねました。","respondent":"池田国保医療年金課長","answer":"2)、3)の部分だと思いますけれども、連合会を通じて内容点検を行っているところです。生活習慣病の改善指導とか健診結果の説明会というのを、今ちょうど過渡期だということで、数値のほうの見直しを図っているところです。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問","question":"3)、どうだったかということ、これもすごく大きいところだと思うのですよね。1)番のというのは、どうだったというところまでぜひ、公表をするということはお考えか尋ねました。","respondent":"池田国保医療年金課長","answer":"例えば、令和元年については７月に発送しているところでございまして、昨年２月の通知分では２４０万円ほど削減できました。その前の１０月通知分におきましては１,０００万円ほど削減ということで、幾ら削減したかというところでの金額のほうは把握しています。","id":"exchange-037"},{"speaker":"渡部委員","kind":"確認","question":"１件、確認させてください。この平成２８年度の赤字を埋めるという目的に対するこのシートが、各区が提出しているものがそれぞれの区の計画ということの認識につながると。","respondent":"池田国保医療年金課長","answer":"今、委員がお話しされたとおりでございまして、あくまでも平成２８年度の赤字の計画で、本当に１枚の報告書、こちらのほうが計画書という題になっているところですので、そういったことでご承知いただければと思います。","id":"exchange-038"},{"speaker":"渡部委員","kind":"意見","question":"今、みんな誤認があって、そういう何かがあるのかな、なんて思っていたのですけれども、そういうのではなくて、これが計画ということですので、もう何か提出というのは別に出てくるものもないのでとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"この２億９,４５０万円ということだったということで確認させていただいていいでしょうか。それが本当はそこの平成２８年度の赤字だったけれども、この２億９,４５０万円になったという、確認をお願いしたいと思います。","respondent":"池田国保医療年金課長","answer":"その４,９００万円を解消したとしても、あくまでも平成２８年度の赤字額を減らすための計画ということで、４,９００万円と。実際に赤字額が、その額では０にすることはできないというふうに認識は持っているところです。","id":"exchange-040"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"なので、それを初めて出すのですから、こういうことで出しましたということを少なくとも出すべきだったなというふうには思います。ぜひわかりやすい資料で、何なのかというのがまずはわかるようにしていただきたいと思いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"}]},{"id":"topic-04","title":"国民健康保険料における延滞金徴収の運用開始","agenda":"国民健康保険料における延滞金徴収の運用開始","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この延滞金は、１４.６％と７.３％というのを定めていると思うのですけれども、これから徴収されるということなのでしょうか。ここの今までの経過とこれからというふうなところで、ご説明ほしいと求めました。","respondent":"池田国保医療年金課長","answer":"それから２３区の課長会等で、私ども２３区のほうでも、各区で延滞金の運用を始めさせていただきました。都からの指導にも、延滞金の徴収をということがございまして、延滞金の運用につきまして、この４月から運用を開始するです。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからなぜ今回から、令和２年４月１日からということで取り始めることになったのか、その点についてお聞かせほしいと求めました。これは今まで取らなかったことも、それから今回から取るということも、全て２３区統一で延滞金の徴収を始めるということなのか尋ねました。","respondent":"池田国保医療年金課長","answer":"今なぜ延滞金を取るようになったかというところでは、先ほど説明いたしましたように、皆様の負担の公平性を確保するということがまず１つあります。これから運用を開始するというところですが、品川を含めて３区が、令和２年、令和３年から実施するです。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今回３区ということで、あわせても１０区しかやらないわけですから、ほかの１３区はやらない。そういう中で、品川区がこれの徴収を始めるということですから、２３区統一でやるということではないということですよね。","respondent":"池田国保医療年金課長","answer":"先ほど言いました７区で、これから３区というところで、これから検討するというような中身になっているところです。この還付加算金と延滞金というのをセットで運用を開始しているところでございまして、令和２年度から延滞金の運用を開始するというものです。","id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"国保条例の第２２条の２のところに、やむを得ない理由ということで区が認めた場合は、減免という措置が取られるということでいいのか尋ねました。","respondent":"池田国保医療年金課長","answer":"第２２条の２の規定だと思いますが、免除について、これからの要綱等で整理していく予定になっております。","id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"窓口にも何回も相談に行ったことがありますけれども、どの方も、本当にもう貧困で払えないというふうな状況なのですよね。それから１２０万円想定というのは、そういう方のところで想定をしているということなのか、その減免についての想定についても説明を求めました。","respondent":"池田国保医療年金課長","answer":"金額が２,０００円以下の方については徴収しないということもありますし、低い方についてはそれほどかからないのではないかという想定をしています。人口規模等を見まして、３分の１の１２０万円ほどということでの想定で…","id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今までは、実際に保険料だけで済んでいたものが、しかも、このすごい割合ではないですか。ほかの１３区はやっていないのにもかかわらず、ぜひやめていただきたいということで、強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"あべ委員","kind":"質問","question":"この資料の中で、現年度収納率が９２.３２％とあるわけですけれども、つまり、現年度で払ってない方が７.６８％いらっしゃるということです。多分、シミュレーションを組まれていると思うのですが、この延滞はしつつ払っている人というのはどのぐらいの割合になるのか尋ねました。","respondent":"池田国保医療年金課長","answer":"収納率９２.３２％ということで、延滞率という、延滞金がかかる方の率というところまで押さえていません。はなくて、保険料の収納率について上げるために、延滞金の価格をつけて運用するということでご理解いただければと思います。","id":"exchange-048"},{"speaker":"あべ委員","kind":"質問","question":"すみません、私が伺ったのは、滞納されつつ払っている方というのはどのぐらいいらっしゃるのでしょうか。滞納されていて払った方というのは大体どのぐらいいらっしゃるのでしょうかというその数字の質問なのです。","respondent":"池田国保医療年金課長","answer":"平成３０年度までの滞納率ということでお話をしますと、１４.１４％が滞納率ということになっているところです。現年については約９２％納めていただいていますし、滞納繰越分率についても約４７％という数字ですので、収納率のほうが向上してというような形です。","id":"exchange-049"},{"speaker":"あべ委員","kind":"質問・要望","question":"７％弱の方が滞納はするけれども払っているという状況になるのかなというふうに受けとめましたが、それでよろしいでしょうか。新年度からしっかり情報が伝わるようにしていただきたいと思っているのですけれども、どのような方法を考えていらっしゃるのか尋ねました。","respondent":"池田国保医療年金課長","answer":"その中に、当然、延滞金の運用が始まりましたということでご説明するのがまず１つあります。４月に出して、６月以降でほとんどの方の運用が始まるということですので、周知のほうはきちんとできるかなというふうに思っているところです。","id":"exchange-050"},{"speaker":"あべ委員","kind":"意見","question":"４月にその説明を送って、６月以降に払うとなると、そのことをしっかり覚え続けている方というのもあまり多くないのではないか。なので、とにかく変わった、お金がかかってしまうということを大きく打ち出していただければなというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"渡部委員","kind":"質問・要望","question":"引き落としで１回でも引き落としにならなかったり、１００％、電話が行くではないですか。対象になる方には伝えてほしいと僕は思っていて、その２点、お願いいたします。","respondent":"池田国保医療年金課長","answer":"運用についての要領をつくってまいりますけれども、もしくは、できない方というようなことを決めることを考えております。その中に一言、延滞金がかかることがありますということでのご案内を追加するよう、コールセンターの委託業者のほうに依頼するようにいたします。","id":"exchange-052"},{"speaker":"若林委員","kind":"確認","question":"確認です。（３）の対象外、その７.６８％のうちのどれほどの割合の方が該当してくるというふうに想定されているか、少しイメージとしてお教えください。","respondent":"池田国保医療年金課長","answer":"９万９,０００円が頭打ちになるかと思うのですけれども、当然、延滞金はかからないというふうな状態です。その実際の額をよく、賦課された月と日付を見て考えないと、出てこないというふうなところになってくると思います。","id":"exchange-053"},{"speaker":"若林委員","kind":"質問","question":"この７区の、何ですか、そこら辺をお聞きしたいと思います。","respondent":"池田国保医療年金課長","answer":"ここの部分で７.６８％の方がどのぐらいになるかというと、申しわけないですけれども、お答えができない状態です。今お答えすることはできないのですけれども、実際上、保険料の収納について貢献しているということは聞いているところです。","id":"exchange-054"},{"speaker":"あべ委員","kind":"確認","question":"確認しておきたいのですけれども、４月１日以降の保険料に対して、延滞金の計算をしていくということなのでしょうか。それとも、今年の３月まで分の延滞しているものに対しても、来年度からの請求として、延滞金をいきなりかけてということになるのか尋ねました。","respondent":"池田国保医療年金課長","answer":"令和２年度の保険料に変わってまいりますので、３月の分も保険料を頂戴するような形になりますので、延滞金の計算対象になってまいります。あくまでも４月に、４月１日から保険料の賦課を始めたものについて延滞金をかけるです。","id":"exchange-055"},{"speaker":"あべ委員","kind":"確認","question":"すみません、私が聞きたかったのは、これまでに既に延滞をしている方に対して、例えば今、既に３０万円払っていませんというときに、これからすぐに延滞金がかかってくるかどうかというのだけ確認してくださいというのが先ほどの質問だったのです。","respondent":"池田国保医療年金課長","answer":"大変申しわけございません。３月までに賦課したものについての延滞金はかかりません。","id":"exchange-056"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"９万９,０００円の場合が、延滞金をかける意味というのですか、余計払えなくなっていくということになっていくのではないですかね。私たちは保険料を下げるべきだと思っているのですけれども、そういうことこそすべきではないかと思うのですが、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"先ほど、高額の保険料の方でも、お支払いの力があるのにお支払いできない方もいらっしゃるしというようなお話があったかと思います。これまでも再三ご説明していると思いますけれども、分割でお支払いするとか、皆様のほうでもご周知のほうをいただければと思ってあります。","id":"exchange-057"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"また来年も再来年も上がっていくわけですから、しかも、１３区はやってない中でです。何でここに品川区は乗り出していくのかがちょっと理解できません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は本当に払いたくても払えないという人を追い詰めるような状況にはしないでいただきたいということを強く要望したいのですけれども、そういうふうにもう貧困で払いたくても払えない、そういう状況の方には減免制度が適用されるということで考えていいか尋ねました。","respondent":"池田国保医療年金課長","answer":"延滞金運用につきましては、きめ細かく調整できるものは調整する、そうでないものは違うということで運用を図っていきたいというふうに思っております。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、２３区の中でも突出してそういう厳しい取り立ての中で収納率を上げるという職員の研修を東京都で受けてきた区なのですよね。払える状況もつくっていけるのだというふうなところに変えてほしいというふうなことも、その人の生活実態に合わせて、その人の……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その人に寄り添った対応、減免制度をしっかりと使っていただきたいということで、強く要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"}]},{"id":"topic-05","title":"「品川区自殺対策計画」（案）およびパブリックコメントの実施結果","agenda":"「品川区自殺対策計画」（案）およびパブリックコメントの実施結果","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"このまとまった結果、ホームページと広報しながわで公表ということですが、その先の活用策というのはどのようにお考えなのでしょうか。多分これ、どういった形でこれを活かしていただこうという計画になっているのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"庁内の職員全員が認識するということがまず重要だというふうに考えたところもありまして、少し説明が漏れたのですが、２９ページをご覧ください。当初は実施していた民生児童委員の方なども対象とした形で、明るい…","id":"exchange-062"},{"speaker":"あべ委員","kind":"質問・要望","question":"１件、特に１０代が多いというのが、やはりここは教育委員会が特にその意識を一層持っていただきたいと思っているのです。１０代が多いというところはぜひ教育関係者に強く理解していただきたいと思うので、その点、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"今日は変更がないので説明を飛ばしましたが、もちろん区でしっかり取り組むべきだというふうに認識してございまして、私どもとも連携しておりますが。この教育への取り組み方については、その必要性も重要性も認識した上で一緒に取り組んでいくように連携しつつ…","id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここでは委員の任期は２年ということですので、１年過ぎて、あと１年の任期と考えていいのでしょうか。それで、これからこの協議会というのはどれぐらいの頻度でどう運営されていくのかということについて、お聞かせほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"次年度以降の予定といたしましては、あくまで予定ですが、２回を予定しています。任期２年につきましては、その後の継続、当然、その目標達成までの継続ということを十分視野に入れております。","id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"２年間の任期だということなのですけれども、何というのですかね、また検討できるというふうな状況になるのかなと。そこら辺のところが少しあると、もう少し深まっていくのかなという思いがしたのですけれども、そういう点についてはいかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"「自殺対策に関する基本認識」のところで、こういう基本認識のもとに、ここにこの必要性を品川区の基本計画では捉えたというふうに考えてあります。今回、例えば事例の共有も踏まえまして…","id":"exchange-065"},{"speaker":"西村委員","kind":"質問・要望","question":"要望だけお願いします。区民も参加できる参加しやすいパブコメに、難しいのですけれども、ご努力をお願いしたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"}]},{"id":"topic-06","title":"新型コロナウイルス感染症の対応","agenda":"新型コロナウイルス感染症の対応","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"少し確認もしたのですけれども、あのときに、こういうふうにやらなければいけかったのかというのを少しここでも説明をしてほしいなと思います。大きくその２点ですかね。","respondent":"鷹箸保健予防課長","answer":"周りの方に感染が広がっている可能性があると考えた場合には、この病気に限らず、これまでも実施してまいりました。当初は全く報告をする予定ではなかったところですし、１例、あの中に品川区でやったものも含まれているというふうに考えていただけるかと思います。","id":"exchange-067"},{"speaker":"渡部委員","kind":"質問・要望","question":"でないと、また課長に迷惑がかかることになりますというような状況だと思いますので、ぜひいろいろ教えてほしいと求めました。だけど、果たしてその辺までどうなのかなと、行政としてどうなのかなと、今、考えるときなのかなと少し思っていての質問でした。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"今の話をお聞きして、少し確認なのですけれども、この検査数というのは、コロナウイルスのＰＣＲ検査ということで捉えていいのでしょうか。和歌山で６７０件で、そのうちの２０１件が品川のこの品川保健センターでやられた検査だということで捉えていいのでしょうか、その確認です。","respondent":"鷹箸保健予防課長","answer":"検査ですが、この間、少なくとも東京都で報告されている数の中のこの２０１件は品川区で対応したということは事実です。全て必要な方には検査を実施し、必要な入院などの対応をしておりますので、感染拡大防止に努めたというふうに理解して行動しています。","id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ぜひこの方を検査をしてほしいということで申し入れると、そういうのは保健所としてはどういう状況になっているのか伺いたいと思います。昨日のニュースではもう４万人を超える方が検査をしていて、１日に７,５００件の検査ができて、そういう状況になっているのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"こちらは電話相談センターで保健師等が対応しておりますけれども、病院あるいは保健所で連携の上、調査するという流れになっています。先週あった都の説明会では、より早く診断をして対応することが必要な方に、本来の検査をする。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"帰国者・接触者電話相談センターから保健所に来て、そして保健所から、ここのセンターの指定医療機関というのは品川にもあるのでしょうか。そうすると、この指定医療機関というのはどこなのかというのを教えていただきたいのと、それから……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうなのですか。そういう報道がすごくされているのですけれども、そういうふうに保健所から直接というふうにはならないということになっているということか尋ねました。","respondent":"鷹箸保健予防課長","answer":"それから、外来についてはあえて公表しないというふうになっています。不安に対応するのは非常に重要なのですけれども、我々はそのような対応で、それは全国一律にそのような対応をさせていただいているところです。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それ以外のところは、品川では２つの窓口でやっていて、２人が常に対応しているというふうなことになるのでしょうか。それは保健師がやっているということか尋ねました。","respondent":"鷹箸保健予防課長","answer":"専用電話相談には３２７件、それから保健予防課でお受けしたものが１８５件、あわせて５１２件の電話に対応しています。検査数については以上です。","id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"現場からすると、やはりそこら辺のところは、検査を気軽にできるような体制にするというのは必要だということで考えられるのでしょうか。そこら辺のところで、言える範囲でお願いします。","respondent":"鷹箸保健予防課長","answer":"そう遠くない時期に対応を変えるような形で、国が方針を、対応を決めているというふうに受けとめています。入院してから２日間以降の検査を、１２時間あけて２回検査をして、陰性でないと退院できないのです。","id":"exchange-074"},{"speaker":"あべ委員","kind":"質問","question":"ご高齢の方々あるいは病気、そして障害の中でも虚弱系の方々、そうした方々の感染はやはり怖いなというふうに思います。それから病気療養中の方など、どのような形でなさって、感染防止に努めていらっしゃいますか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"高齢者施設全体の取り組みとしましては、日々、クリニックと連携しながらやっていただいているというところです。ホームヘルプのほうがそうなのですけれども、これについては事業者からも今、相談がたくさん来ております。","id":"exchange-075"},{"speaker":"あべ委員","kind":"質問","question":"対策の仕方も、お手洗いをアルコール消毒するとか、そういったことというのはいつも以上に入念にやっていったほうがいいのかなというふうに思います。ちょっと一段、その消毒という意味ではこまめにやっていく必要があるのではないかという、その辺の対応はどうなっていますか尋ねました。","respondent":"高山健康課長","answer":"おおむね対応については慣れていらっしゃるということで、一般的な対応になりますけれども、そういったものを設置して。","id":"exchange-076"},{"speaker":"あべ委員","kind":"確認","question":"この２００という数、１２０でいうと、配分になっていくのでしょうかね。なるほど、そうなのかという気もしないではないのですけれども、確認でお願いします。","respondent":"鷹箸保健予防課長","answer":"非常に特別な対応で、こういう対応をしているわけではございませんので、全員というようなことではありません。私が考える範囲では、こういったような症状がない方まで全部などという特別な対応は、このとき限りだと思っています。","id":"exchange-077"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"あべ委員","kind":"意見","question":"そういった動ける医療的ケア児あるいは知的なおくれのない、発達おくれのない医療的ケア児について、どのような受け入れがあるかということもお話しくださいますかとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"児童発達支援では「ほわわ品川」が、放課後等デイサービスでは「ミント」という事業所が対応しております。医療的ケア児の受け入れについては課題と認識しておりますので、医療的ケア児支援関係機関連絡会で情報共有をし、課題解決に努めてまいります。","id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"連絡会なのですけれども、準備会ができたということで伺ったのですけれども、実際に連絡会が開始されるのはいつぐらいからという予定はもうありますか尋ねました。","respondent":"松山障害者福祉課長","answer":"確かに準備会議を２月５日に行いまして、来年度の連絡会につきましては、年に２回を予定しております。１回目は６月か７月ぐらい、２回目は冬ぐらいを予定しております。","id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうしますと、その連絡会のメンバーというのももう既に決まっているというとこでしょうか。どんな方で何人ぐらいというのがわかったら説明を求めました。","respondent":"松山障害者福祉課長","answer":"連絡会の中で予定されているメンバーですが、それから医療型児童発達支援センター、品川特別支援学校。は品川区側のメンバーとなっておりまして、外部の方は１０人から１１人程度というふうな予定です。","id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この課題はすごく期待されているところですので、ぜひよろしくお願いしたいと思います。それで、これは公開なのかどうかだけ、最後に説明を求めました。","respondent":"松山障害者福祉課長","answer":"公開するかどうかにつきましては、主たる委員の方々と少しお話をさせていただきまして、考えていきたいと思います。始まる前に議論をさせていただいて、公開ということであれば、皆様に早目にお知らせをと考えています。","id":"exchange-081"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ごめんなさい、最後、すみません。関心の高いところですので、そういう公開で皆さんが見える形でやっていただきたいということで、要望だけします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3558#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":93746,"voices":254}},{"id":"r02-20200226-8","meetingId":"r02-cm02","date":"2020年2月26日","dateIso":"2020-02-26","committee":"建設委員会","time":"午前１０時００分～午後 ０時４５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件整理しています。","topics":[{"id":"topic-01","title":"東品川海上公園拡張整備工事","agenda":"東品川海上公園拡張整備工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"参考までに土地の取得価格と、予定されている整備費の総額、それぞれ幾らかお伺いしたいと思います。この整備の内容の策定にあたって、当事者といえば公園利用者になると思うのですけれども、利用者の意見などの反映はどのようにされたのか伺います。","respondent":"溝口公園課長","answer":"都市計画変更等を経て、都市計画手続等を踏まえて、今回の整備工事に至ったものです。用地費なのですけれど、総額で約３億円ほどかかっているものです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"意見","question":"その辺はどのように意見を反映して、このような計画になったのかというのを、もう一度説明を求めました。","respondent":"溝口公園課長","answer":"さらに広域避難場所として位置づけられておりますので、そういったところの安全性の確保ということで、東側区道と連続した計画にしています。品川区のほうでしっかり考えて、整備を進めてきておりますので、そういったもので今回の工事を計画しています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"ほかの隣接するところでは楽しい場所もたくさんある公園なので、利用者としては多分いろいろ、こうなったらいいなという声もあると思うのです。ですからぜひ、できるところは反映させていくという姿勢でぜひ臨んでいただきたいのですけれども、ぜひよろしくお願いしたいなというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"単純に言葉がわからないのですけれど、平板舗装はどういう手法の舗装なのか説明を求めました。","respondent":"溝口公園課長","answer":"説明が足りなくて申しわけありません。同じ物を同じような形で拡張していくというか、整備をしていくというのが、今回の平板舗装工事になります。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"材質とか水を通すとか、そういう材質などについて、もうちょっと教えていただけますか。","respondent":"溝口公園課長","answer":"通常、インターブロックと言われているブロックを舗装に引いているところがあるのと同じように、透水機能等あるものの形になっておりますので、一応雨水流出抑制、そういったものにも配慮した製品を使っていこうというふうに考えているところです。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"確認","question":"ちょっとお聞きをしたいのは、あっちのほうに出入り口はなかったのかという確認と、親水デッキの幅はどれぐらいになるのかということだけ。費用も結構かかっているので、その辺のところを確認したいのでお願いします。","respondent":"溝口公園課長","answer":"ジョナサン側の入口ですが、今回新たに整備することによって、初めて東側区道と直接接続する出入り口ができるような形になります。たしか五、六メートルはあると思いますけれど、同じような形の幅員をもって整備していきたいというふうに考えているところです。","id":"exchange-006"}]},{"id":"topic-02","title":"（仮称）旗の台六丁目公園整備","agenda":"（仮称）旗の台六丁目公園整備","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"適地を探していたということですが、地元の町会からの公園整備の要望が寄せられていたという理解でよろしいのでしょうかというのが１点です。今後の参考までに、今回の用地取得までの経緯、経過も簡単にお伺いできればと思います。","respondent":"溝口公園課長","answer":"旗の台六丁目につきましては、以前より町会等含めて、公園の設置の要望が来ておりました。今後もいろいろ情報をとりながら、地域の声も聞きながら、新たな公園整備に取り組んでいきたいというふうに考えているところです。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"今回の用地取得費の財源なのですけれど、区の単費と補助金の割合を、総額幾らかというのとあわせて伺いたいと思います。閑静な住宅地であるので、そういう点では配慮が必要な地域なのかなと想像しているのですけれども、この点についてのお考えを伺いたいと思います。","respondent":"溝口公園課長","answer":"ただ、今後計画を進めていく中で確定していくことになりますので、計画を進めていく中で決まっていくものだというふうに考えているところです。地域の方のご理解をいただきながら進めていきたいというふうに考えておりますので…","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"ぜひ、地域活動の拠点となれるような、あとは憩いの場となれるような公園になるよう、丁寧な対応をお願いしたいと思います。予定している補助事業というのですか、どういう補助金の枠組みを今、区のお考えをお聞かせほしいと求めました。","respondent":"溝口公園課長","answer":"要は、防災に資するというところでの国の公園整備の補助制度もありますので、そういったものの活用もにらんでおります。一番いい形で国庫補助金、そういったものも活用して、整備をしていきたいというふうに考えているところです。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後になりますが、公園のない町会・自治会はほかにもたくさんあるのですよね。やはり要望があるところから整備を実現すべきだと思うのですけれども、どのように実現するお考えがあるのか伺いたいと思います。","respondent":"溝口公園課長","answer":"例えば面積要件、そこはそれぞれ、個別の対応の中で考えていかなければいけないというふうに考えているところです。そういったところも勘案しながら、総合的に判断して、できる限り新たな公園の整備を行っていきたいというふうに考えているところです。","id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"この公園の土地の取得場所を見ると、荏原七丁目とのちょうど境界だと思います。しようがないとは思うのですけれど、ここでいいのかなというふうな疑問も一応あり得るのかなと思うのですけれど、そのあたりはいかがか尋ねました。","respondent":"溝口公園課長","answer":"ただやはり、なかなか土地取得が困難な中、今回まとまった５００平米以上の土地が取得できるというのは大きなことだと考えています。ここについては、やはり町会境とはいえ、公園としてしっかり整備していきたいと考えているところです。","id":"exchange-011"}]},{"id":"topic-03","title":"（仮称）マイガーデン西五反田の新設","agenda":"（仮称）マイガーデン西五反田の新設","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"平成２５年に寄付を受けたということですが、検討に時間がかかった具体的な理由は何かあるのでしょうか、伺いたいと思います。３点目は、改めてなのですが、マイガーデンとはどのような事業なのか、利用料や利用期間などを、教えてほしいと求めました。","respondent":"溝口公園課長","answer":"いろいろ検討していく中でなかなか行政需要に見合った費用対効果も含めて、総合的に判断して活用ができないというところであります。利用するにあたっても私どものほうで管理していかなければいけませんので、受益者負担の観点から一定料金をいただいているところです。","id":"exchange-012"},{"speaker":"吉田委員","kind":"確認","question":"先ほどのご質問の確認になりますけれど、例えば暫定利用のマイガーデンを増えていくような方向性というのは考えていらっしゃるのか。ぜひ増やしてほしいというご意見があるので、そういうふうに伺うのですが、継続して申し込んでもだめだったというような声も聞いています。","respondent":"溝口公園課長","answer":"２年、３年とかというような話もできるのかもしれませんけれども、なかなかそういったものは難しいと考えています。引き続き、現状の１年というサイクル、ご理解いただきながら運営していきたいというふうに考えているところです。","id":"exchange-013"},{"speaker":"吉田委員","kind":"確認","question":"私もその南大井のほうのルールをよく知らないのですけれど、例えば殺虫剤を、まきたい人とまきたくない人がいますよね。それから近隣の方たちにとってもその辺は気になるところかなというふうに思うのですが、その辺のルールについて、もう一回確認させてください。","respondent":"溝口公園課長","answer":"今回、作物というか野菜を育てる上で、さまざま皆さんが工夫されて取り組んでいる、というのは聞いているところです。そういったルールについては引き続き、利用者説明会を毎回やる中で、周知を図っていきたいというふうに考えているところです。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私どもの会派から必ずといっていいぐらい要望させていただいているのが、都市計画道路などで買収した土地、そこでマイガーデンをできないか。そういう考え方というのはできないのかなと、ちょっと改めて伺います。","respondent":"溝口公園課長","answer":"区としてやはり、区民サービスとしてやっていく中では、最低限必要なものを整備していきたいというふうに考えているところです。それについては引き続き、ほかの事例等も踏まえながら、研究、検討していきたいというふうに考えているところです。","id":"exchange-015"}]},{"id":"topic-04","title":"目黒川安全航行啓発イベントの実施","agenda":"目黒川安全航行啓発イベントの実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"そもそも論で申しわけないのですけれど、目黒川で船舶を航行する場合の許可の関係など、ルールというのはどうなっているのでしょうか。時期的には花見の時期にやはり集中しているという実態であるのかどうかなどもわかれば、説明を求めました。","respondent":"松本河川下水道課長","answer":"しかし、昨年の桜の時期に、イベントを実施しました。平成３１年３月３０日、３１日で行っておりますが、そこでカウントした中では３００隻ぐらいの船が通っていることはわかっております。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"マナーについてはこのガイドを守っていただきたいということで、では特に、自由に航行しているということの理解でよろしいのでしょうか。その辺も伺います。","respondent":"松本河川下水道課長","answer":"桟橋をもし仮に利用する場合には、品川区に申請をしていただく必要があります。アルコールにつきましては、昨年の平成３０年７月に東京都水上安全条例というのが施行されまして、それを遵守するようなことになろうかとは思います。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません、私の記憶違いだったらあれなのですが、これは水上バイクとかが目黒川に上ってきてしまうということがあって、今、カメラがついていると。注意をしたのがどれぐらいあるとか、そういうデータがあるなら、教えていただきたい。","respondent":"松本河川下水道課長","answer":"監視カメラですが、目黒川に監視カメラはついてあります。何か問題があったときにはそのデータを回収して確認することは実施するような予定ですが、チェックは基本的にしていないといったところです。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"確認","question":"今このカメラをつけたりいろいろなことで、今の目黒川はよくなっているという理解でいいという形でいいのですか、というような確認です。どうしてかというと、その辺の感触をぜひ、もう一回お願いします。","respondent":"松本河川下水道課長","answer":"苦情に関しては、平成２９年からは暴走だとか危険走行による苦情というのは私たちのところには届いていない状況です。そういった話というのは入ってありますので、その辺のニュアンスというのがすみません、微妙なところはあるかと思います。","id":"exchange-019"}]},{"id":"topic-05","title":"被災者生活再建支援事業の実施","agenda":"被災者生活再建支援事業の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"４件の対象想定件数があるということで、半壊が４件ということだったのですが、この半壊と判定されたお宅の地域的、あるいは構造的な特徴など、共通点などがあれば伺いたいと思います。","respondent":"中島防災課長","answer":"構造的な特徴というところはとりわけ、聞いているところではないのですけれど、通常のお宅であったというふうに考えております。１件だけ、隣の擁壁等の関係で損害を受けたところがありますので、そこについては特筆すべきところかなというふうに考えております。","id":"exchange-020"},{"speaker":"たけうち委員","kind":"意見","question":"１月２０日の建設委員会で報告いただいた、１００件ぐらいを想定しているということで、関連なのでわかったらでいいのですけれどとの意見を述べました。","respondent":"森住宅課長","answer":"今、委員からご紹介ありました事業につきましては住宅課のほうで行っておりますけれども、先週末の段階で４１件の申請をいただいているところです。罹災証明をもともと発行されている方もいらっしゃいますし…","id":"exchange-021"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。４１件ということで、想定だと１００件ぐらいだということなので、状況を見ながらまた再度何かお知らせするということも検討されているのか尋ねました。","respondent":"森住宅課長","answer":"３月６日までを一応実績報告書の提出期限としておりますので、基本的には追加でご説明ということは考えておりませんけれども、お問い合わせがあった際には、丁寧にご説明をしていければなというふうに思っております。","id":"exchange-022"},{"speaker":"松本委員","kind":"質問","question":"２分の１は区が支出するということなのですが、予算的にはどこから支出するのか尋ねました。","respondent":"中島防災課長","answer":"今回、２分の１の区の支出については、災害復旧特別会計の災害復旧事業費のほうを想定しています。避難場所を数多く設置したり、東京都もこのような補助制度を創設したことを鑑みて、この会計から支出するものです。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問","question":"区がやるべき話なのかどうなのか、入っている人と入っていない人がいますが、保険があるではないですか。その辺のところというのは、行政がやるべきかどうかというのは微妙なのだけれど、何かそういうことに触れていますか。","respondent":"中島防災課長","answer":"「しながわ防災ハンドブック」の中では少しだけ、地震保険への加入というところのご説明を入れしています。風水害のところについて記載が見当たらないので、そのあたりのところの周知については、少し考えていきたいなというふうに思っております。","id":"exchange-024"},{"speaker":"大沢委員","kind":"意見","question":"すみません、今のところで、居住用と事業用というのを切り分ける必要があるのですけれど、そこのところはどういうふうになっていますかとの意見を述べました。","respondent":"中島防災課長","answer":"今回の被災者生活再建支援事業についてということでしょうか。","id":"exchange-025"},{"speaker":"大沢委員","kind":"質問","question":"今の石田秀男委員の保険のところです。自己責任ではないけれど、保険でやって保険で賄うというのは基本だと私は思うのですけれども、そこのところはどういうふうにされているのか尋ねました。","respondent":"中島防災課長","answer":"恐らく事業継続計画とか、そういう関係もあると思いますが、そういうところは区では商業・ものづくり課とかが企業に対する周知啓発も行っております。そういうところでも連携をしていく、どこまで説明できるかはわからないのですけれど、ちょっと念頭には置いておきたいと思いま…","id":"exchange-026"},{"speaker":"あくつ委員長","kind":"確認","question":"ではすみません、私のほうからも。この４件のうち、これは保険に関係なく適用するということでよろしいかどうか、確認をさせてください。","respondent":"中島防災課長、森住宅課長","answer":"同じ都の事業ですので、同様というふうに認識をしています。 保険によって改修できたもの、できなかったものがあるというところで、保険については加味しないというふうに考えているところです。事業用については営利に基づく部分なので今回対象外ということでやらせていただいているところです。","id":"exchange-027"}]},{"id":"topic-06","title":"令和元年度区内一斉防災訓練および各地区総合防災訓練の実施結果等","agenda":"令和元年度区内一斉防災訓練および各地区総合防災訓練の実施結果等","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"アンケート対象者が４,２０３名で、回収率が７１％ということですが、お子さんたちは入っていないという理解でいいということでしょうかということ。特筆すべきそれぞれの訓練、できればみんな共通でやれたらいいのではないかなというようなお考えがあれば、お聞かせほしいと求めました。","respondent":"大森災害対策担当課長","answer":"この２月、３月期になりますと、次の訓練の検討等につなげていくような形で進めているところです。そのような形で、自分たちで地域の特性に合った訓練メニューを考えて実施していただきたいというのが一つ大きな方向性かなと考えています。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"何というのでしょうか、その辺の区の考えはないのでしょうかということで伺ったので、もう一度お聞かせほしいと求めました。","respondent":"大森災害対策担当課長","answer":"その訓練というのを取り扱いできるような形で対応していただきたいということで、ご紹介をして、実施しています。そのような形で、訓練の対象者の確保と新たな資機材という部分についてもご検討いただきながら訓練を進めていきたいと、このように考えております。","id":"exchange-029"},{"speaker":"安藤委員","kind":"提案","question":"具体的に提案なわけですけれども、これには答えるべきなのではないかなと思うのですけれども、区のお考えはどうかというのを伺います。ここについての区の考えというのですか、回答というのですか、その辺についてのお考えもあわせてお伺いしたいと思いますとの意見を述べました。","respondent":"大森災害対策担当課長","answer":"こちらをしっかりつくりまして、Ａ４判で４０訓練項目ぐらいは入っているような、かなりしっかりした冊子を予定しております。しっかりご説明して、次年度の訓練につなげていきたいと、このように考えております。","id":"exchange-030"},{"speaker":"松本委員","kind":"意見","question":"この八潮の参加人数は４８１人と結構ほかと比べて多いのですけれど、若干、大丈夫かなというふうに思ったりするのです。ちょっと内容が不安に思われるのですけれども、そういったところは何か情報、把握されていたらお願いいたしますとの意見を述べました。","respondent":"大森災害対策担当課長","answer":"こちらのほうで地区内に会場を３地区設けまして、学校等も連携しながら、区としても把握しております。その辺につきましては地域の考え方に基づいて進めていただいているです。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"別紙１を見ると、町会・自治会は３人、防災学習となっている。行政側がこういうことをやってほしいなというのが、というのがあるのであれば、その辺の考え方を教えていただきたい。","respondent":"大森災害対策担当課長","answer":"作成を予定している訓練の手引きにつきましては、共助の育成のための訓練内容を含め、幅広くカバーしているものです。やはり避難所の運営会議のメンバーを中心にいろいろ検討していただいているところですけれども、また、しっかり検討していただいて。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問","question":"何かないと、もっと、では中学生呼んでこようと。先ほど伺ったらあるというし、そういう指導をしていただいたほうがありがたいなと思うのですけれど、その辺の考え方を説明を求めました。","respondent":"大森災害対策担当課長","answer":"いろいろ積極的に訓練に取り組んでいただいているような地域ももちろんありますし、このような方々が中心になって、もちろん認識をしています。実際の災害対応のことを考えますと、やはりその辺については、そのような方向で進めていきたいなというふうには考えているところです。","id":"exchange-033"},{"speaker":"吉田委員","kind":"確認","question":"本当にこの訓練で、実際に何か起きたときに、大丈夫なのだろうかということを感じている方は、率直なところいるかなというふうに思うのです。でもやっていかなければいけないわけですから、せっかく予算化されて冊子をつくるときに、その辺だけ確認させてください。","respondent":"大森災害対策担当課長","answer":"今後作成する予定の、いろいろ話を聞いて、事例なども含めて紹介をするような形で進めているところです。その解決につながるような方向というところがなるべく出るような形でつくりたいなということで、進めさせていただいているところです。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ今実際に、少しでも近づけるようなものをいろいろな方たちのご意見を伺いながら、つくってほしいと求めました。これは要望にとどめします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"あくつ委員長","kind":"確認","question":"認識の確認なのですけれど、先ほど石田秀男委員からもありましたが、カウントすると５校ほど生徒が出ていない学校があります。そうすると次のタイミングがないということですから３年間やらないということになると思うのです。","respondent":"大森災害対策担当課長","answer":"その会長連絡会の中で、そういうことであれば隔年で両方を訓練できるような形で実施しようという形で決まったものです。隔年で実施して、事情があるかもしれませんがご理解いただいて、しっかり参加していただくような形で働きかけをしてまいりたいと考えています。","id":"exchange-036"},{"speaker":"大沢委員","kind":"質問","question":"これはどういうふうな事情があって保護者のゼロがずっと並んでいて、一方で、多いところは５８名や４５名であったりします。そんなことで、非常に数字の並び方がきれいなのだけれど、このゼロである理由はどういうことなのか尋ねました。","respondent":"大森災害対策担当課長","answer":"このゼロの部分につきましては、今回の訓練の参加は児童・生徒のみで、土曜の授業の一環として実施しているという学校です。学校の授業に合わせまして保護者の皆さんに引き取り訓練という形で、訓練に参加していただいているものを計上しているものです。","id":"exchange-037"},{"speaker":"大沢委員","kind":"質問","question":"引き取り訓練に参加をしてということですが、ゼロのところはその引き取り訓練について保護者に言っていないのですか。保護者が出ているところは引き取り訓練に参加してくださいとの旨を発していて、ゼロのところはそこのところは言っていないということか尋ねました。","respondent":"大森災害対策担当課長","answer":"ゼロの部分ですけれども、我々のほうで報告を受けて把握している限りですが、その引き取り訓練は実施していない学校と把握しています。","id":"exchange-038"},{"speaker":"大沢委員","kind":"質問","question":"例えば３人とか、数字の分布にばらつきがあるのが自然な形ではないかなと思うのですけれども、いろいろな事情があるのでしょうけれど。大井１のところに４５というのがあるのですけれど、今年浜川小でやったので次年度はほかのところでというような形にこれはなっていくのか尋ねました。","respondent":"大森災害対策担当課長","answer":"我々のほうでは、委員ご指摘の持ち回りでというような話では受けておりませんし、報告も受けておりません。あくまで、その訓練の実施結果として、学校側を含めて引き取り訓練を実施しましたということで防災課としては報告を受けているところについて。","id":"exchange-039"},{"speaker":"大沢委員","kind":"質問","question":"学校の裁量であれば、これは、防災課にカウントするのは、数をただいたずらに増やしましたよ、ということで、教育委員会と切り分けて数字出したほうがいいと思いますけれど、どうか尋ねました。","respondent":"大森災害対策担当課長","answer":"委員ご指摘のとおり、保護者等の引き取り訓練については学校主体でやっている部分ですので、この辺の数字のとり方、報告の仕方については、次回からちょっと検討させていただいて、改善をしてまいりたいと思います。","id":"exchange-040"},{"speaker":"大沢委員","kind":"質問・要望","question":"やはり地域の中の学校という位置づけがあるのであるから、声かけなりは偏ることなくやっていただきたいなと。３人でも２人でも４人でも、ばらつきがあるのが普通の数字の並び方ではないのかなと思ったので、この質問をさせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"}]},{"id":"topic-07","title":"本日は、防災対策の中から、避難所運営マニュアルと要配慮者への支援","agenda":"本日は、防災対策の中から、避難所運営マニュアルと要配慮者への支援","exchanges":[{"speaker":"たけうち委員","kind":"確認","question":"確認ですけれども、非常にいいことだと思うのですけれども、全部で５２カ所あるわけです。その辺はどんな感じなのかというのがわかれば、まずそこを説明を求めました。","respondent":"中島防災課長","answer":"こちらの資料に記載してある避難所運営マニュアルの更新状況についてですが、基本的には完成したのは５２カ所というふうに認識しております。まだ我々としても周知啓発を引き続きしていくテーマかなと考えていますので…","id":"exchange-042"},{"speaker":"たけうち委員","kind":"質問","question":"一旦は５２カ所全部マニュアルができたけれども、ペットも含めて、盛り込まれたら随時更新していくという考え方でよろしいということですね。この割当図もマニュアルの中で各避難所が、その避難所内に合わせたものをつくったということでよろしいか尋ねました。","respondent":"中島防災課長","answer":"今回、割当図も更新支援の大きな成果だと考えています。基本的には全ての避難所についてもこのような図面が盛り込まれていると思います。","id":"exchange-043"},{"speaker":"たけうち委員","kind":"質問","question":"その学校に応じて、そういうのも含めて、具体的にこういうものができているというふうに認識していいのかどうかということ。体育館の使い方も、そこに避難者の中でもどういった形のものを入れるとか、そういうのも具体的に割り当てという形で地図化されているのか尋ねました。","respondent":"中島防災課長","answer":"主に避難生活等を送る場として、例えばある町会は体育館を使うとかいう形の割当ての中で、図面を作成しています。倉庫については、基本的には備蓄倉庫等がありますので、物資等はそちらのほうに置いているのではないかと思います。","id":"exchange-044"},{"speaker":"たけうち委員","kind":"意見","question":"非常にすばらしいなと思うので。例えば我々もそうなのですけれど、そこに住んでいらっしゃる方とか役員の方などが、どういう形で見られるのかということがもしわかればお願いしますとの意見を述べました。","respondent":"中島防災課長","answer":"防災課でもどのようにというのを検討させていただいたところで、避難所連絡会議などという場で確認をしていただくような形を想定しています。今後、情報の共有とかいうところについては、課題として考えておりますが…","id":"exchange-045"},{"speaker":"たけうち委員","kind":"提案","question":"一般質問で、来た方が誰でも最初の対応ができる、そういう対応ができるようなものをやったらどうだということも提案しました。そういったこともぜひ、今後検討してもらいたいなと思いますが、いかがか尋ねました。","respondent":"中島防災課長","answer":"そういう形で大きくして貼ることについて、あらかじめできるかどうかというのはちょっと検討はしていきたいと思います。そこについて重点的に取り組んでいく中で、そういうものについては、必要性というのを研究していきたいというふうに思います。","id":"exchange-046"},{"speaker":"たけうち委員","kind":"意見","question":"やはり最初に必要なものは各学校ごとに若干違ってくるかもしれませんけれど、一律のものもあるので、それはやはり区が主導して用意してあげる。防災手引きが今回、新年度予算で検討されるということなので、あわせてぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問","question":"手話が一番、やはり筆談ができそうに思うけれどもなかなか筆談というのは難しいんだよ、ということを当事者の方からも伺っています。例えばでも結構ですので、伺いたいと思います。","respondent":"中島防災課長","answer":"各避難所のマニュアルの中でも、程度があると思いますけれど、盛り込んでいっていただいているところです。これから改善等もいろいろと考えていくべき話だと思いますが、そういう文字等を少し留意して対応、配慮を心がけるように記載しています。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問・要望","question":"１人１個という感じで配られてしまったというのが、ずれてしまうようなことがある事例として、東日本大震災のときの事例として語られています。何かこの中で、そういうところまでの踏み込んだ記載はマニュアルにされているのかどうか、伺いたいと思います。","respondent":"中島防災課長","answer":"物を配ったりとか着がえするなど、諸々のところは配慮が必要だと考えておりますので、そこについては区としても働きかけていきたいと考えています。そういう方々に、女性に配慮するということは運営側のほうもご理解いただきながら運営していただければというふうに思っておりま…","id":"exchange-049"},{"speaker":"吉田委員","kind":"意見","question":"やはり、だから女性がリーダーとして声を上げにくいというようなところがあったというふうに、これまでの事例では聞いております。東京ではそんなことはもうないと思いますけれども、もしちょっと配慮がないかなというところにはアドバイスなどしていただけたらと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"改めてお伺いしたいのですけれど、品川区の場合、それだけでは到底足りないなというのは感じているところなのです。まず教室が埋まったら体育館みたいな、そういったルールがもしあるのであれば、お伺いしたいと思います。","respondent":"中島防災課長","answer":"基本的に要配慮者には１階を主に使っていただくということが多いと思いますので、各避難所ごとにマニュアルを作成する中で、１階部分の利用については一定程度定めているというふうに感じております。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区ではどういう段階で判断していくのかというのを聞きたかったので、ちょっとお答えほしいと求めました。ペット対策は、いわゆる同伴ですか、室内まで一緒に避難できるというようなところまで配慮しているところは幾つかあるのか伺いたいと思います。","respondent":"中島防災課長","answer":"体育館につきましては、いつから使うかというところですと、恐らく最初から使うような形で考えております。あくまで同行避難というところで、建物外のところに別にスペースを設けるようなものがほとんどだというふうに認識しております。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問・要望","question":"お伺いしたいのは、実際に避難所運営をするときの区職員の具体的な役割というのですか、区の職員の役割というのはどのようになっているのでしょうか。伺いたいと思います。","respondent":"中島防災課長","answer":"あくまで同行避難をまずできる限り進めていくというところを念頭に、進めていくのがよいのではないかなと考えているところです。ボランティアの方が来られた場合というのも、区の職員のほうが受け入れ等の対応に従事すべく、考えているところです。","id":"exchange-053"},{"speaker":"安藤委員","kind":"質問","question":"２枚目のほうですけれども、この名簿の更新ということで、この名簿の更新というのは実際どのように行われているのか伺いたいと思います。それと、この避難所への避難にあたっての区職員のサポート、公助のかかわりというのはどのようなものがあるのか伺いたいと思います。","respondent":"中島防災課長","answer":"それを３年ごとに定期的に状況の確認等も行いまして、適切な管理を努めているところです。発災時直後にすぐ駆けつけられる、やはり地域の方々に共助の中でご支援いただくというのが一番よいのではないかというふうに考えてあります。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"この人員の振り分けというのですか、その判断というのですか、そちらはどこがどういう責任で行うのかというのをお伺いします。二次避難所・福祉避難所の備蓄や支援体制などは、実際に避難した後の態勢なども含めて今、どのようになっているか伺いたいと思います。","respondent":"中島防災課長","answer":"福祉部との連携も必要になってきますし、実際今、そこについては防災計画全体の中で考えていく必要があるというふうに考えております。区全体の備蓄の中でも対応するように考えておりますし、それぞれ備蓄についてはされているというふうに考えております。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問・要望","question":"その当事者がやはりその作成時に入って、その作成にかかわることが重要だという質疑もありましたけれども、私も非常にそう思うのです。障害をお持ちの方、ぜひそういった当事者参加を強めていただいて、こうした計画を具体化していっていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"町会長には名簿は行っているという理解でいいのか、町会長だけなのか、どうなのかというのも、改めて教えていただきたいなと。もめたことを思い出したのだけれど、今でもそんなことがあるのかなというのを、教えていただきたいと考えています。","respondent":"中島防災課長","answer":"３点目の、先ほど私の説明が不十分だったのですけれど、同意いただいた方を名簿に載せております。地域にこういう危険があるということを認識をしたり、実際の災害時にどういう行動をとればいいかというところも検証できるというふうなところです。","id":"exchange-057"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それからもう一つ、その制度の中でそれが必ずありますよというならいいのだけれど、施設入所されている方いるではないですか。登録している人だって、ご家族が「いや、その辺の部分はどうなっているのかというのを教えていただきたいなと思います。","respondent":"中島防災課長","answer":"施設入所につきましては、ちょっと私のほうが説明不足でございまして、施設入所をしていない１万５,０００人が対象ということになっております。施設に入っている方についてはその施設の管理者等がご対応いただけるというふうに考えているところです。","id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/733618?Template=document&Id=4286#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":49665,"voices":146}},{"id":"r02-20200226-9","meetingId":"r02-cm02","date":"2020年2月26日","dateIso":"2020-02-26","committee":"文教委員会","time":"午前１０時００分～午後 ２時１０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"令和元年度品川区教育委員会事務事業の点検および評価の報告書","agenda":"令和元年度品川区教育委員会事務事業の点検および評価の報告書","exchanges":[{"speaker":"横山委員","kind":"質問","question":"お伺いいたします。もう少し詳しく、どういった観点から見ていただいたのかというところの詳細な説明をいただけたらと思いましたので、まずそこからお願いいたします。","respondent":"工藤指導課長、有馬庶務課長","answer":"それだと通うのが負担になる可能性があるということで、今年度からは全校で実施すると。さらに、実際に参加した生徒からの意見や保護者の意見も総合しながら、改善できるところは改善していきたいと考えているところです。 幅広くコミュニティの部分、人間の形成で人とどう付き合うかという部分との兼ね合いも考えまして、今回はこの教授に依頼したです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"事務（給食業務）職員の定年退職に合わせた栄養士委託への切り替えが適当ということで、これがなぜ適当なのかということを伺いたいと思います。今後、各校に１人配置していくということで、各校に１人ですから、１つの部活を見るということになるのか。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"２校に１人ですので、ここに書かれてあります事務（給食業務）職員という形で、いわゆる給食に対応する職員の配置をしています。今、やっています栄養士の委託を拡大していくことが適当であるということで… 私からは、部活動指導員の現段階での活用状況についてご説明いたします。まずは今年度の４校から、各校１名は配置できるような方向を目指して、判断していきたいと考えているところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"確認","question":"今のところは単独でつけていらっしゃるということで、今後もそういった方向で全校配置をしていくというお考えなのかどうかも伺いたいのですが。今のところはやられていないということでいいのかという確認と、今後、どういった形でやられていくのかということをご説明ほしいと求めました。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"委託のほうが、今、事務でやっている人間よりも幅広くできるということはあります。逆に委託での栄養士を入れたほうが業務としての幅も広がるということもありまして、今後、切り替えが適当であるというご意見をいただいたものです。 今後もそのような形で柔軟に各校が対応できるようにと考えております。毎年、実施していく予定です。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"今、指導の、よりプロフェッショナルな仕方みたいなことを研修していくということなのですか。教育環境、学校の環境としてもいいと思うのですが、いかがか尋ねました。","respondent":"大関教育総合支援センター長、篠田学務課長","answer":"先ほどのプロの方のお話だけではなくて、指導主事による部活動指導のあり方という基本の大原則の部分についてはレクチャーも行っております。次年度はさらに自分の動作を映して活用できるアプリケーションを… 事務職員のいる学校に栄養士も配置を、というお話です。確かにそういう配置ができれば手厚い対応にはなりますけれども、各学校、今後も考えてまいりたいと考えているところです。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"学校給食のところで、１名と決定している理由を伺えればと思います。ご答弁でも、手厚くなっていいというお話だったので、そういった方向で考えていくということが必要なのかなと思うのですが、いかがでしょう。","respondent":"篠田学務課長","answer":"行政のする仕事ですので、理想は高く掲げたいとは思いますけれども、やはり予算等の制約等もありますので、基本的には必要な職員を最低限配置するということを考えているものです。","id":"exchange-005"},{"speaker":"塚本委員","kind":"質問","question":"２ページに、どこかに１つでも当てはまればということで選んで１２事業ということで、この４つの条件というのは毎回変わるのですか。１２事業に決まっているのですけれども、全体の数字か、事業数を教えてほしいと求めました。","respondent":"有馬庶務課長","answer":"選定事業の１番から４番に定めているものについては、昨年と同様、変化はありません。全体の事業は、教育委員会全体で１２７事業ですので、大体１割強というようなところです。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問","question":"ページで言うと１２ページ、９番目、今後の方向性として書かれています。この学校経営監等専門家というのはどういう人なのかというのが一つと、実地的に授業を見て、少し詳しく教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"２週に１回の巡回とはまた別の観点から、あるいは保護者から学校に対する要望が、その専門家を派遣するようなケースもあります。学校の取組が間違いではないという部分を、きちんと保護者に説明するためのアドバイスをいただいたりと、そのような活用をしています。","id":"exchange-007"},{"speaker":"塚本委員","kind":"意見","question":"訪問相談後の具体的な手だてが明確になるような拡充ということで言うと、今、助言に当たっていらっしゃる専門家の方々に一層、活躍というか活動、対応していただくのか、また違う方向性、違う形でという方向性なのか、その辺りを詳しくお聞かせほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"今後ともお願いしてまいりたいと考えていますが、民間の特別支援教育に携わる団体が、次年度よりスタートすると聞いております。その対応への可能性も検討しています。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"その派遣というのは、昨日も議題にありましたけれど、いわゆる介助員とか学習支援員とか、特別支援が必要な子どもということではなくて、教員の側に助言やサポートをするということで、民間からの派遣等というのがされていくということでよろしいか尋ねました。","respondent":"大関教育総合支援センター長","answer":"ちょっと説明が不足しておりました。それが適切であるかという部分を、また学校の立場からしっかりと助言をいただく必要が、今後は重要になってくると感じております。","id":"exchange-009"},{"speaker":"筒井委員","kind":"意見","question":"わかる、やはり「より広報・ＰＲ活動に力を入れ、多くの区民が図書館に足を運びたくなるような取り組み」というのが必要かと思うのです。多くの区民が図書館に足を運びたくなるような取組というのは、今後、具体的にはどのようにお考えになっていくのかをお知らせくださいとの意見を述べました。","respondent":"横山品川図書館長","answer":"少しでも足を運んでいただくために、イベント等を行い、イベントの周知を行うような形で呼びかけをしています。親子に興味を引くような取組など、電子書籍ほかの新しい媒体についても注視して、取り入れるような形で工夫してまいりたいと思っているところです。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"現在、広報の手段としては、広報しながわなどに載せたりされているのでしょうか。その点をどのようにお考えになっているのか、お示しください。","respondent":"横山品川図書館長","answer":"ＰＲの仕方ですが、一般的になりますけれども、広報紙でお知らせするとともに、フェイスブック、ツイッターで周知を図っているところです。個々のイベントではないのですが、図書館のご紹介をしていただけるということで、さまざまな機会を捉えて周知に励みたいと考えています。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"非常に有意義なことかと思っているのですけれども、実施館が荏原図書館・八潮図書館・五反田図書館の３館だけになっているのはどういった理由なのか。今後も事業継続とさらなる充実が求められているというわりには、予算額が、これはどういったことなのかということをお伺いいたします。","respondent":"横山品川図書館長","answer":"一つひとつの開催について、すぐに館を増やしてというのがなかなか難しいところで、一つひとつ段階を踏んで拡充していきたいと考えています。平和３０年度と令和元年度の予算額なのですが、まずは小さく行うという、お金ではない事業というような形です。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"４ページの学校改築の計画的な推進で、どのような形で委員会などに報告がされるのか、どういった形でそれを知ることができるのでしょうか。各校に１名配置していただきたいと思っているというところからお尋ねします。","respondent":"若生学校施設担当課長、篠田学務課長、工藤指導課長、大関教育総合支援センター長","answer":"２０２０年ごろまでに個別の施設計画ということで策定を求められているものでして、今年度、検討を進めているところです。… 今後の方向性のところで、「予定受験者数の約８割」と書かれているです。これは平成２７年度から実施している事業でございまして… 英語力をつけるものに合わせながら、そういったコミュニケーションを図ろうとする態度の育成を狙いとして進めていきたいとも考えているところです。… ２点目、管理職の面接等も最終的にした上で、実際の任用に進めるというステップがあります。…","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"意見","question":"それぞれについては別の機会にお尋ねします。この数字について低いとお考えなのか、全員受験まで目指していきたいのかというところで、考え方といいますかとの意見を述べました。","respondent":"篠田学務課長","answer":"半分近くのお子さんが受けているという状況ですので、次年度、さらに引き上げられるように働きかけは続けていきたいと考えているところです。","id":"exchange-014"},{"speaker":"せお委員","kind":"質問","question":"その方も別という認識でよろしいでしょうかということと、あと、これから人材もさらに必要になってくるかと思うのです。そちらの見通しなどはあるのかということをお聞きします。","respondent":"大関教育総合支援センター長","answer":"学習支援員等を派遣していただいている法人でも、今年度より研究所を立ち上げて人材育成をさらに図っているという報告も受けているところです。区としても、さまざまな関係団体との連携は今後とも図ってまいりたいと考えております。","id":"exchange-015"},{"speaker":"せお委員","kind":"質問・要望","question":"引き続き、特別支援教育のサポートに向けて、さまざまな連携をとっていただいて、広めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"委員会にも報告などなく、パブリックコメントなどもやらないということなのですか。そういったことをぜひやっていくべきだと思うのですが、いかがか尋ねました。","respondent":"若生学校施設担当課長","answer":"策定については今年度中にする予定なのですけれども、委員会等の報告についても、次年度改めて行うということで、今、検討しています。技術的な部分が多い計画でもございまして、特に外部等のご意見をお伺いするという予定はなく、事務局のほうで進めていきたいと考えています。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"できてから報告ということでは、意味がないとは言いませんけれども、検討段階のところで委員会に報告していただいて、パブリックコメント等をやっていくということが、より多角的な視点をもつことになるだろうと思いますし、いいものができていくと思いますので、ぜひそうしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"せお委員","kind":"質問・要望","question":"小学校、中学校のほうなのですが、これは１０月からのトータルで見てみると、第一日野小学校がとても多いと思うのですが、まず第一日野小学校の数が多い要因などがおわかりであれば教えていただきたいです。","respondent":"篠田学務課長","answer":"お１人がかかってしまうと、当然、感染が広がるということもあります。毎年、第一日野小学校だけが多かったということはありませんので、たまたま今回はそういった形で広がってしまったのだろうと認識しています。","id":"exchange-019"},{"speaker":"せお委員","kind":"質問・要望","question":"品川区でも予防でできることはやっていただきたいと思っているのですけれども、泡の石けん、アルコール消毒があったのです。そのように３つも要らないかなと思うのと、固形石けんは要らないかななどと私は思うのですが、そこのところが何かありましたらお願いします。","respondent":"篠田学務課長","answer":"学校によって対応は若干まちまちなところはあるのですけれども、そういった意味で、かなり重複しているようなところはあるかもしれません。そういったご意見等はさまざまあるかと思いますので、研究させていただいて、これから対応を考えてまいりたいと考えています。","id":"exchange-020"}]},{"id":"topic-02","title":"品川区子ども読書活動推進計画（素案）に対するパブリックコメント結果","agenda":"品川区子ども読書活動推進計画（素案）に対するパブリックコメント結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"区としての、教育委員会としての受けとめというのですか、伺えればと思います。そういった理由、違いというのも伺えればと思います。","respondent":"横山品川図書館長","answer":"個々の実施事業のレベルでは明確にすべきだと思いますが、このような形で、すべてのファクター。学校図書館運営支援スタッフの増であるとか、学校図書館運営支援スタッフについては、方向性を示した抽象的な回答になっているところです。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"個々の事業のレベルというお話だったので、計画は全体としてというのは確かにあるとは思うのですが、ぜひ今後しっかりと推進主体を位置づけて。その人たちが責任をもって、関係する皆さんと一緒に進めていくということになると思いますので、そういった形で進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"おくの議員の一般質問の教員のところで、病気休暇取得者と病気休職者の年代別人数、あと精神的理由のところの内訳についてほしいと求めました。","respondent":"工藤指導課長","answer":"１６名の内訳の詳細について、あとは適応障害、ほぼこの２つがあります。そういうことで、お答えできるところでは以上です。","id":"exchange-023"},{"speaker":"のだて委員","kind":"確認","question":"長時間労働の影響で、また、あまり経験のない若年層の方が負担が大きいのではないかということで確認させていただきました。２０代は４人で、３０代は６人ということで、認識というのはいかがか尋ねました。","respondent":"工藤指導課長","answer":"やはり２０代、３０代が多くなっているというところから、比率は高いものとは考えてあります。これからも、すべての世代において、働き方改革は進めていくことが大事であるという認識をしています。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"平均で１１時間半とか、約１２時間労働ということになっていますし、作業を削減して。ぜひ働き方改革を含め、長時間労働を是正していってほしいと求めましたが、最後にご答弁をお願いします。","respondent":"工藤指導課長","answer":"ご指摘いただいているとおり、やはり業務量の削減。具体的に取り組む業務を削減していくなど、学校とも連携しながら、働き方改革はさらに進めていきたいと考えているところです。","id":"exchange-025"},{"speaker":"せお委員","kind":"質問","question":"簡単に見てみたのですが、ないような気がして、そういうものは入れたりはしないのか尋ねました。","respondent":"廣田子ども育成課長","answer":"こちらはパンフレットという形でお渡ししているのですけれども、登録用紙の中に、特殊な事情や配慮が必要な事情を書いていただく欄がございまして、それをいただいて面接をするという形で、個別に対応しております。","id":"exchange-026"},{"speaker":"せお委員","kind":"質問・要望","question":"まだ私の周りなどでも、すまいるスクールにはどうせ入れないのでしょう、入れてもらえないのでしょうと思っている方が結構いらっしゃるのです。そういった感じで、まだ理解が浸透していない方もいらっしゃるので、少し加えていただけたらというのを要望したいと思います。","respondent":"廣田子ども育成課長","answer":"では、今年度に関しましては、これから保護者会、説明会等で丁寧に説明させていただきまして、パンフレットの中にどんな形で入れるかについては持ち帰らせていただこうと思います。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"新型コロナウイルスについてなのですけれど、これから３月には、幼稚園、小・中学校の卒業式、４月には各校の入学式など大きな行事もあり、また当然、普通の授業もやられていると思うのですが、教育委員会としては、新型コロナウイルス感染症について、現時点で何かお考えや対応策はあるのか尋ねまし…","respondent":"新妻委員長","answer":"筒井委員、恐れ入ります。ただいま、すまいるスクールについての説明に関して話をしていただいておりますので。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"そうですか。では、すまいるスクールに関してはないのですけれど、別途、その他として発言します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問","question":"東京都教育委員会で何がどうとか、今、お話があった対応をしようということになったのかというのが一つ。休校になるなどというのを、またそのときに（判断する）、という認識でよろしいか尋ねました。","respondent":"中島教育長","answer":"昨日、校長会とも臨時の会を開きまして、対応……。その学校は休校体制をとって、臨時の対策会議を開く形になろうかと思いますが、その場合に区内全校を休校とする可能性もあるかなとは思っております。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"そろそろご案内状をいただく時期だと思うのですけれども、やり方などは案内状に記載していただけるのですか。今後の我々議会向けの周知などは。","respondent":"中島教育長","answer":"従来どおりの、ほぼ２時間かけて行われるような長い時間の、義務教育学校ですと全児童・生徒が参加してという形は難しいだろうと考えております。もしご来賓の方のご入場ができなくなりましたということになれば、再度、ご連絡が行くような形になるかと考えています。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=4994#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":33707,"voices":111}},{"id":"r02-20200226-5","meetingId":"r02-cm02","date":"2020年2月26日","dateIso":"2020-02-26","committee":"総務委員会","time":"午前１０時００分～午後 ２時４５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を78件整理しています。","topics":[{"id":"topic-01","title":"令和２年度都区財政調整","agenda":"令和２年度都区財政調整","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"冒頭、児童相談所の関係で割合が５５.１％だというご説明がありましたが、今回の合意について区の評価を伺いたいと思います。本来財政調整で見られるべきものが、区や２３区長会などはどのような見解を持っているのか、あわせて伺いたいと思います。","respondent":"品川財政課長","answer":"先行３区が運営費等として出している額で、そういう中でいろいろ交渉があった中では０.１％ということになっておりますが、０.１％となったです。まだまだこういう需要額については、来年度の財調交渉でもやはり東京都に対して言っていきたいと考えております。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"どのような見通しを持っているのか伺いたいのと、今のところはこういう若干増額で推移しているものの、今後はどのような見通しをされているのか。一般論で言うと、オリンピックが終わるとどうなるのかという声がよくあるだけに、区としての見通しについて伺いたいと思います。","respondent":"品川財政課長","answer":"どうなるかわかりませんが、東京都の来年度の見込みとしては、固定資産税は増額という形で今のところは見ているです。ですので、ある程度固定資産税のほうは安定的に動いてくるのではないかと今のところは考えております。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えばこの再開発や道路などのインフラ整備、地方から都市部がどう見られるかという点の改善につながっていかないのかなと私自身は思っております。新規算定項目１５項目、ぜひそこを改善していただきたいということと、この１５項目と２１項目とは何かということを質問したいと思います。","respondent":"品川財政課長","answer":"それからあとは自転車駐輪場の整備とか、それから介護人材とか、そういったところあたりが新規の算定項目となっております。それからあと予防接種関係が載っておりますけれども、あとは外国人の生活支援とか、そういったところあたりが算定項目の改善等となっています。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"この委員会資料はプレスの報告だということですけれども、やはりいわゆるその他の部分についても資料にしっかり載せてほしいと求めました。新たな財源を区政にどう生かしていくのか、区民にどう生かしていくのか、ぜひそこは改善していただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"４ページにも、あと、この「再算定するものとする」とあるこの再算定とはどのような算定なのかというところを伺いたいのです。","respondent":"品川財政課長","answer":"１つ目ですけれども、例えば間伐材等を使った事業等、そういった事業をいろいろ進めているところです。その後、これは８月時点から少し変更になるとか金額が変わるとかいった場合について、また各区に財政調整を配分していくというような考え方です。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"２つ目のほうです。この森林整備等は、森林環境譲与税とは別で、森林環境税に関係するといったことでよろしいか尋ねました。","respondent":"品川財政課長","answer":"森林環境税というよりも、今、森林環境譲与税のほう、歳入のほうの部分でいろいろと動いているというところがありますので、基本的にどちらかといえばその後者のほうを指すかと思います。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"森林環境税と森林環境譲与税の違いというか、それぞれのご説明をしていただきたいのですけれども、よろしいか尋ねました。","respondent":"品川財政課長","answer":"そちらが森林環境税です。森林環境譲与税というのは、その取った金額から、国のほうから各自治体に配分されるという金額のことを申します。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"そうなってくると、品川区がもっと一般財源の中で独自にできる政策がふえてくるわけじゃないですか。というふうに財政調整を見ていかなくてはいけないのかなと私は思うのですけれども、その辺はいかがか尋ねました。","respondent":"品川財政課長","answer":"考え方としては一致しているという部分の中で、配分割合のほうも少し東京都も考慮したというところでの特例的対応という言い方になっているかです。それから４番目、例えば令和２年度予算ですと…","id":"exchange-008"},{"speaker":"西本委員","kind":"確認","question":"よくしようと思って２２区は手を挙げているわけですが、お金の財源のところもサポートしてほしいというのは、引き続きお願いしたいところがあります。品川区で、その分財源が出てくるので、そこの確認だけお願いします。","respondent":"品川財政課長","answer":"ですので、あくまでもその区の中でかかった費用がそのまま返ってくるというものではないということは一つの考え方としてあります。そういう中でやっていきながら、そこで足りない分を例えば補正するとか、そういう考えは基本的にはございません。","id":"exchange-009"},{"speaker":"西本委員","kind":"提案","question":"そういう使い方をしてほしいと思いますので、もちろんその要求はこれからどんどん言っていただきたいと考えていますので、よろしくお願いいたします。やっていないところがあったら、何か考えて事業を展開してみたらみたいな提案がいろいろできるかと思うので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"だったら、そしてさらに今までこれは都が取っている分があるわけですから、何か随分ずるいやり方かなと。いや、その分は区で持ち出しなんですというのは何か不合理な気がするのですが、その辺についてちょっと聞かせてください。","respondent":"品川財政課長","answer":"そういった中で、今の建設単価等の動きにはやはりなかなかついていけないというところも現状としてあるかと思います。そういった部分もとにかく少しでも算定されるように、やはり毎年度我々も東京都のほうに要望していきたいと考えています。","id":"exchange-011"}]},{"id":"topic-02","title":"広報紙のリニューアル","agenda":"広報紙のリニューアル","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"なので、どういう団体でどういうことをやっていて、やりますというような情報を募集するという仕組みもぜひつくってほしいと思うのです。プッシュだけではなくて、受けるという仕組みをぜひ広報紙の中でやれたらありがたいなと思いますが、いかがか尋ねました。","respondent":"木村広報広聴課長","answer":"今は実際年に１回、そういう点についてはぜひ参考にさせていただきながら、どのように取り上げていけるか考えていきたいと思っています。今、ピックアップをするという形でご紹介をしていけるようなことは考えられるかなと考えていますので…","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"この２番目のほうの協働団体といういろいろ地域で活動されている団体の方々は、宣伝してほしい団体の方だと思うのです。ぜひそういう窓口をしていただいて、つながりがつけられるような状況で、ぜひ今後考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"現状において、例えばどういう分野やどういう施策について浸透していないというふうに課題として捉えているのか。今後どこを改善させたいと思っているのか、その事業を教えてほしいと求めました。","respondent":"木村広報広聴課長","answer":"既にケーブルテレビの番組で、昨年度から実施しているのですけれども、「こんなときは区役所へ」という番組をつくっております。区民の方のためにこういうサービスをやっていますという、いわゆる経常的にやっている部分をわかりやすくご紹介するということを考えております。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"確かに今ホームページを見ると、区が知ってほしいことが先で、区民が知りたい情報になかなかたどり着かない。時期の問題では保育園の入園、また児童手当等々、改めてそこをお伺いしたいと思います。","respondent":"木村広報広聴課長","answer":"ホームページのたどり着きにくいというあたりの部分も、これは今検討をして、来年度やっていこうかなと考えております。広報紙については、いつもそういう視点で紙面構成をしていくというような姿勢で考えてまいりたいと考えています。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"月３回発行している中で、何か地域だったり赤ちゃんだったり、私はそれはそれでそういう要素があってもいいと思っているのです。今月の２１日号には誰々さんのうちの赤ちゃんが載るらしいよという話題になってくると、全部堅苦しくやっていたら手にとりませんから、いかがか尋ねました。","respondent":"木村広報広聴課長","answer":"例えば１面もそうですけれども、スタンドに差さっているところで、ぱっと見てあっと思わせていく。まだトライの途中なので、そこからの一つ誘引という、中身を見てみようかというところへもつなげてまいりたいと考えております。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後ですけれども、私は２７歳で区議会議員に当選して、それまで区役所が何をしている場所というふうにあまり考えたことがなかったのです。逆の言い方をすると、これだという答えを何か持っているわけではありませんが、ぜひさまざまな工夫を進めていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"須貝委員","kind":"提案","question":"これも入れてほしい、Ａ４判の冊子にして、おそらくあれは中で構成するのも大変な仕事だと思うのです。区に求めている人は求めているし、また探す人は区に聞いて探しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"今後紙面のリニューアルを行うということで、紙面の大きさだったりとかも変わるのかというところを確認したいです。フォントが変わるのかなというのも確認したいのと、あと、それぞれのフォロワー数とかがもしわかったら教えていただきたいです。","respondent":"木村広報広聴課長","answer":"それから、中のフォントそのものに大きく変更はないのですけれども、そういうより見やすいような形に紙面構成をしていこうかなと考えています。それからフェイスブックがフォロワー数２,７９１人です。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問","question":"フォントのところにかかわると思うのですけれども、さまざまな立場の人が情報を手にとれるように、障害のある方たちでも読むことができる。そういった方たちにＱＲコードとかで、ここから読めますよといったような案内がもしできればと思うのですが、それについて伺いたいと思います。","respondent":"木村広報広聴課長","answer":"どなたでも見やすいような、あと、色についても色覚はどなたにとっても見やすいような色の構成にしているというところはあります。今は全部ではないのですけれども、一部ではそちらに誘導するというような形でやっておりますので、引き続きそういう形で進めてまいりたいと思いま…","id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"漢字が読みづらかったりとか、そういうインクルーシブな社会を品川区から実現できるようにといった観点で、ぜひ求めてほしいと求めました。その当事者の方たちに意見を聞くといったことをぜひしてほしいのですけれども、そのことに関して何か考えがあれば伺いたいのですけれども。","respondent":"木村広報広聴課長","answer":"ご覧になる方どなたにとっても見やすい、わかりやすいというところは追求しなければいけないところではありますので、どういう形でというのはちょっとありますけれども、研究してまいりたいと思います。","id":"exchange-021"},{"speaker":"大倉委員","kind":"質問・要望","question":"これは（１）の1)の「イラストを効果的に使用、直感的に理解できる構成」、何かそういう専門的な知識を持った方がやられるのでしょうかということ。すごくかわいい子が１面にいて、富山県でしたか、そういったところについての考え方を説明を求めました。","respondent":"木村広報広聴課長","answer":"印刷業者に委託している中、わかりやすいようにデザインをして、その中身を校正しながら進めていっているというような仕事の進め方をしております。こちらについても基本的にこのリニューアル後も引き続きそのような形でやっていきたいと思っています。","id":"exchange-022"},{"speaker":"小芝委員","kind":"質問・要望","question":"昨年の１０月に行政視察をしました松阪市では、やはり品川区もこれまでたくさん広報、媒体を使ってたくさんボールを投げてこられたと思うのです。そういった広報のあり方を考えてつくってほしいと求めましたが、そこら辺のご見解をお伺いしたいと思います。","respondent":"木村広報広聴課長","answer":"そういうところで、もちろんご許可をいただいた上ですけれども、とり上げさせていただいているところではあります。埋もれた対象へというところで、スマホへの発信であるとか、そういう形からの誘導といった形を引き続き進めてまいりたいと考えています。","id":"exchange-023"},{"speaker":"つる副委員長","kind":"確認","question":"まず１点ちょっと確認で、デザインフォントをやっていますというのですが、紙媒体についてはそうなっているという理解でいいのですよね。そういうのを含めてもう既に紙媒体も、それからデジタルブックのほうも、そういう採用になっているという確認をまずさせてください。","respondent":"木村広報広聴課長","answer":"ユニバーサルフォントでまた別途、ロゴとはまた別に出しているところもありますので、そちらで認知していただけるようになっていると考えています。","id":"exchange-024"},{"speaker":"つる副委員長","kind":"質問","question":"今回リニューアルということの報告なのですが、今回２１日号に１日号から移行させて充実させるということは、これまで２１日号で組んでいた企画がまた別のところに行くのか、それともいろいろな意味で見直すのかということがあると思うのですが、その辺簡単に説明を求めました。","respondent":"木村広報広聴課長","answer":"どちらかというと見直すというようなところです。区の施策、それから魅力というあたりをばっと表に出していきたいというところでございまして、基本的には見直していくという考えです。","id":"exchange-025"},{"speaker":"つる副委員長","kind":"確認","question":"所管事務調査のほうで確認する部分もあるとは思うのですが、世論調査で見ても年齢層の高い方、ターゲットに対していろいろ工夫をしていく。という思い切った判断、コレクトしてもらうという部分のところの考え方を説明を求めました。","respondent":"木村広報広聴課長","answer":"ただお伝えしていくほうの責任として、これからもちょっと継続はしていきたいと考えていますので、これからも工夫してまいりたいと考えています。そういうところも入れながらというところで、手にとっていただきやすい表紙をこれからもつくっていきたい…","id":"exchange-026"},{"speaker":"つる副委員長","kind":"質問・要望","question":"今、月４回発行している自治体もないことはないという中では、これまで区の中で検討がされたかどうかということだけを教えていただきたいのです。例えば月４回にしたときに、その辺がわかれば、簡単で結構なので説明を求めました。","respondent":"木村広報広聴課長","answer":"もちろん今までもそういう形での検討はしてまいっておるところでの今の現状というところでございまして、現状、やはり今も月３回だけではなくて。そういう中でのせめぎ合いの中でやっているところでございまして、引き続きそういう部分は検討しながら進めてまいりたいと思います。","id":"exchange-027"}]},{"id":"topic-03","title":"新型コロナウイルス感染症の対応","agenda":"新型コロナウイルス感染症の対応","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"４つ目の積極的疫学調査の実施というところで、検体搬送の回数の合計が６回というのは、これは感染ということか尋ねました。","respondent":"立川総務課長","answer":"そうではございませんで、いわゆる検査をそれぞれ行いまして、ある程度の数がまとまった時点でいわゆる車で搬送した、その回数がこの搬送回数です。","id":"exchange-028"},{"speaker":"小芝委員","kind":"質問","question":"そうすると、今の時点で区内での保健センターを通じた検査での感染というのはあるのかないのか、説明を求めました。","respondent":"立川総務課長","answer":"その辺の発表というのは東京都の専管事項でございまして、いわゆる各区において感染者がいるとかいないとかいう発表はできないという状況です。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"地方自治体として何がどうできるのかというところなのですけれども、幾つか伺いたいのは、そのメンバーをご説明ほしいと求めました。さまざまな英知を結集して、どういう対応が必要なのかというのが求められると思うのですけれども、ご説明ほしいと求めました。","respondent":"立川総務課長","answer":"本部のメンバーですけれども、まず本部長としまして区長です。それから、副区長、教育長、それから各部の部長、それから総務が事務局ですので総務課長、それから品川区保健所、また保健センターの各課長等です。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、一体どうしたらいいのですかというのが今の区民でもあり、また私自身の率直な思いなのです。質問としてはどうしたらいいのか、ぜひいろいろさまざま整理した上で区民に情報提供していただきたいと思っているのですけれども、いかがか尋ねました。","respondent":"立川総務課長","answer":"区からの情報提供につきましては、国と都等の情報等を収集いたしまして適切に対応していますので、いわゆる国や都、また他自治体を差し置いてというか、そういったところの情報を得ずに区が独自に何かを発信するということは実施しないです。","id":"exchange-031"},{"speaker":"中塚委員","kind":"意見","question":"既にドラッグストアには長蛇の列ができ、マスクや消毒液は本当に必要な人が手に入らず混乱している状況が品川区内でもよく見かけます。さまざま今後さらに厳しくなることもあり得るかと思いますが、区議会も含めて全力でこれを乗り切っていきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"保育園、幼稚園、児童センターなどの子どもたちが長くいる環境の中での対応という部分が書かれていないのです。ホームページだったりとかＳＮＳへの発信などもしてほしいということを求めたいので、その辺の検討はどうされているのかというところを伺いたいです。","respondent":"立川総務課長","answer":"委員ご指摘のところですが、基本的な通知につきましては、いわゆる紙媒体等で皆様にお送りしています。全庁的にどういった内容でホームページ等に上げられるかについては、ちょっと検討してまいりたいと思います。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"通知が出ているので、ぜひ保護者の方たち、今どういう情報が発信されているのかというところがわかるような情報提供をしてほしいと求めました。そういったところでの発信も必要かなと思うのですが、その辺についてもお知らせほしいと求めました。","respondent":"立川総務課長","answer":"児童センターの対応につきましては、詳細につきましては現在検討中です。パパママ応援アプリにつきましては、ちょっと所管のほうから情報をいただいておりませんので答弁は控えします。","id":"exchange-034"},{"speaker":"西本委員","kind":"確認","question":"２５日が区立保育園・幼稚園という形になっているのですけれども、これは内容は同じものなのでしょうか。そこを確認させてください。","respondent":"立川総務課長","answer":"日付が離れているものにつきましては、内容は異なります。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"では、私立保育園についてはダイレクトに情報が行かないからということで、区が関与したということですか。同じぐらいの時期ですから同じだと思うのですけれども、なぜこのようにばらばらになっているのか、なぜ一気にできないのか尋ねました。","respondent":"立川総務課長","answer":"いわゆる２月の後半に出した内容につきましては、ほとんど同一のものです。保育支援課の判断というのが多少異なるところがございまして、保育課は２月２５日に国の基本方針を見てから保護者に通知を出そうということで。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"そこでなぜ所管の対応という判断に任せることになるのですか。それは今後のこともあるので、しっかりとしていただきたいのですが、いかがか尋ねました。","respondent":"立川総務課長","answer":"新型コロナウイルス感染症対策本部では、区として全体の方向性等を決定していますが、各通知等につきましては、各所管の判断で実施しているというものです。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"そして通知はいつ発信をして、いつ届けられるようにするのかということは本部で決めるべきことではないのですか。そうしなければ、危機管理はできないのではないのか尋ねました。","respondent":"立川総務課長","answer":"いわゆる例えば保育園の保護者向け、幼稚園向け、区立学校向け、すまいるスクール向け、こういった内容につきましては、いわゆる本部会議の方針に沿って各所管のほうで判断するというものです。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問・要望","question":"感染症などは特にそうだと思うので、それは徹底してほしいと思います。そういう現状を、そういう仕組みはできているのか尋ねました。","respondent":"立川総務課長","answer":"基本的な発信の内容につきましては、区のホームページ等でも各個人個人がどのような対応をすればいいのかというのは、既に周知しています。区として情報収集手段等があるものについては、どういった形で情報発信するべきかということを今後検討していくべきかと考えるところです。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"ではその借りている会議室のお金はどうなるのですかといったときに、半分しか返されないのです。それをどうされるのか尋ねました。","respondent":"立川総務課長","answer":"各保健所の情報というのは、いわゆる情報を東京都と共有するという仕組みは既にでき上がっていると考えているところであります。こういったご意見があったということで所管のほうに伝え、また区としての方針を近々に決定していく必要があろうかと考えているところです。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区としてどういう状況かという情報はもらっているという理解でいいですかということを、もう一度確認したいのと、これは意見ですけれども。なので、早急に指示を出していただきたいとお願いしたいと思います。","respondent":"立川総務課長","answer":"いわゆる品川区保健所の情報というのは、東京都のほうですべて吸い上げます。それで、東京都内の全状況というのは、東京都のほうがホームページ等で日々更新している状況です。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"ただ、品川区の現状は品川区で情報収集して、承知しておかないといけないのではないのですか。そういう仕組みはあるのですか、ないのですかというご質問です。","respondent":"立川総務課長","answer":"いわゆる感染者が発生した、または疑われる方が発生したというのは、国・都の方針としまして、本人または家族のプライバシーにかかわる部分でありますので、その辺の情報発信については各地域の自治体はしないということになっているです。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"結論ですが、そうなると、感染状況、ほかにもあるかもしれませんけれども、保健所で把握した情報というのは、品川区には報告することがない。品川区自身も品川区でどれだけの感染者がいるのかということの承知はできないという仕組みになっているという理解でいいか尋ねました。","respondent":"立川総務課長","answer":"いわゆる感染情報というのは、東京都全体の中で各保健所がございまして、その各保健所の情報が都全体の情報となります。品川区は保健所を持っておりますけれども、その品川区保健所の情報が、区の情報として正式にもらえるという仕組みにはなっておりません。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"もやはり品川区は区民を守っていかなければならないという使命がありますので、できる限りのことを、これはそれしか言いようがないですね。今後の課題として、やはり共有関係が必要なのではないかということぐらいはぜひ言ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"須貝委員","kind":"質問・要望","question":"結局これは平日の９時から５時までは対応しますと書いてありますけれども、では土日祝日は病気が発症しないのですか。やはり区民が頼りになるのは区ですから、区としてやはり区民の命と健康を守るということをここでしっかり明確に出していただきたいと私は思います。","respondent":"立川総務課長","answer":"それから、相談センターですが、基本的な考え方ですが、平日の９時から１７時については各区の保健所が対応するです。職員の発症ですが、国の基本方針等で示されておりますとおり、人事所管と連携して推進していく必要があるのかなと考えているところです。","id":"exchange-045"},{"speaker":"須貝委員","kind":"質問・要望","question":"区のほうでマスクなどを非常用で保管していないのですか。買えないから、していないのかどうかわかりませんが、やはり職員の方にもちゃんとマスクがあるのかという確認はしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういった消毒液の配布が可能なのかどうなのかと、例えば呼吸器疾患等のこういったマスクが今必要な人たちへ優先的な配布ができるのか。そういった必要としている方たちが情報を求めそうなところ、そこについてまずお聞かせほしいと求めました。","respondent":"立川総務課長","answer":"数カ月後に納品ができる見込みであるといった回答をいただいているところですので、区としましても今後いつ再調達ができるかわからない状況です。そういったことで、区としましては積極的に進めていく必要があるのかなと考えているところです。","id":"exchange-047"},{"speaker":"大倉委員","kind":"質問・要望","question":"イベントへの貸出ということなのですが、裏面の主な中止をしたイベントということで、これは本部が判断するのでしょうかというのを教えてください。その貸出しについては、消毒液も今出回らなくて数が限られているというところでは、その辺の考え方について説明を求めました。","respondent":"立川総務課長","answer":"こちらは基本的には主催者の判断でですけれども、当然区としましては、相談があれば一緒に考えていきたいです。いわゆる消毒液だとか、細心の注意を払って開催してもらうということを、区としてはその辺をアナウンスしていかなければいけないと考えています。","id":"exchange-048"},{"speaker":"大倉委員","kind":"質問","question":"やる予定があるのかどうかも含めて、そういった動きをどのように把握されているのかということを教えてください。その新型コロナウイルス感染症対策本部会議もいつまでにというところと、イベントは今後の動きによってなのかどうか説明を求めました。","respondent":"立川総務課長","answer":"その間、大きな動き等がございましたら、前倒しで実施する予定になっております。現在のところ３月末までのイベントについて、４月以降につきましては、その辺は柔軟に対応していきたいと考えています。","id":"exchange-049"},{"speaker":"大倉委員","kind":"質問・要望","question":"今本当に周りの方で３７度５分あるのだけれどもどうしたらいいのだろうといったお話がたくさんある中で、今は相談件数がどのような状況なのか、相談窓口の状況がわかれば教えてほしいと求めました。","respondent":"立川総務課長","answer":"現状ですと、２月２５日までに合計で５１２件のご相談が寄せられているところです。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問","question":"湖北省および浙江省からの帰国者との接触で３７度５分以上ということなのですけれども、その表現は今はもうそういうことではなく感染が広がっているので、今後その部分はどうなっていくのかを伺いたいのですけれども。","respondent":"立川総務課長","answer":"感染の疑いということでは、また在住者や感染者との接触者で３７.５度以上の発熱および呼吸器症状がある児童・生徒ということで定義しています。当然国等の判断が変われば、区立学校からの保護者あて通知等もまさにこれで発出する必要があると考えているところです。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問","question":"では、その国の判断が変わらない限りは、帰国者と帰国された方たちなどとの接触がない以上は、その家庭の判断と学校での判断になるというところでよろしいか尋ねました。","respondent":"立川総務課長","answer":"そういったことについて情報提供したところですので、委員ご指摘のそういった判断基準の変更等につきましては、今後また適切に対応していくです。","id":"exchange-052"},{"speaker":"つる副委員長","kind":"確認","question":"幾つか確認で、いろいろ今質疑があって、区で発信できないこととか情報制限とかあって、今ネット上の話が先ほどありました。このあたりを説明を求めました。","respondent":"立川総務課長","answer":"国や東京都の最新の情報につきましては、適宜区内の各機関に情報提供しています。いわゆる期限つきで何かを実施しなければいけないということで、こちらは現状、今後検討していく必要があるかなと考えているところです。","id":"exchange-053"},{"speaker":"田中委員","kind":"意見","question":"湖北省、浙江省の方との接触がない限りは検査はできないのか、それとも検査はできるのか。その検査できるところは、この品川保健センターだけなのかとの意見を述べました。","respondent":"立川総務課長","answer":"これは従来の基準を一部改定したところでございまして、内容といたしましては、風邪の症状や３７度５分以上の発熱が４日以上続いている。保健所が実施しております相談センターのほうにご連絡をいただくということで、これは全国的に統一された基準です。","id":"exchange-054"},{"speaker":"田中委員","kind":"質問","question":"その相談をして、やはり検査をしたほうがいいといったときには、その移動手段として、品川保健センターだと遠い方もいるので、その移動手段について伺いたいのですけれども。","respondent":"立川総務課長","answer":"相談の結果、感染の疑いがある場合には、専門の帰国者接触者外来をご紹介するですので、マスクを着用し、公共交通機関の利用を避けて受診してくださいといったことが今現状、皆様にお知らせしている内容です。","id":"exchange-055"},{"speaker":"田中委員","kind":"質問","question":"電車やバスは乗りませんといったお知らせがあるのですけれども、では、遠い方はタクシーに乗ることになったりするのかなと。感染を広げないための対策としての一文が何かもうちょっとあったらいいと思うのですけれども、その辺はどのように検討されているのか伺いたいです。","respondent":"立川総務課長","answer":"帰国者接触者相談センターの運営等、またそこからの指示につきましては国や東京都の情報に合わせて、改定する場合は皆様に周知する必要があるかなと考えています。","id":"exchange-056"},{"speaker":"田中委員","kind":"質問・要望","question":"情報発信について、本当に先ほどからいろいろな方からも意見があったので、わかりやすい、そしてどのような立場の方にでも伝わる周知方法、ＳＮＳの関係でもホームページでもそうですし、できる限りの発信をしてほしいということを求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"}]},{"id":"topic-04","title":"(4)固定資産税および都市計画税の軽減措置の継続","agenda":"(4)固定資産税および都市計画税の軽減措置の継続","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"それで、２ページ目の４番の耐震化のためのというところがあります。こちらからどれだけ要望を言えるのかなというところはあるのですが、この見通しで何かあれば教えていただきたいのですが、その辺はいかがか尋ねました。","respondent":"伊東税務課長","answer":"こういうことをもう少し継続していこうと思えば、また来年、再来年度も継続ということになるかと思います。現状では１年延長ということで今回発表があったということです。","id":"exchange-058"},{"speaker":"西本委員","kind":"意見","question":"これで大分進んでいるという部分もあるので、今後とも軽減措置というのはできる限りお願いしたいと思いますので、どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"須貝委員","kind":"質問","question":"これだけもうおそらく何年ですか。最初はこのまま本当に軽減措置がありがたくて続けてほしいという気持ちがありましたけれども、ちょっとご見解を説明を求めました。","respondent":"伊東税務課長","answer":"２３区に限ってはさまざまな特殊要因があるだろうというところの判断で、こういうような軽減措置をその都度その時々の状況に応じて判断されている。確かに委員ご指摘のとおり、継続はしているというところでありますけれども…","id":"exchange-060"},{"speaker":"須貝委員","kind":"意見","question":"意見だけ言わせていただいて、これだけ２３区、特に都心にどんどん人口が地方から流入している。そういうことも考えた上で、やはり固定資産税の見直し等も考えていただけたらありがたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"インスタグラムのフォロワー数がわかるようでしたらお知らせいただきたいというのと、目標とか、そういうものがもしあるのならば教えてほしいと求めました。","respondent":"木村広報広聴課長","answer":"効果検証ですけれども、１つは各イベントとか講演会で、そういうところを見たりというところで把握をしてまいりたいと思うところです。具体的な目標はまだちょっとこれから考えてまいりたいと思っています。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問","question":"シティプロモーションと切り離して、あとぼやっとこうしたときはどのような対応があるのかなというときに、よく整理された情報にたどり着くと。そうした視点が大事ではないのかなと思うのですけれども、重なる部分ありますが、いかがか尋ねました。","respondent":"木村広報広聴課長","answer":"そういう仕組みも取り入れながら、実際そういうところにちゃんとたどり着けたかどうかというあたりも把握していかなくてはいけないと思うのですけれども、しっかり考えてまいりたいと考えています。","id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"その月によってどういったことがあるのかとか、あらかじめ情報が整理できる部分はたくさんあると思います。明日以降ここから続けていきましょうねという対応をしているのを視察で確認させていただいたのですけれども、区役所と接する機会は少ないし。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"田中委員","kind":"意見","question":"若い世代に向けてということで、これまで若い世代、例えばこのしながわ未来トークの中でも、このようなＳＮＳとかをやったほうがいいとかいった意見があって、この今回の形につながったのか、その辺についてお知らせほしいと求めました。","respondent":"木村広報広聴課長","answer":"この２０１５年あたりからのＳＮＳの導入、展開というのは、そういう問題意識からスタートし始めたところです。議会の皆様からのこういうツールがいいよ、今ぜひ入れていくべきだよというお声も頂戴しながら、このツールを導入してきたというところもあります。","id":"exchange-065"},{"speaker":"田中委員","kind":"意見","question":"今のご説明だと、若い世代の方たちが本当によく目にするものだったりとか、身近に感じているものの調査というのがもっと必要なのかなということ。やはりその世代の方たちの声を聞く機会というのをもっと考えていかなくてはいけないと思ったのですが…","respondent":"木村広報広聴課長","answer":"大学連携の方々とのお話の中でもそういう話だったりとか、どういう情報が欲しいのか、何を使っているのかなというのをつかみながらやっているということはあります。","id":"exchange-066"},{"speaker":"西本委員","kind":"質問","question":"若い人たちにシティプロモーションという観点から言うと、何をしてほしいのか。何をしてほしいのか、何が若い人たちはしたいのかというのは受けとめられないのですけれども、その辺はいかがか尋ねました。","respondent":"木村広報広聴課長","answer":"皆にこういうことを教えたいというところでの自発的なというか、そういう部分を期待をしながらこういうツールを入れてきたというところもあります。情報の発信の主体、あるいはよさを知っていただくというような、みずからそういう主体にもなってもらいたいなという思いもありま…","id":"exchange-067"},{"speaker":"西本委員","kind":"質問","question":"シティプロモーションですから、シティーセールスですね。どのような障害者でも自己実現ができる、私も具体的にどうすればいいというのはないのですが、その考え方についてちょっとお聞きしたいと思います。","respondent":"木村広報広聴課長","answer":"そこに着目をしたような形で、個々いろいろな切り口から品川のいいところをＰＲできるように今いろいろやっているところですし、これからもやっていこうと思っています。","id":"exchange-068"},{"speaker":"西本委員","kind":"質問・要望","question":"ただのイベントというか、その後どうしているのか、それは品川区に根づいたのですか。もう少しそれも根づくような形で育てていってほしいと思いますので、期待を持ちつつ、改善をぜひしていただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"大倉委員","kind":"質問・要望","question":"こういうところなのだということを、この取組は非常に大事だと思っているので、しっかり進めていっていただきたいと思っています。そういった昔から住んでいる人、そういう特集号というのを含めた何かそういった取組はどうかなと思ったのですけれども、いかがか尋ねました。","respondent":"木村広報広聴課長","answer":"なかなかその紙そのものを手にとって見るというのが難しい中でという部分があるのです。委員のおっしゃるそういう観点はとても大事な部分でありますので、そういう場面も活用しながら、これからも進めていきたいと思っています。","id":"exchange-070"},{"speaker":"大倉委員","kind":"質問・要望","question":"若いと言っても２０代から４０代の人たちと、割と若い世代の人は情報自体を求めていたり、活動の場所を求めていたりしていると思うのですね。特集号というのはやはり難しいのですかというところを１点教えてほしいと求めました。","respondent":"木村広報広聴課長","answer":"何かそういうところをうまく連携・連動・参加、こちらから「どうですか」みたいな形で、そういう場面もいろいろ活用していきたいと思います。いわゆるご覧になりやすいような媒体、ツール、そういうもので何かそういうことを発信していけるような形を考えていきたいと思っていま…","id":"exchange-071"},{"speaker":"大倉委員","kind":"質問","question":"ほかの自治体とかでやっている、例えば一つ商店街というところで見ると、こういうお店があるのだなと商店街には行ってくれるかなと。そういう特集を組んで、そこに商店街のお店の何か提供品をつけたチラシみたいなものができたらおもしろいかなと思ったのですが、どうか尋ねました。","respondent":"木村広報広聴課長","answer":"先ほどのリニューアル紙面みたいなところでのまちの取り上げ方、商店街の取り上げ方みたいなところで、何かそういううまい仕掛けができるかどうか、ちょっとこれから研究していきたいと思います。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"改善点なり工夫点なり、またお互いが共有できたり、そういうことも必要かなと思うのです。すべてを広報に載せられるわけではないので、現状はどのようになっているのか尋ねました。","respondent":"木村広報広聴課長","answer":"それが一覧で見られるような、ホームページからのバナーをつくりまして、そういう仕掛けもやっているところです。それから、よりわかりやすく伝わりやすくというような事業も行ったりとかして、中身そのもののブラッシュアップもやっているところです。","id":"exchange-073"},{"speaker":"つる副委員長","kind":"質問","question":"今回シティプロモーションと若い世代への情報発信ということで所管事務調査をやっておりますが、そもそも自治体の広報の目的というのは何なのか、改めて説明を求めました。","respondent":"木村広報広聴課長","answer":"１つは、行政がどのようなサービスを提供しているか、あるいはどこで何をやっているかというあたりのお知らせをするというところが１つ。そういう区民の皆様とのコミュニケーションのツールということで考えております。","id":"exchange-074"},{"speaker":"つる副委員長","kind":"質問","question":"どうしても同じ媒体で、そこで提供されている中身は同じだから、やはり２度目はないというところがあると思うのです。どういう効果を期待して、若い世代にアプローチしているのか、説明を求めました。","respondent":"木村広報広聴課長","answer":"１つ例示としては何かの講演会事業に参加をしていただいて、自分でも何かをやってみようか、そういうようなご自身の行動につなげられるようなこと。行動としてつながるようなことを、これは私どもだけではなくて…","id":"exchange-075"},{"speaker":"つる副委員長","kind":"質問・要望","question":"先ほどほかの委員からもあったと思うのですが、そういう実際に区民の方が何を求めているのか、その頂点が一番すばらしい広報だと思うのです。そういった視点というのはどういう形になるのか尋ねました。","respondent":"木村広報広聴課長","answer":"繰り返しになってしまいますけれども、その方が次に何をしようか、コミュニケーションを広げていただけるような効果が出ればいいかなと思っています。漠然として申しわけないのですけれども、そういう形で考えております。","id":"exchange-076"},{"speaker":"つる副委員長","kind":"質問・要望","question":"だからそれが内向きの広報と外向きの広報という言い方になるのでしょうか、そういった本当にまさに魅力がある品川区だと思うのです。世代によって求めていることも違うわけですし、若い世代の人たちは入手しなくても、品川区で生活をしていただいているわけですよね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"須貝委員","kind":"質問","question":"ここまで品川区がシティプロモーションをやってきたのですから、もうそろそろどこかで終わるということも考えていいのではないかなと。意見だけ言わせてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2160#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":64523,"voices":183}},{"id":"r02-20200227-14","meetingId":"r02-cm02","date":"2020年2月27日","dateIso":"2020-02-27","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 １時４８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"これがつくられるということなのですが、これは五反田駅だけなのでしょうか。池上線のほかの固定式ホーム柵が可動式ホームドアに全部なると非常にうれしく思うのですけれども、その点いかがでしょうか、お伺いします。","respondent":"鈴木都市計画課長","answer":"午前中も説明がありましたが、やはり一定程度、固定式も安全対策はとられているものと認識はしておりますが。今日午前中はあのような説明でございましたが、やはりこれは順次しっかり可動式にしていただきたいとは、以前からですがお話はしています。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"どうぞよろしくお願いいたします。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"助成内容なども違ったら教えていただきたいです。主要駅というのですか、そのほかの駅がなかなか進んでいないと思うのですが、そこの理由などがあれば改めて教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"エレベーターの整備助成のスキームですが、基本的な考え方は国、地方公共団体それから事業者それぞれ３分の１というスキームは同じです。この整備が進まないというのは、先ほどご説明したように、路線が長いということで、ちょっと東急とはその辺で違うところがあったのかなです。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"車両の違いがあるということで、今、大阪のほうでロープ式の昇降型ホームドアというのですか。その辺の評価や課題は認識があるのでしょうかということを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"この鉄道事業者にはこのタイプが有効ではないかといった研究あるいは委託を使って検討することは当然可能ですが、それをまずやっていただくのは。ただ、主要駅の整備が進められてきていることを考えますと…","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こうした路線が長かったり、ぜひ積極的に進めていっていただきたいですし、区からも声を出していただけたらと思います。その後、京急との話の状況だったりとか、あとは変化があれば伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"これまでも京浜急行にはエレベーター設置についての要望、特に設置場所の用地的なところで非常に課題が多いというところでなかなか先に進まないです。もう１つはワンルートがもうほぼ都内全域で確保が終了したという中で…","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この特殊な駅等も含めてワンルートがあっても２ルート目も確保するための補助金は出すということで、あとは本当にもう京急次第なのだなと私も思っていますけれども、引き続きぜひ一緒に区からも声を出して求めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひこれも解消していくように働きかけていただきたいのですが、いかがでしょうかというのが１点です。３番目のこれまでの助成駅というところで、単純に山手線の駅は助成がなしで整備されたという理解でよろしいのか、それもあわせて伺います。","respondent":"鈴木都市計画課長","answer":"これは区としても認識してございまして、非常に１日全体の流れというか、どうしても優先順位的には後になってきているです。それから、山手線につきましては基本的には区の助成なしでＪＲのほうで進められたという認識です。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回、今回の東急新横浜線の整備に伴う目黒線の６両から８両の編成に増やすことの取り組みについてお伺いしましたけれども、内容は随分わかりました。そちらについて、品川区としては今回の８両化で問題が解消されるとお考えなのかどうか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"そういう中で車両が増えていくということは、物理的に本数も増えているということで、ある程度の効果はあると考えています。武蔵小山も人口が開発で増えてくるということがありますので、今後、東急ともより一層話をしながら混雑解消に向けて考えていきたいと考えています。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回さらに武蔵小山で２つの地区の再開発の準備組合等々が立ち上がっていると思うのですけれども、さらに追加される２地区が仮に建ち上がった場合、想定される増える住民の数を教えていただきたいのと、現状での武蔵小山駅の混雑問題への影響はどのようにお考えでしょうか、伺います。","respondent":"稲田都市開発課長","answer":"今、その中でいろいろと検討をされているところでございまして、何人ぐらいここで増えるかは区では今、現在詳細には把握していないです。ある程度の建物が建ってくるというところでは考えておりますので、まちの人口とか駅等の混雑も考えながら…","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"視察先で東急にもとりあえず当面の２棟のマンションの影響を伺ったのですけれども、その具体化なのだという説明もありました。そこら辺について、もう少し品川区としては把握と予測とそして抑制をしていくべきなのではないのでしょうか、伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"安藤委員","kind":"意見","question":"まちの課題解決をしながらと言いますけれども、集中的に人口が増える、超高層を建てるということで逆に新たな課題をみずから生み出してしまうということであれば、私はそういったものは見直すべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"こんの委員","kind":"確認","question":"今のところはここは１０万人以下のところなのでしょうか。それを１点確認と、まだそこら辺のところの動きがあるのかないのか、わかる範囲で見通しなど教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"いろいろな場面でこちらからもお聞きしているのですが、そうした回答は今のところない状況です。いろいろなところで整備を進めていく中で、優先順位をもって整備をしていくというところで、区としては受けとめているところです。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問・要望","question":"状況を確認しつつ進めてくださっていると思いますが、これからも引き続き状況を確認しながら、要請を上げていってほしいと求めました。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問","question":"未整備１６駅とあるのですけれども、予定の駅も何駅かありまして、こちらにつくホームドアというのは可動式か固定式かは、現在決まっている状況か尋ねました。","respondent":"鈴木都市計画課長","answer":"資料の４番目の何年度予定と入っているところにつきましては、可動式で設置がされるものと理解していますし、その形で進むと考えています。区の助成も基本的には固定式よりは可動式のホームドアを対象に制度的なものは構築していますので…","id":"exchange-014"},{"speaker":"せお委員","kind":"質問・要望","question":"ぜひ、区からもちょっと。確認されていないということだったので、一応、要望をぜひ出してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"}]},{"id":"topic-02","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"形を整えてまとめという書類につくり上げてほしいと求めましたので、見させていただいたところ、特に私は申し上げることはありません。これに沿って、今の委員長の発言のとおりで進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ちょっと確認なのですけれども、例えば庁舎のあり方については、まとめるということでさっき意見が。ちょっとそこの意味がよくわからなかったので、確認させていただけますか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"意見","question":"この庁舎のあり方に関することというテーマの中ではこういう意見が出ましたという意見は載せるということでいいわけですね。そういう意味でしたら、それでお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"確認","question":"今のところの確認ですけれども、いわゆる両論併記の形で意見をこういう意見が出たということを提出するということでいいのか、それとも今回の調査事項に関しては、何も提出をしないということなのか、そこだけちょっと確認をさせてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/988746?Template=document&Id=6084#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":14586,"voices":45}},{"id":"r02-20200228-18","meetingId":"r02-cm02","date":"2020年2月28日","dateIso":"2020-02-28","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午前１１時５０分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"観戦ツアーについてなのですが、これまで言われてきた、東京都のほうでこの観戦ができるという話があったと思うのですが、それと違うのか同じなのかということで、区の主催と書いてあるので、そこのところを確認させてほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"東京都のほうでの観戦というのがちょっとわからないのですけれども、この区の主催でというのは、区は自治体観戦チケットというのがありまして、それを購入をして、それを区の主催で区が募集をして、区民の方向けに観戦ツアーをしますというような取組みです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"学校とかでそういう話があったので、それは区が買ってやるというものだと理解をいたしました。最寄駅が利用できないとか、下見ができないという問題点が挙げられていたのですが、今の現在の状況を伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"先ほどの東京都での学校観戦プログラムという2)のほうが、東京都が実施しているツアーで、区が仲立ちをしているです。中の見取り図を見ますとこのような形で入るというのは、もう少し先になってから下りてきて、相談するようになるのかなと認識しております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり子どもたちですから、先般保育園についても、そういったプラスアルファでチケットを確保していくということでいいのかどうか。最寄駅が利用できないという話も聞いていたのですが、その点について何かご答弁あれば、伺えればと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そこはしっかり教育委員会等とも連携しながら、組織委員会とも話をしながら、万全の対策をとっていきたいと考えています。今の話も含めまして、いろいろな方面から検討して、最終決定はしていくようにしたいと考えています。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"万全の対策をしてほしいと求めましたし、やはりそういった中で、それを強制していくということはないようにしてほしいと求めました。このしな助の方々をパラスポーツにつなげることで、発展に寄与できると思うのですけれども、いかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ひょっとしたら出てくるかもしれませんし、その場合はその援助というか、実施する支援はしていきたいと思います。いろいろな形で、その方に合ったレガシーというか、続ける手助けをしていきたいと思います。","id":"exchange-004"},{"speaker":"小芝委員","kind":"確認","question":"２枚目の東京２０２０観戦チケットのところで、下記住所宛てにお申込みくださいというのですが、これはどちらの住所なのですか。確認だけちょっとお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"このはがきの絵のところです。おそらくこれは郵便番号が特定されていて、これでもうこの観戦チケットの事務局に届くような形になっているのかと思います。","id":"exchange-005"},{"speaker":"小芝委員","kind":"質問","question":"１の(1)の観戦ツアーのところなのですけれども、あと今後の一般区民向けのタイムスケジュールを教えていただければと思うのですけれども、お願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"数としてはオリンピックで最大で４００枚から５００枚ぐらい、それとパラリンピックのほうで２００枚から３００枚程度を要望しています。タイムスケジュールなのですが、皆様にきちんとご案内して…","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問・要望","question":"現在の登録は個人が５１１名、団体が２９団体ということなのですけれども、そういう活動の実際の状況というのはどのようになっているのかということをお知らせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ですので、実態として１回でも出たことがある方というのは、大体半数ぐらいと考えています。団体ｄｅしな助の方というのは団体で、そこにはたくさんの方が登録されていると思いますので、その人数で何とか賄えるかと考えています。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"チケットについて質問があるのですけれども、熱中症の恐れがあるから辞退する学校が多いという新聞記事を読んだことがありまして、品川区ではそういう東京都からの各学校に支給をされるようなチケットというのはあったのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"新聞等の報道で、やはり辞退される学校があるということは私も認識しております。品川区におきましては、今のところそういう辞退するという話は聞いていません。","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"それが、要はキャンセルになってしまったチケットも多分大分あると思うのです。そのチケットが、この区主催の大会観戦ツアーに回されるとか、そういうことではないのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"区民向けの観戦ツアーのチケットは、学校観戦プログラムとまた別のルートになっておりますので、余ったものが回ってくるという形ではないと認識しております。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問","question":"しな助が聖火リレーのときの警備にあたるということなのですが、その聖火リレーのときに、警察とか消防とか消防団とか、ほかに警備にあたる方で把握しているところを説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"プロの警備の人というのは、それは東京都のほうで手配して、警察も含めてそれはきちんとやります。はみ出ないでくださいというふうにおっしゃったりとか、そういった役割になるように東京都のほうから聞いております。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"まず区で今要望を出している、先ほど４００枚から５００枚とか２００枚から３００枚あると言ったのですが、その対象がどういう層なのか。たしか有償無償のどちらかという議論がかつてあったという記憶があるので、その辺を確認させてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"対象を特に限るということは今のところは考えておりませんで、平たく募集をして抽選等にしようかと今のところは考えているところです。それから有償か無償かということにつきましては、こちらは無償で考えております。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"区として要望を出しているのは、逆の意味ですね、室外もあると思うのです。そうすると、例えば暑さ対策のグッズとかが一緒に用意されているとか、そういったことも考えられているのかというのを説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"観戦ツアーにいらっしゃった方のグッズとかを配るかというお話なのですが、今のところそれは想定しておりません。お子様でしたら必ず保護者同伴ですし、そういった形で対応していただきまして、こちらのほうでそれを用意するような予定は今のところないです。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"4)のホストタウン向け、これは先ほど理解できなかったのですが、それからコロンビア共和国が出場するであろう競技ということなのですか。それとも、その方たちが見られるという意味だったのか、もうちょっと細かく説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"希望としてそれ以外のもできるようにはなっておりましたが、そこの市民だとか区民が買える、見に行くというようなチケットです。ですから、見に行く対象は品川でしたら品川区民です。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問","question":"まとめて聞けばよかったのですけれども、そうすると、その場合、その募集というか誰が行けるかというのも、先ほどの区民向けと同じような形で別枠で募集するということか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ですので、ちょっとこれは違う形にしようかと今検討中です。交流をした団体だとか、そのようなところとかがいいかと思ったりですとか、今検討中です。","id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで、この活動期間が２０２１年３月までということになっていますね。継続してやるのかということをお聞きしたいのと、1)イベント、ちょっとお聞きしたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"しな助は終わった後にそのまま続けるのかというご質問で、しな助自体も一旦解散となる予定です。ほかにも区内で幾つか期間中に開催するようなイベントもありますので、そちらのほうに配置というかお願いをしたいと考えています。","id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"全体として、今、品川区どこでもというようなことでお話をされているのかということを１点お伺いをさせてほしいと求めました。もし何かあったときの態勢、そこの責任がどこにあるのかということをお伺いをしたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"やはり今まで３競技中心に気運醸成を図ってまいりましたので、それを今度は実際に見るという体験をしていただきたいということで、要望しています。やはり聖火リレーの実施の主体は組織委員会と東京都ですが、こちらのほうは保険等のことについても品川区が持つことになっていま…","id":"exchange-016"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひ、チケットの応募に関しても工夫をしてほしいと求めました。今回の東京２０２０大会におけるこのしな助の団体２９団体、個人５１１名、何かそういうのはお考えがありますか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そのあたりをいろいろお話も伺いながら、どのような形がいいかというのは今後も考えていくことかと考えています。しな助という形でそのまま残してどこかが所管してやるというふうには、今のところは考えていないです。","id":"exchange-017"},{"speaker":"若林委員","kind":"確認","question":"ちょっと確認をさせていただいて、あと５１１名の登録の方のうち実質半数というところで、そうすると２５０名というところですかね。いわゆる屋外等で例えば何か区のイベントがあったときに、そういった形のレガシーというのは考えていないのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"これのレガシーとして考えるのは、それがまたいろいろな大会ですとか、連帯感が地域でできるのがいいのかなと思います。地域のほうからそういう声が挙がったりするといいかとは思っております。","id":"exchange-018"},{"speaker":"若林委員","kind":"確認","question":"ぷつっと切れる、糸が切れたみたいなふうにならないような考え方は持たれているのかどうかというのが１つです。特設なのでいわゆる施設としてはなくなるのですねという確認とか、あれは開発組合かな、そこら辺の考え方ももう一つ聞いておきたいなと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そういうところと連携しながら、どういった形でまとめていくのかというのは、庁内でも全体で考えていくところかと思います。ただ、そういったことは今後、オリンピック・パラリンピックが終わった後もいろいろな形で連携はできるのかなと考えています。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"１点だけ教えてください。皆様心配されているところなので、不確定情報が伝わってしまうとちょっと混乱が起きるのではないかなと思うので、その辺だけ確認させてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"これがいつごろ確定するかというのは、私のほうでもまだ把握はしておりません。それが学校や保育園から保護者に伝わるという形だと思いますので、引率する主体のところが発する情報が一番確実だと認識しています。","id":"exchange-020"},{"speaker":"吉田委員","kind":"意見","question":"その正式ルートから、きちんとその当事者のところに行くということですよね。だからそれまではあまり混乱しないようにではないけれども、そういう感じでもし何かご意見を聞かれれば、お伝えしていけばいいということですねとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"私も組織委員会に行っている職員から聞いたりですとかそういうことで、今は検討中というのが本当に一番の答えです。いや、でもそれはよくしようとか、正式ルートのほうの情報をお待ちくださいというふうにお答えいただきたいと思います。","id":"exchange-021"}]},{"id":"topic-02","title":"東京２０２０大会後の名称・設置物","agenda":"東京２０２０大会後の名称・設置物","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"銘板はこの別紙３のとおり、品川区の会場としては大井ホッケー競技場には銘板を置けるという理解でよろしいのでしょうか。潮風公園、この２カ所は銘板設置が認められているということでいいのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"銘板設置、東京都が設置するものの一覧が出ております。それから１１番の潮風公園、イメージとしては２ページのところにあるような形での銘板が設置されることになっております。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"先ほどオリンピック・パラリンピックの名称については、要望を出したけれども、頑張ったけれどもというところで、区としてはなかなか残念でした。一般質問でのご答弁でも、どこか１カ所とか複数箇所なのかとか、そのあたりの検討段階の状況を教えていただきたい。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それから公式練習会場もなる予定ですので、そういったものについて銘板を設置したいということで、現在申請はしています。まだ答えは来ていないです。","id":"exchange-023"},{"speaker":"つる委員","kind":"質問・要望","question":"当然それが認められるかどうかといった類いのものかとは思うのですけれども、そういう意味では幾つでも要望、認可されたものが設置される。１カ所だけですよということではないということですね。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員ご指摘のように、各区１カ所とかそういう決まり方ではございません。複数箇所申請して、それが全部認められる場合もあれば限られていってしまう場合もあるとは思いますが、当区も複数箇所で申請しております。","id":"exchange-024"},{"speaker":"つる委員","kind":"質問","question":"イニシャルのときには多分東京都等の、さっき補助対象となっていましたけれども、どーんと出てくる。その後のそれこそレガシーとして残す場合、維持管理というのは、その後は区が見ていかなくてはいけないというものか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらはおそらく最初の建てるときの補助もありますが、その後は区のほうで見ていくというふうに認識しております。","id":"exchange-025"},{"speaker":"本多委員","kind":"質問","question":"関連するのですけれども、この銘板の形状とか、何か決まりはあるのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ただ、それ以外のものとの同居が難しいとか、一緒の板に載せるのはちょっと難しいようには聞いておりました。例えばオリンピックのマークが入って、私どもの設置している３キャラが入るとかいうのは厳しいと聞いております。","id":"exchange-026"},{"speaker":"本多委員","kind":"質問","question":"聖火リレーの出発点とか、しながわ中央公園のゴール地点とか、そういったものも視野に入れているのでしょうか。それと、さっきも出ていたのですけれども、この補助制度の概要がもし今わかれば説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"銘板の設置について、聖火リレーの場所等についても申請をしております。それから補助制度は、すみません、今は何分の一とかという数字を持っておりません。","id":"exchange-027"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"若林委員","kind":"意見","question":"すみません。今、このオリンピック・パラリンピックに向けた区内会場とその準備に関しての今の対応等があれば、お知らせほしいと求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"東京都や組織委員会のほうから、まず特段連絡は来ていないところです。区としては、私どもの関連する事業といったものに関しては、３月いっぱいは中止や延期にしております。","id":"exchange-028"},{"speaker":"若林委員","kind":"質問・要望","question":"よろしくお願いします。いずれにしても区内２会場を含め日本全体で待ち焦がれた東京２０２０大会、ぜひ格段の取組みを進めていただきたいという要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"若林委員","kind":"意見","question":"さっきの発言で、しな助は無形レガシーではないですよねと言って、どちらかわからない状態なのですけれども、人間国宝は無形ですよね。委員会としてはそういうまとめの方向性なので、あえてちょっとそういうふうなのかなということで、先ほどの質疑も含めて訂正したいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/312568?Template=document&Id=6570#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":21630,"voices":80}}]);
